update content_bodies set title = '【絶景茨城】霞ヶ浦（かすみがうら）-帆引き船｜VISIT IBARAKI,JAPAN', description = '霞ヶ浦は日本で2番目に大きな湖で、茨城県全体の1/3以上の流域面積を持っています。冬には多くの渡り鳥が訪れ、平均深度は4mと浅いため、ワカサギやコイ、ハゼのほか、外来魚のブルーギルやブラックバスも生息し、全国から釣り人が集まります。また、150種の野鳥や水生植物が豊富に生息しており、自然が豊かです。夏には観光用の帆引き船が運航され、白い帆を張った船が湖面を進む姿は霞ヶ浦の風物詩となっています。' where id = 'o5GbdIEEuJOXdBfFMANaV';
update content_bodies set title = 'Kasukabe Lake - Sailing Boats | VISIT IBARAKI, JAPAN', description = 'Kasukabe Lake is the second largest lake in Japan by surface area, covering more than one-third of Ibaraki Prefecture''s total area. In winter, many migratory birds visit the lake. The average depth is 4 meters, making it home to various fish species, including smelt, carp, and goby, as well as non-native species like bluegill and black bass, attracting anglers from across the country. The lake is also a rich habitat for 150 species of wild birds and aquatic plants. In summer, tourist sailing boats operate on the lake, showcasing the majestic sight of the boats with their white sails filled with wind, a symbol of Kasukabe Lake.' where id = 'Fr_ZyACOjvfDmGcowH-Nj';
update content_bodies set title = '【絶景茨城／日本遺産】弘道館［4K］茨城県水戸市', description = '弘道館は茨城県水戸市に位置する国指定の特別史跡および重要文化財で、1842年に水戸藩第9代藩主の徳川斉昭によって設立された日本最大の藩校です。最後の将軍である徳川慶喜も幼少期にここで学び、大政奉還後は謹慎生活を送りました。この映像では、普段は見ることのできない実物の「鳥瞰図」や孔子廟の内部、八卦堂に収められている弘道館記碑などの貴重な部分を紹介しています。' where id = 'qoav0ySx79osxCDWUg-vJ';
update content_bodies set title = 'Kōdōkan: A Scenic Heritage Site in Ibaraki, Japan [4K]', description = 'Kōdōkan, located in Mito City, Ibaraki Prefecture, is a nationally designated special historic site and important cultural property. Established in 1842 by Tokugawa Nariaki, the 9th lord of the Mito Domain, it is the largest domain school in Japan. The last shogun, Tokugawa Yoshinobu, also studied here during his childhood and later lived in seclusion after the restoration of imperial rule. This video captures unique aspects of Kōdōkan, including a real ''chōkanzu'' (bird''s-eye view), the interior of the Confucian temple, and the Kōdōkan monument housed in the Hakkadō, which are not usually accessible to the public.' where id = '9mHbYYt8jb4c6CDFzEFcR';
update content_bodies set title = '常陸國總社宮例大祭｜VISIT IBARAKI, JAPAN', description = '常陸國總社宮例大祭（ひたちのくにそうしゃぐうれいたいさい）は「石岡のおまつり」としても知られ、関東三大祭の一つに数えられています。この祭りの特徴的な要素は、石岡市の象徴ともなっている大きな獅子頭です。また、県指定無形民俗文化財である「ささら」と「石岡囃子」の伝統的な演目も行われます。毎年、全国から数十万人の観光客が訪れ、この壮大なお祭りの迫力を楽しんでいます。' where id = 'o0p9uQRiQlO1FjqHTfIKa';
update content_bodies set title = 'Hitachi Kokuso Shrine Grand Festival | VISIT IBARAKI, JAPAN', description = 'The Hitachi Kokuso Shrine Grand Festival, also known as the ''Ishioka Festival,'' is one of the three major festivals in the Kanto region. It features a large lion head, which has become a symbol of Ishioka City. The festival includes traditional performances such as ''Sasara'' and ''Ishioka Bayashi,'' which are designated as intangible folk cultural assets by the prefecture. Each year, hundreds of thousands of tourists from across the country come to experience the grandeur and excitement of this magnificent festival.' where id = '0hgmyJ-v2WV6dQ3WIvane';
update content_bodies set title = '【絶景茨城】紫陽花 雨引観音', description = '桜川市の雨引観音では、毎年6月10日から7月20日まで「あじさい祭り」が開催されます。この期間中、約100種5,000株のあじさいが境内やその周辺を彩り、色とりどりの花々が楽しめます。また、夜には特別なライトアップが行われ、あじさいが池に浮かべられ、幻想的な景観が広がります。' where id = 'W7883kJ4BzwWRTqBgPtqV';
update content_bodies set title = 'Spectacular Ibaraki: Hydrangeas at Amabiki Kannon', description = 'The Amabiki Kannon in Sakuragawa City hosts the ''Hydrangea Festival'' annually from June 10 to July 20. During this period, approximately 5,000 hydrangeas of around 100 varieties bloom vibrantly throughout the temple grounds and surrounding areas. In the evenings, a special illumination event takes place, where hydrangeas are floated on the pond, creating a stunning visual display.' where id = '5HIv5Zaatt0E_wwd240If';
update content_bodies set title = '【ドローン映像】長崎ばーどアイ4K　「柿の浜海水浴場」', description = '『長崎ばーどアイ』は、長崎の美しい風景を4Kドローン映像で楽しむことができる作品です。撮影場所は北松浦郡小値賀町の柿の浜海水浴場で、2020年の夏に撮影されました。この映像は、四季折々の長崎の魅力を伝え、視聴者に夢や旅行の楽しさを感じさせる内容となっています。' where id = 'BhTL8w7hIF_c_RCoCQCXm';
update content_bodies set title = 'NAGASAKI Bird''s Eye - 4K Drone Footage', description = 'This video showcases stunning 4K drone footage of Kakinohama Public Beach in Nagasaki, Japan. Filmed in the summer of 2020, it captures the beauty of the region''s landscapes throughout the seasons. The footage invites viewers to dream, travel, and discover the amazing places in Nagasaki, highlighting the unique charm of the area.' where id = 'PlPbmgCq6Nme1VsOHBNOH';
update content_bodies set title = '【絶景茨城】国営ひたち海浜公園｜ネモフィラ', description = '死ぬまでに行きたい絶景の一つ、茨城県ひたちなか市にある国営ひたち海浜公園のネモフィラハーモニー。海からの風に揺れるネモフィラと青空が混ざり合い、視界は鮮やかな青一色に埋め尽くされます。ここでしか味わえない唯一無二の青の絶景をお楽しみください。' where id = 'aHtk_Ptb--kldl5eorCCl';
update content_bodies set title = 'Hitachi Seaside Park: A Scenic Wonder in Ibaraki', description = 'One of Japan''s most breathtaking views, the Hitachi Seaside Park in Hitachinaka City, Ibaraki Prefecture, features the stunning Nemophila Harmony. The gentle breeze from the sea sways the nemophila flowers, blending their vibrant blue with the sky, creating a mesmerizing vista filled with shades of blue. Experience this unique and unparalleled blue scenery that can only be found here.' where id = 'EeyZwT7a31pcZBLHG-_lj';
update content_bodies set title = '絶景茨城／国選択・県指定無形民俗文化財：撞舞（つくまい）', description = '撞舞（つくまい）は、茨城県龍ケ崎市の伝統芸能で、毎年7月下旬に行われる八坂神社の祇園祭で披露されます。祭りの最終日の夕方、根町の撞舞通りで行われ、独特の衣装を着た二人の舞男が、高さ14メートルの柱の上で命綱なしでスリリングな技を披露します。この魅力的なイベントは、地域の豊かな文化遺産を象徴しています。' where id = '0Kw7fGPzO0gTkgrVvuDRC';
update content_bodies set title = 'Spectacular Ibaraki / Nationally Selected and Prefecturally Designated Intangible Folk Cultural Asset: Tsukumai', description = 'Tsukumai is a traditional performing art celebrated in Ryugasaki City, Ibaraki Prefecture. It takes place during the Gion Festival at Yasaka Shrine in late July for three days. On the final evening, two performers dressed in unique costumes showcase thrilling skills atop a 14-meter-high pole without safety harnesses. This captivating event highlights the rich cultural heritage of the region.' where id = 'T63EUmMQEXqpZ00yaTZRC';
update content_bodies set title = '【絶景茨城】日立市の海［4K］｜VISIT IBARAKI, JAPAN', description = 'この動画は、2015年7月14日に撮影された茨城県日立市の美しい海岸線を紹介しています。夏の空の下、南の久慈浜の朝焼けから始まり、河原子、会瀬、日立バイパス、鵜の岬、伊師浜を巡る様子が映し出されています。' where id = '0k0D95x5nV4RZ8eMZuT4g';
update content_bodies set title = 'Stunning Ibaraki: The Sea of Hitachi City [4K] | VISIT IBARAKI, JAPAN', description = 'This video showcases the beautiful coastline of Hitachi City in Ibaraki Prefecture, filmed on July 14, 2015. Under the summer sky, the footage captures a journey from the morning glow of Kuji Beach in the south to Kawarako, Aise, the Hitachi Bypass, Unosaki, and Ishi Beach in the north.' where id = 'ZfSlW1OD9IdL8BEovxqSp';
update content_bodies set title = '【絶景茨城】潮来祇園祭禮', description = '潮来祇園祭禮は800年以上の歴史と伝統を誇り、毎年8月上旬の3日間にわたって開催されます。江戸・明治時代の匠の技を今に伝える14台の奉納山車は、各町内の財産として大切に管理されています。特に「曲曳き」と呼ばれる引き廻しでは、若衆と山車、芸座連が一体となった圧巻の光景が楽しめます。' where id = 'H3SqRY5JHTxD3Tq0dn6IZ';
update content_bodies set title = 'Ibaraki''s Spectacular: Itako Gion Festival', description = 'The Itako Gion Festival, with over 800 years of history and tradition, takes place annually in early August for three days. It features 14 beautifully crafted floats that showcase the skills of artisans from the Edo and Meiji periods, each carefully maintained as treasures of their respective neighborhoods. The highlight of the festival is the ''Kurubiki'' or float maneuvering, where the young men, floats, and performers come together in a stunning display.' where id = '15MjUr6RD0Mc8dAdfq344';
update content_bodies set title = 'ドローン映像　長崎ばーどアイ４K　蛤浜海水浴場', description = 'この動画では、ドローン映像を用いて長崎ばーどアイ４Kで蛤浜海水浴場を紹介しています。美しい海岸線や周辺の自然を高画質で楽しむことができ、視聴者にこの海水浴場の魅力を伝えています。' where id = 'uSLZ3mANoQqPJjI3W4JLi';
update content_bodies set title = 'Drone Footage: Nagasaki Bird Eye 4K - Hamaguri Beach', description = 'This video introduces Hamaguri Beach using drone footage captured in 4K by Nagasaki Bird Eye.' where id = 'bjvTDNFP86L9Z7reBv3A8';
update content_bodies set title = '【絶景茨城】菜の花［4K］茨城県境町｜VISIT IBARAKI, JAPAN', description = '2015年4月16日、茨城県境町の川岸には毎年春に美しい黄色の菜の花が広がります。この場所で開催される「さかい菜の花フェスティバル」では、訪れる人々が高瀬舟に乗りながら、菜の花畑の美しい景観を楽しむことができます。' where id = '_rVSUY1DWAoJszwVM32xM';
update content_bodies set title = 'Stunning Ibaraki: Nanohana [4K] Sakai Town, Ibaraki Prefecture | VISIT IBARAKI, JAPAN', description = 'On April 16, 2015, the riverside in Sakai Town, Ibaraki Prefecture, transforms into a beautiful carpet of yellow nanohana (rapeseed flowers) every spring. The ''Sakai Nanohana Festival'' is held at this location, where visitors can enjoy the scenic views of the nanohana fields while riding on a traditional Takase-bune ferry.' where id = 'Iw5vS9z31hEYSz5WCvuya';
update content_bodies set title = '【絶景茨城】八重桜［4K］茨城県那珂市｜VISIT IBARAKI, JAPAN', description = '2015年4月23日に撮影されたこの映像は、茨城県那珂市にある静峰ふるさと公園を紹介しています。この公園は「日本のさくら名所100選」に選ばれており、毎年春の4月中旬から5月初旬にかけて、八重桜が一斉に咲き誇ります。さらに、八重桜のライトアップや郷土芸能、コンサートなどのイベントが行われる「八重桜まつり」が開催され、壮観な八重桜の景色に彩りを加えています。' where id = 'rrJ4EQpmol64QMisRzKkR';
update content_bodies set title = 'Stunning Ibaraki: Yaezakura [4K] Nakashi, Ibaraki Prefecture | VISIT IBARAKI, JAPAN', description = 'Filmed on April 23, 2015, this video showcases the Shizumine Furusato Park in Nakashi, Ibaraki Prefecture, which is selected as one of Japan''s 100 Famous Cherry Blossom Spots. Every spring, from mid-April to early May, the park is adorned with beautiful Yaezakura cherry blossoms, making it a renowned cherry blossom viewing location. Additionally, the park hosts the ''Yaezakura Festival,'' featuring cherry blossom illuminations, local performances, and concerts, enhancing the spectacular scenery of the Yaezakura.' where id = 'S-6ShfZoi6V2T71WvSJA5';
update content_bodies set title = '【絶景茨城】桜［4K］茨城県水戸市', description = 'この動画では、2015年3月30日と4月3日に撮影された茨城県水戸市の桜の名所を紹介します。護国神社、千波湖、六地蔵寺などの桜の名所が登場し、特に六地蔵寺の樹齢180年のしだれ桜が見どころです。4K映像で桜の美しい景色を楽しむことができます。また、紹介された場所を含む複数の会場で「水戸の桜まつり」が開催されます。' where id = 'Zs4d95Uf1XMbYf28AonrS';
update content_bodies set title = 'Stunning Ibaraki: Cherry Blossoms [4K] in Mito City, Ibaraki Prefecture', description = 'This video showcases the beautiful cherry blossoms in Mito City, Ibaraki, filmed on March 30 and April 3, 2015. It features famous cherry blossom viewing spots such as Gokoku Shrine, Lake Senba, and Rokujizō-ji Temple, including the 180-year-old weeping cherry tree at Rokujizō-ji. Enjoy the breathtaking scenery of cherry blossoms in 4K. Additionally, the ''Mito Cherry Blossom Festival'' is held at multiple venues, including the featured locations.' where id = 'tsrEvf00yrsG_EjGqpooL';
update content_bodies set title = '【絶景茨城】桃 ［4K］ 茨城県古河市｜VISIT IBARAKI, JAPAN', description = '茨城県古河市の古河総合公園で開催される古河桃まつりでは、5種類の花桃（矢口・源平・菊桃・寿星桃・寒白桃）が楽しめます。桃林は鮮やかなピンク色に染まり、訪れる人々を魅了します。2015年度の開催期間は3月20日（金）から4月5日（日）までです。詳細は古河市観光協会（TEL: 0280-91-1811）までお問い合わせください。' where id = '0v3xPDsMKV3NUmtHqknDe';
update content_bodies set title = 'Stunning Ibaraki: Peach Blossoms [4K] - Koga City, Ibaraki Prefecture | VISIT IBARAKI, JAPAN', description = 'The Koga Peach Festival is held at Koga General Park in Koga City, Ibaraki Prefecture. The festival features five varieties of flowering peaches: Yaguchi, Genpei, Kikumo, Shosei, and Kanbai. The peach orchard is beautifully adorned with vibrant pink blossoms. In 2015, the festival took place from March 20 (Friday) to April 5 (Sunday). For more information, contact the Koga City Tourism Association at TEL: 0280-91-1811 or visit their website.' where id = 'Lk1aT-HNqE6KeGkeZbjQZ';
update content_bodies set title = 'あやめ｜水郷潮来あやめ園【絶景茨城】', description = '水郷潮来あやめ園では、5月下旬から6月下旬にかけて、約500種100万株のあやめや花菖蒲が美しく咲き誇ります。あやめまつり期間中には、「嫁入り舟」や「あやめ踊り」、「ろ舟遊覧」など、水郷ならではのイベントが開催されます。また、夜にはライトアップされ、昼間とは異なる幻想的なあやめの景色を楽しむことができます。' where id = 'pwhveP9_jOmCDn47iyaam';
update content_bodies set title = 'Ayame | Suigo Itako Ayame Garden - Stunning Ibaraki', description = 'Suigo Itako Ayame Garden showcases approximately 1 million irises of around 500 varieties blooming from late May to late June. During the Ayame Festival, unique events such as ''Bride Boat'', ''Ayame Dance'', and ''Rowing Boat Tours'' are held, reflecting the charm of the water town. At night, the garden is illuminated, offering a fantastical view of the irises that differs from the daytime experience.' where id = 'sDSOS0bgcewPYndcjcxzR';
update content_bodies set title = '【絶景茨城】ひまわり［4K］筑西市明野｜VISIT IBARAKI, JAPAN', description = '2015年9月4日に撮影されたこの映像は、茨城県筑西市の宮山ふるさとふれあい公園近くにある明野ひまわりの里で開催される「あけのひまわりフェスティバル」を紹介しています。このフェスティバルは毎年8月下旬から9月上旬に行われ、壮大な筑波山を背景に八重ひまわりが畑一面に広がる絶景を楽しむことができます。' where id = '4n2Pi-SEG8i6_4fadOl8G';
update content_bodies set title = 'Breathtaking Ibaraki: Sunflowers [4K] Chikusei City Akino | VISIT IBARAKI, JAPAN', description = 'On September 4, 2015, the Akino Sunflower Festival takes place in the Akino Sunflower Field near Miyama Furusato Fureai Park in Chikusei City, Ibaraki Prefecture. This festival is held annually from late August to early September, showcasing a stunning view of double sunflowers sprawling across fields with the majestic Tsukuba Mountain in the background.' where id = 'fmW-xEbFyHpAP82uiYc54';
update content_bodies set title = '西塩子の回り舞台【絶景茨城】', description = '「西塩子の回り舞台」は、茨城県の山里に位置する江戸時代から続く農村歌舞伎の舞台で、日本で最も古い回り舞台の一つです。公演が途絶えた時期もありましたが、地域住民の努力により1997年に復元されました。現在は3年ごとに公演が行われており、2025年にはコロナ禍を経て6年ぶりの開催が予定されています。この舞台の最大の特徴は、毎回組み立てて解体する点で、地域住民が協力して丸太と竹を使い、一夜限りの大舞台を作り上げます。' where id = 'mnEz0XAfn7bVaBg-R9KYm';
update content_bodies set title = 'Nishishio''s Rotating Stage: A Scenic Ibaraki', description = 'Nishishio''s rotating stage is a traditional rural Kabuki stage located in the mountainous region of Ibaraki Prefecture, dating back to the Edo period. It is one of the oldest existing rotating stages in Japan. Although there was a period when performances ceased, local residents worked hard to restore it in 1997 after a 50-year hiatus. Currently, performances are held every three years, with the next one scheduled for 2025, marking a six-year gap due to the COVID-19 pandemic. A unique feature of this stage is that it is assembled and disassembled for each performance, with the entire community coming together to construct a grand stage using logs and bamboo for a one-night-only event.' where id = '-QZp72lF3hMMhbasxiBzq';
update content_bodies set title = 'ドローン映像　長崎ばーどアイ４K　若松瀬戸の夏', description = 'この動画では、長崎ばーどアイ４Kを使用して、若松瀬戸の夏の風景をドローン映像で紹介しています。美しい自然や景観が映し出され、夏の魅力を感じることができます。' where id = 'riJ4VKTxyVSytofNSDRkR';
update content_bodies set title = 'Drone Footage: Nagasaki Bird Eye 4K - Summer at Wakamatsu Seto', description = 'This video introduces the summer scenery of Wakamatsu Seto through drone footage captured in 4K by Nagasaki Bird Eye.' where id = 'JVlir97tY-xg1_-RVbYT9';
update content_bodies set title = 'ドローン映像　長崎ばーどアイ４K　蘇る八万地獄　雲仙温泉街', description = '2021年8月、雲仙温泉を襲った土砂崩れによって埋没した八万地獄。しかし、土砂の中から再び源泉が湧き出してきました。この映像では、一般の人が立ち入れない雲仙温泉の源泉にドローンで接近し、ここでしか見られない自然の息吹を感じることができます。' where id = 'U2RT57zOy7tp7p1YfxAMx';
update content_bodies set title = 'Drone Footage: Nagasaki Bird Eye 4K - The Resurrection of Yamamoto Hell in Unzen Hot Spring Town', description = 'In August 2021, a landslide buried Yamamoto Hell, a hot spring source in Unzen. However, the source has begun to emerge again from the debris. This footage captures the drone''s approach to the hot spring source, which is currently inaccessible to the public. Experience the unique natural revival that can only be witnessed here.' where id = 'cZ3pbGVQyo8CoFTicWzDB';
update content_bodies set title = '長崎ばーどアイ　ドローンで迫る平成新山　普賢岳溶岩ドーム頂上2021年版', description = '2021年6月、平成新山である雲仙普賢岳の溶岩ドームの一部が崩落していることが確認されました。この状況を記録するために、NBCはドローンを使用しました。' where id = '_6y-lwvU_GOCQAua7bsFE';
update content_bodies set title = 'Nagasaki Bird Eye: Approaching Heisei Shinzan with Drones - 2021 Edition', description = 'In June 2021, it was confirmed that part of the Heisei Shinzan, the lava dome of Mount Unzen Fugen, had collapsed. NBC used drones to document the situation.' where id = 'YbnS9OjH-3ezgIIaSaIsw';
update content_bodies set title = '長崎のドローン　長崎ばーどアイ４K　水の都島原', description = 'この動画では、長崎のドローンである長崎ばーどアイ４Kと、水の都として知られる島原について紹介しています。島原の美しい風景や水の魅力をドローン映像を通じて楽しむことができます。' where id = 'lRt7YKenrNAygokRHpl0z';
update content_bodies set title = 'Nagasaki Drone: Nagasaki Bird Eye 4K - The Water City of Shimabara', description = 'This video introduces the Nagasaki drone, Nagasaki Bird Eye 4K, and the water city of Shimabara.' where id = 'h0QHxe2vMnTbGdCdzBSiF';
update content_bodies set title = '長崎のドローン　長崎ばーどアイ４K　細石流キリシタン墓地（五島市）', description = 'この動画では、長崎のドローンを使用して、五島市にある細石流キリシタン墓地を4Kで紹介しています。美しい映像を通じて、歴史的な場所の魅力を伝えています。' where id = 'GH5hrloqFpibqJr5ub96z';
