update content_bodies set title = 'Drone Footage: Nagasaki Bird Eye 4K - Oka-zuki and Ko-kazuki', description = 'This footage showcases a giant rock towering over the western sea of Nagasaki. It is noted that the location referred to as Nagasaki City, Sotomachi is actually a mistake; the correct area is Nagasaki City''s Sotomachi district.' where id = 'tWVPwgx29BSbFGA7nrjW-';
