update content_bodies set title = 'ドローン映像　長崎ばーどアイ４K　令和二年の桜', description = 'この動画は、ドローン映像を使用して長崎のばーどアイで撮影された令和二年の桜を紹介しています。美しい桜の風景が映し出され、長崎の自然の魅力を伝えています。' where id = 'vJeK7yh_nJK_UMzqaXFSQ';
update content_bodies set title = 'Drone Footage: Nagasaki Bird Eye 4K - Cherry Blossoms of 2020', description = 'This video showcases drone footage capturing the cherry blossoms of 2020 in Nagasaki, filmed from a bird''s eye view.' where id = 'muh02cRLaZCieWKOLlLzv';
update content_bodies set title = 'ドローン映像　長崎ばーどアイ４K　新しい道の開通', description = 'この動画では、長崎ばーどアイ４Kを使用して新しい道の開通を紹介しています。ドローン映像を通じて、開通した道路の様子や周辺の景観が映し出され、視聴者に新たな交通の便を提供するこの道の重要性を伝えています。' where id = 'nrJYvGgwDxpwdApqSZKXI';
update content_bodies set title = 'Drone Footage: Nagasaki Bird Eye 4K - New Road Opening', description = 'This video showcases the opening of a new road using drone footage captured in 4K by Nagasaki Bird Eye.' where id = 'oTynVwf0yFOLAPq7v_R8c';
update content_bodies set title = '長崎ばーどアイ４Ｋ　眉山（無音）', description = '江戸時代に島原大変を引き起こした島原市の眉山を紹介する映像です。眉山は歴史的な背景を持つ場所であり、島原大変はその名の通り、江戸時代に発生した大規模な反乱を指します。この映像は、無音で眉山の美しい景観をドローンで捉えています。長崎の自然や歴史に触れることができる貴重な映像です。' where id = 'E8bWJ8WYl_zlzKlvYKIMM';
update content_bodies set title = 'Nagasaki Bird Eye 4K: Mount Mayuyama (Silent)', description = 'Mount Mayuyama in Shimabara City, which caused the Shimabara Rebellion during the Edo period.' where id = 'TG9O8y1Jlk05U8M2Sb835';
update content_bodies set title = '長崎ばーどアイ４Ｋ　浦上川河口の風景', description = '長崎ばーどアイ４Ｋでは、浦上川河口の風景を紹介しています。' where id = 'obmVJPyIFM0hYGg9DZp8v';
update content_bodies set title = 'Nagasaki Bird Eye 4K: Landscape of Urakami River Estuary', description = 'Nagasaki Bird Eye 4K presents the scenic view of the Urakami River estuary.' where id = 'RuEu7bj2OibpDzv5R2xqn';
update content_bodies set title = '新潟港のエクスカーション No.4', description = 'このエクスカーションは、海と山の美しさを楽しむ素晴らしい体験を提供します。寺泊魚の市場、雪谷、長岡花火館を訪れ、地元の海鮮や美しい景色を楽しむことができます。' where id = 'DjwLqB5a_ikeg00GeXnGm';
update content_bodies set title = 'Port of Niigata excursion No.4', description = 'This excursion offers a delightful experience combining the beauty of the ocean and the mountains. It includes visits to Teradomari Fish Street Market, Settaya, and Nagaoka Hanabi-Kan, allowing participants to enjoy local seafood and scenic views.' where id = '2nhqG4FydWjbb5Js5BatD';
update content_bodies set title = '長崎ばーどアイ４K　雲仙普賢岳溶岩ドーム２０１９撮影②', description = '1990年に始まった雲仙普賢岳の噴火によって形成された溶岩ドームは、噴出が止まった今もなお、むき出しの岩肌を見せており、不気味な姿をしています。この映像は2019年に撮影された普賢岳の溶岩ドームを捉えています。' where id = 'q-tqWxSHmSEKLAmL_EbCY';
update content_bodies set title = 'Nagasaki Bird Eye 4K: Unzen Fugendake Lava Dome Filming 2019②', description = 'The lava dome formed from the eruption of Unzen Fugendake, which began in 1990, remains exposed and eerie even after the lava flow has ceased. This footage captures the lava dome as it appeared in 2019.' where id = 'qWtOFaKqzkIgqVSdpnjgg';
update content_bodies set title = '長崎ばーどアイ４K　雲仙普賢岳溶岩ドーム2019年撮影①', description = '1990年に始まった雲仙普賢岳の噴火によって形成された溶岩ドームです。溶岩の噴出は止まったものの、今も岩肌はむき出しの状態で、不気味な姿を見せています。この映像は2019年に撮影された普賢岳の溶岩ドームです。' where id = 'c3ehIROKDK4BIdI5XSHgC';
update content_bodies set title = 'Nagasaki Bird Eye 4K: Unzen Fugendake Lava Dome Captured in 2019 (Part 1)', description = 'The lava dome formed from the eruption of Unzen Fugendake, which began in 1990. Even though the lava flow has ceased, the exposed rock surface presents a haunting appearance. This footage of the Fugendake lava dome was captured in 2019.' where id = 'n1TP0KTg0MS8IckrB5u_a';
update content_bodies set title = '今治城に行ってきました！(本丸跡編)', description = '愛媛県今治市に位置する今治城についての情報を紹介します。詳細は公式サイトをご覧ください。URLはhttp://museum.city.imabari.ehime.jp/imabarijo/です。また、天守閣編の動画もこちらからご覧いただけます：https://youtu.be/Rzlk_lNj2o4。' where id = 'xNijfEdVIV3n0xVgbpfyr';
update content_bodies set title = 'I Visited Imabari Castle! (Main Keep Ruins Edition)', description = 'This is Imabari Castle located in Imabari City, Ehime Prefecture. For more detailed information, visit the official site at http://museum.city.imabari.ehime.jp/imabarijo/. You can also check out the keep edition here: https://youtu.be/Rzlk_lNj2o4.' where id = 'G2HR6yY1MXHouTlv5m67x';
update content_bodies set title = 'Pintわくわくしま旅～宇久島編～', description = '「わくわく乗船券」は、本土から五島列島、壱岐、対馬への往復乗船料金に100円を追加することで体験クーポン券が付いてくるお得な乗船券です。さらに、現在は「行っ得！長崎のしまクーポン券」も付いてきます。わくわく乗船券の詳細については、リンクをご覧ください。なお、「わくわく乗船券」と「行っ得！長崎のしまクーポン券」は、予算がなくなり次第終了しますのでご注意ください。' where id = 'c5XalQ9xJE2KxoRkV1o1-';
update content_bodies set title = 'Exciting Island Trip - Ukushima Edition', description = 'The ''Waku Waku Boarding Ticket'' is a special ticket that allows you to enjoy a round-trip fare to the Goto Islands, Iki, and Tsushima from the mainland, with an additional 100 yen for an experience coupon. Currently, it also includes the ''Ikidoku! Nagasaki Island Coupon.'' For more details about the Waku Waku Boarding Ticket, please visit the provided link. Note that both the ''Waku Waku Boarding Ticket'' and the ''Ikidoku! Nagasaki Island Coupon'' will end once the budget is exhausted.' where id = '-lO3GDn-v8DRbNWDZTyws';
update content_bodies set title = '大洲城 歓迎はたふり', description = '「大洲城 歓迎はたふり」は、愛媛県大洲市大洲903にある大洲城で行われるイベントです。このイベントでは、JR四国の観光列車「伊予灘ものがたり」が鉄橋をゆっくり渡る際に、大洲城本丸からのぼり旗を振って歓迎します。開催日は毎週土・日・祝日で、時間は15:16頃と16:25頃の2回です。参加は無料です。また、この動画の最後には、愛媛県松山市を流れる宮前川にいたコガモの映像が収められています。' where id = 'Gaawt3aIRy2Fi5_VQS4HK';
update content_bodies set title = 'Ozu Castle Welcome Hataburi', description = 'The event ''Ozu Castle Welcome Hataburi'' takes place at Ozu Castle, located at 903 Ozu, Ehime Prefecture. During this event, when the JR Shikoku sightseeing train ''Iyo-nada Monogatari'' slowly crosses the bridge, flags are waved from the main keep of Ozu Castle to welcome the train. The event is held every Saturday, Sunday, and public holiday, with two sessions at around 15:16 and 16:25. Participation is free. Additionally, the video concludes with footage of a female duck spotted in the Miyamae River in Matsuyama City, Ehime Prefecture.' where id = 'vI567CreraUlUGnkZ6KYd';
update content_bodies set title = '大洲城 内堀菖蒲園', description = '大洲城 内堀菖蒲園は、愛媛県大洲市大洲８８０−９１に位置しています。この場所は、菖蒲の美しい景観を楽しむことができるスポットです。詳細な情報は、公式ウェブサイトをご覧ください。' where id = 't8VZLY5WBkbYIHBmu07Bn';
update content_bodies set title = 'Ozu Castle Inner Moat Iris Garden', description = 'The Ozu Castle Inner Moat Iris Garden is located at 880-91 Ozu, Ozu City, Ehime Prefecture. For more detailed information, visit the official website.' where id = 'mp_wZVv8xe4vWhJCG3sr2';
update content_bodies set title = '名古屋おもてなし武将隊の演武を見てきました！', description = 'この演武は、平成30年(2018年)1月28日に堀之内と松山城で行われた「第５回 全国城サミットin松山」で行われました。演武では、織田信長、豊臣秀吉、徳川家康に関する楽しい話を聞くことができ、観客は楽しむことができました。演武終了後には、織田信長、豊臣秀吉、徳川家康と一緒に写真撮影をすることもできました。丸亀城鉄砲隊の演武については、こちらをご覧ください！→https://youtu.be/lgCToSMmet4' where id = 'm7ZWoAZh_W5ayor2R9G_p';
update content_bodies set title = 'I Attended the Nagoya Omotenashi Busho-tai Performance!', description = 'The performance took place on January 28, 2018, at Horinouchi and Matsuyama Castle during the ''5th National Castle Summit in Matsuyama.'' Attendees enjoyed entertaining stories about historical figures such as Oda Nobunaga, Toyotomi Hideyoshi, and Tokugawa Ieyasu. After the performance, participants had the opportunity to take photos with these famous samurai figures. For more, check out the Marugame Castle Gun Corps performance here: https://youtu.be/lgCToSMmet4' where id = '5_PjUwqjjUcZ5O55sOxrJ';
update content_bodies set title = '三陸ジオパークVRムービー（戸羽浦）', description = '三陸ジオパークVRムービーは、岩手県の野田村に位置する戸羽浦を紹介しています。この地域は「砂浜から続く塩の道」として知られ、独特の海岸線と地域の文化的な重要性を強調しています。' where id = 'R5S-UCT8yUbPy46m6WDBA';
update content_bodies set title = 'Sanriku Geopark VR Movie (Tohugaura)', description = 'The Sanriku Geopark VR Movie showcases Tohugaura, located in Noda village, Iwate prefecture. This area features the ''Salt road that continues from sandy beach,'' highlighting the unique coastal landscape and cultural significance of the region.' where id = 'K3bi3iMOUK8iFBgE3o8rQ';
update content_bodies set title = 'しまなみ海道伯方島探索！木浦城跡(伯方ふるさと歴史公園)！', description = 'ここは、愛媛県今治市伯方町にある木浦城跡(伯方ふるさと歴史公園)です。木浦城跡(伯方ふるさと歴史公園)には、城や古墳があり、まさに歴史を感じることのできる公園です。' where id = 'DxtTyuqWOYGJHzzFXEb8t';
update content_bodies set title = 'Exploring the Kiu Castle Ruins (Hakaba Furusato Historical Park) on Shimanami Kaido, Hakata Island!', description = 'Kiu Castle Ruins, located in Hakaba Town, Imabari City, Ehime Prefecture, is part of the Hakaba Furusato Historical Park. This park features a castle and ancient burial mounds, allowing visitors to truly feel the history of the area.' where id = '4Kr3MRZ0UjiZo5qcmJ8kE';
update content_bodies set title = '天守閣からの景色は絶景！岩国城を探索してみた！', description = '岩国城は山口県岩国市に位置し、山頂からの素晴らしい景色と日本刀の展示で知られています。訪れる人々は、城の美しい景観と歴史的な価値を楽しむことができます。' where id = 'n3TxdRAvN-QOADkEnEEVa';
update content_bodies set title = 'The View from the Castle Keep is Spectacular! Exploring Iwakuni Castle!', description = 'Iwakuni Castle, located in Iwakuni City, Yamaguchi Prefecture, is famous for its breathtaking views from the mountaintop and its display of Japanese swords.' where id = 'ayM2SN1Q61bi8wv7GWD2k';
update content_bodies set title = '観光マナー映像「The Etiquette Guide to Fukuoka」（韓国語版）', description = 'この映像では、楽しい福岡旅行のためのいくつかのポイントを紹介しています。公の場でのマナー、トイレの使い方、写真撮影時のマナー、ゴミの不法投棄禁止、喫煙時のルールについて触れています。福岡で楽しい旅行をお楽しみください！' where id = 'Mi0GSgY2BRN8n6-2iy9tQ';
update content_bodies set title = 'The Etiquette Guide to Fukuoka (Korean Version)', description = 'This video introduces several key points for an enjoyable trip to Fukuoka. It covers manners in public places, how to use restrooms, etiquette for taking photos, the prohibition of littering, and rules to follow when smoking. We hope you have a great time in Fukuoka!' where id = 'tcz2LmmwgSPgzvTDIH1Vb';
update content_bodies set title = '観光マナー映像「The Etiquette Guide to Fukuoka」（繁体字版）', description = 'この映像では、福岡旅行を楽しむための重要なポイントを紹介しています。公共の場での礼儀、トイレの使用方法、撮影時のマナー、ゴミを捨てないことの重要性、喫煙に関するルールなどが含まれています。皆さんが素晴らしい福岡の旅を楽しめることを願っています！' where id = '4Z6_PgWns69bnh-7ZNxtt';
update content_bodies set title = 'The Etiquette Guide to Fukuoka (Traditional Chinese Version)', description = 'This video introduces key points for enjoying your trip to Fukuoka, including etiquette in public places, proper restroom usage, photography etiquette, the importance of not littering, and smoking regulations. We wish you a wonderful trip to Fukuoka!' where id = 'JrZbL7MXk38ICeR3gngD_';
update content_bodies set title = '観光マナー映像「The Etiquette Guide to Fukuoka」（簡体字版）', description = 'この映像では、福岡を訪れる際の重要なマナーについて紹介しています。公共の場での礼儀、トイレの正しい使い方、写真撮影のマナー、ゴミを捨てないことの重要性、喫煙に関する規則などが含まれています。福岡での素晴らしい旅をお楽しみください！' where id = '5N5U3NS51xdwSm86Y-rD0';
update content_bodies set title = 'The Etiquette Guide to Fukuoka (Simplified Chinese Version)', description = 'This video provides essential tips for travelers visiting Fukuoka. It covers public etiquette, proper restroom usage, photography etiquette, the importance of not littering, and smoking regulations. Enjoy your trip to Fukuoka!' where id = 'knMnBD4unsCMK_r3PlKCD';
update content_bodies set title = '新潟港の小旅行 No.3', description = 'この小旅行は、歴史的な名所である柴田城から始まります。柴田城は日本の封建時代を垣間見ることができる場所です。旅行には、静かな雰囲気で知られる美しい庭園・清水園や、伝統的な酒造りで有名な千年酒の菊川を訪れることが含まれています。また、文化的な豊かさを加える伊津屋も旅程に含まれています。全体として、この短い旅行は歴史、自然、地元の工芸品の融合を提供します。' where id = 'CVm_7DATgA1x8vl67bd27';
update content_bodies set title = 'Port of Niigata excursion No.3', description = 'This excursion begins at Shibata Castle, a historical site that offers a glimpse into Japan''s feudal past. The trip includes visits to Shimizuen, a beautiful garden known for its serene atmosphere, and Sennensake Kikkawa, a place renowned for its traditional sake brewing. Additionally, the itinerary features Izutsuya, a location that adds to the cultural richness of the experience. Overall, this short trip provides a blend of history, nature, and local craftsmanship.' where id = 'L13re9EctzYrsaNG22Rja';
update content_bodies set title = '観光マナー映像「福岡旅遊指南」（繁体字版）', description = '福岡市の公式YouTubeチャンネルで公開されているこの映像は、福岡の観光地を巡りながら日本の文化やマナーを紹介しています。映像は無償で提供されており、必要な方はプロモーション推進課（E-mail：promotion.EPB@city.fukuoka.lg.jp）までご連絡ください。福岡市役所や福岡チャンネルの公式情報も含まれています。' where id = 'g0nqz3N5KfS9Te626cIqT';
update content_bodies set title = 'Fukuoka Travel Guide Video (Traditional Chinese Version)', description = 'This video, available on Fukuoka City''s official YouTube channel, introduces Japanese culture and manners while showcasing various tourist attractions in Fukuoka. The video is provided free of charge, and those interested can contact the Promotion Division at promotion.EPB@city.fukuoka.lg.jp for more information.' where id = 'sk1nvLpCQzSlpCDOiin7c';
update content_bodies set title = '観光マナー映像「福冈旅游小贴士　～一起来感受福冈的魅力吧！～」（簡体字版）を制作', description = '福岡市の公式YouTubeチャンネルで、日本の文化やマナーを紹介しながら福岡の観光地を巡る映像を制作しました。この映像は無償で提供されており、必要な方はプロモーション推進課（E-mail：promotion.EPB@city.fukuoka.lg.jp）までご連絡ください。' where id = 'UGoPVNC2N_d27yHItnXxo';
update content_bodies set title = 'Fukuoka Tourism Tips - Experience the Charm of Fukuoka!', description = 'This video, available on Fukuoka City''s official YouTube channel, introduces Japanese culture and manners while showcasing various tourist attractions in Fukuoka. The video is provided free of charge, and those interested can contact the Promotion Division at promotion.EPB@city.fukuoka.lg.jp for more information.' where id = '89OBOHQBYFlCAkDt9PrFa';
update content_bodies set title = '江戸：現代東京の基盤', description = '江戸は東京の前身であり、当時世界最大の都市の一つに成長しました。人々の日常生活から生まれた豊かで独自の文化は、形あるものと形のないものの両方を含んでいます。江戸は優雅さを受け入れ、多様なアイデアや価値観を歓迎し、文化の繁栄を促しました。その開放性と挑戦する意欲が、都市に創造性と想像力を吹き込みました。今日、江戸の心は現代東京を通じて流れ続けており、その現在と未来に影響を与えています。' where id = '2PLtiO4iR_lSz8-xOIFtm';
update content_bodies set title = 'Edo: The Foundation of Modern Tokyo', description = 'Edo, the predecessor of Tokyo, was one of the largest cities in the world during its time. It fostered a rich and unique culture, both tangible and intangible, shaped by the daily lives of its inhabitants. The city embraced elegance and welcomed diverse ideas and values, which contributed to its cultural flourishing. Edo''s openness and ambition to tackle challenges infused the city with creativity and imagination. Today, the essence of Edo continues to flow through modern Tokyo, influencing its present and future.' where id = 'VAouXWJxKEmn-ODcagLXD';
update content_bodies set title = '江戸時代からの銭湯の精神', description = '銭湯は、日本の伝統的な浴場であり、現代の東京と歴史的な江戸時代を結ぶ timeless な伝統を象徴しています。この文化的な慣習は時代を超えて続いており、人々にリラクゼーションとコミュニティの体験を提供しています。私たちが銭湯を訪れる理由は何でしょうか？銭湯は単なる入浴の場ではなく、社会的なハブとしても機能し、日本文化の持続的な精神を反映しています。' where id = 'EO1pB_YPQkwsuck54292Q';
update content_bodies set title = 'The Sento Spirit since Edo Period', description = 'Sento, the traditional Japanese bathhouse, represents a timeless tradition that connects modern Tokyo to the historic Edo period. This cultural practice has endured through the ages, inviting people to experience relaxation and community. The question arises: why do we visit Sento? It serves not only as a place for bathing but also as a social hub, reflecting the enduring spirit of Japanese culture.' where id = 's5rh5rl7AoqLC56vMdRK9';
update content_bodies set title = '江戸時代以来の東京の緑の都市開発', description = '東京は江戸時代から400年以上にわたり進化を続けており、緑地を保護してきました。私は歩行者の観察や住民、事業者との対話を通じて都市デザインを研究しています。これらの緑地は、幸せな都市生活にとって重要です。この考え方は江戸時代から変わっていません。緑地は人々が繁栄する楽しい生活を育むのに役立っています。100年後も、東京が持続可能で自然と調和して存在し続けることを確実にします。' where id = 'zqgkq1GyYr5oPl4EwNV21';
update content_bodies set title = 'Tokyo''s Green Urban Development since Edo Period', description = 'Tokyo has been evolving for over 400 years, maintaining its green spaces since the Edo period. The research focuses on urban design through observing pedestrians and engaging with residents and business owners. These green areas are crucial for a fulfilling city life, a principle that has remained unchanged since the Edo period. They contribute to a thriving environment for the community. Looking ahead, the commitment to ensuring Tokyo''s sustainability and its harmonious existence with nature will continue for the next century.' where id = 'RzQDCYJ6QBuZPoHIcqzl7';
update content_bodies set title = 'ISHIKARI STYLE　～SUMMER～', description = '石狩エリアは、都市と自然が共存する場所で、美しい景色や楽しい体験が豊富にあり、SNS用の写真を撮るのに最適です。COVID-19が収束した後、皆様を石狩エリアにお迎えできることを楽しみにしています。最新情報はFacebookの「Ishikari Days - Hokkaido TabiGokoro」をご覧ください。' where id = 'ck-R6l15OSMExZE9jn8vZ';
update content_bodies set title = 'ISHIKARI STYLE - SUMMER', description = 'The Ishikari area is a place where cities and nature coexist, offering numerous beautiful sceneries and enjoyable experiences perfect for capturing on social media. We eagerly await your visit to the Ishikari area once the COVID-19 pandemic is over. For more updates, follow us on Facebook at ''Ishikari Days - Hokkaido TabiGokoro''.' where id = 'LB_6i1gm_VAr7KpwobHRa';
update content_bodies set title = '北海道・北東北の縄文遺跡群', description = '世界文化遺産「北海道・北東北の縄文遺跡群」に含まれる道内の縄文遺跡の魅力を紹介します。これらの遺跡は、縄文時代の文化や生活様式を知る貴重な資産であり、訪れる人々にその歴史的価値を伝えています。' where id = '-cjduifCRU7out8bFUQMc';
update content_bodies set title = 'Jomon Prehistoric Sites in Northern Japan', description = 'This text introduces the attractions of the Jomon archaeological sites in Hokkaido and the northeastern region of Japan, which are part of the UNESCO World Heritage Site ''Jomon Prehistoric Sites in Hokkaido and Northern Tohoku''.' where id = 'kyD-ETCUDljMDF818Qjgu';
update content_bodies set title = '豪華なスーパーヨットの旅に出かけよう！東京の魅力的な島々を発見。', description = '東京には11の離島があり、それぞれが驚くべき景色と独自の文化を持っています。これらは東京の一部とは思えないほどです。現在、スーパーヨットは伊豆大島、八丈島、新島に寄港可能です。伊豆大島は東京から約120kmの場所にあり、海と空の交通施設が整っているため、スーパーヨットやプライベートジェットでのアクセスが可能です。この火山島では、三原山のクレーターや日本唯一の砂漠「裏砂漠」、透明度の高い海でのダイビングなど、さまざまな自然活動を楽しむことができます。伊豆大島の独特の贅沢を体験してください。' where id = 'KVOsmUzdxskdqU2Lg0730';
update content_bodies set title = 'Embark on a Luxury Superyacht journey! Discover Tokyo''s Enchanting Islands.', description = 'Tokyo is home to 11 remote islands, each offering stunning views and unique local cultures that are surprisingly part of the metropolis. Currently, superyachts can dock at Izu Oshima, Hachijojima, and Niijima. Izu Oshima, located about 120 km from Tokyo, features both sea and air-port facilities, allowing access via superyacht or private jet for a luxurious cruise experience. This volcanic island boasts attractions such as the crater of Mt. Mihara, Japan''s only desert ''Ura-sabaku,'' and opportunities for diving in crystal-clear waters, along with various natural activities. Experience the unique luxuries that Izu Oshima has to offer.' where id = 'M0yWQyWGC8FY1HJWRtrox';
update content_bodies set title = '石狩スタイル冬', description = 'この動画は、石狩地域の冬の魅力を紹介しています。石狩地域は、都市と自然が共存する場所で、美しい風景や楽しい体験が豊富にあり、SNS用の写真を撮るのに最適です。COVID-19が収束した後、ぜひ石狩を訪れてほしいというメッセージが込められています。詳細はFacebookページ「石狩デイズ -北海道旅心-」をフォローしてください。' where id = '85M5AH0etlAcYc9PPv4Y5';
update content_bodies set title = 'ISHIKARI STYLE WINTER', description = 'This video showcases the winter beauty of the Ishikari area, highlighting its unique charm. The Ishikari area is a place where urban life and nature harmoniously coexist, offering numerous scenic spots and enjoyable experiences perfect for capturing on social media. The video invites viewers to visit Ishikari once the COVID-19 pandemic is over, emphasizing the area''s appeal for travelers. For more information, you can follow their Facebook page ''Ishikari Days -Hokkaido TabiGokoro''.' where id = 'z6hfIaruqD4yllxMNhNp1';
update content_bodies set title = '阿蘇山上・草千里ヶ浜にお越しの皆様へ、守ってほしい3つのお願い', description = '阿蘇山上草千里ヶ浜を訪れる皆様に、守ってほしい3つのお願いがあります。まず、放牧中の馬には近づかないでください。これは馬を驚かせたり、安全上のリスクを引き起こす可能性があります。次に、無断立ち入りは禁止されています。特定のエリアには許可された人のみが入ることができ、環境の保護と安全が確保されています。最後に、ゴミのポイ捨ては禁止です。地域を清潔に保つことは、すべての訪問者の楽しみと野生動物の保護にとって重要です。皆様のご協力をお願いいたします。' where id = 'GdezG_Ewym8pw73iw0qsz';
update content_bodies set title = 'Three Requests for Visitors to Aso Mountain and Kusasenrigahama', description = 'Visitors to Aso Mountain and Kusasenrigahama are asked to adhere to three important requests. First, please do not approach grazing horses, as this can disturb them and pose safety risks. Second, unauthorized entry is prohibited; only authorized personnel are allowed in certain areas to ensure the safety and preservation of the environment. Lastly, littering is strictly forbidden. Keeping the area clean is essential for the enjoyment of all visitors and the protection of wildlife. Your cooperation in following these requests is greatly appreciated.' where id = 'GS-XvlOOqVmzK5yLvauyu';
update content_bodies set title = '雨の日も楽しみたい！雨の阿蘇市おすすめ観光プラン！古民家カフェ・ワークショップ・温泉も！', description = '雨の日でも阿蘇市を楽しむための観光プランを紹介します。おしゃれで落ち着いた空間で過ごせる隠れ茶房「茶蔵カフェ」や、ハンドメイド雑貨の「KHO」を訪れ、ユニークなクラフトを楽しむことができます。また、阿蘇の温泉でリラックスすることもでき、雨の日の過ごし方として最適です。詳細は各施設のリンクを参照してください。' where id = 'Om2vn3GkJvzc8q__VVmCm';
update content_bodies set title = 'Enjoying Aso City on Rainy Days: Recommended Sightseeing Plan with Traditional Cafes, Workshops, and Hot Springs!', description = 'This guide presents a sightseeing plan for Aso City that allows you to enjoy your time even on rainy days. It features cozy and stylish spots where you can relax. The plan includes a visit to the hidden tea house, Chakura Cafe, known for its charming atmosphere. Next, you can explore handmade goods at KHO, a shop that offers unique crafts. Finally, unwind at one of Aso''s famous hot springs, providing a perfect way to enjoy the rainy weather. Links to the cafe, the handmade shop, and the hot spring association are provided for more information.' where id = '-yohTo_Y2i74BNC317Dfp';
update content_bodies set title = '九州きっての絶景阿蘇', description = 'この動画では、九州の中でも特に美しい風景を持つ阿蘇について紹介しています。' where id = 'WaDUqmb8zV0v9xnvL2Rjr';
update content_bodies set title = 'Aso, Kyushu''s Breathtaking Scenery', description = 'This video introduces Aso, known for its stunning landscapes in Kyushu.' where id = 'zUmxdORiUSUY6Kq1qJQT_';
update content_bodies set title = 'バイクの聖地阿蘇をツーリング！大観峰 ～道の駅阿蘇 #1後編', description = 'この動画では、バイクの聖地である阿蘇のおすすめツーリングコースを紹介しています。大観峰を出発し、ミルクロード、城山展望所、国造神社、幸せの一本道、あそ四季彩（直売所）、阿蘇神社を経て、道の駅阿蘇までのルートを走ります。オープニングではコースの説明があり、その後各スポットの紹介が続き、絶景や地元の魅力が楽しめる内容となっています。' where id = 'h5xuNEIAJj4lV0T6hvtFd';
update content_bodies set title = 'Motorcycle Pilgrimage in Aso! Daikanbo - Aso Road Station #1 Part 2', description = 'This video introduces recommended touring routes in Aso, a sacred place for motorcyclists. The journey starts from Daikanbo and includes the following stops: Milk Road, Shiroyama Observatory, Kunizukushi Shrine, Happy Road, Aso Shikisai (direct sales shop), Aso Shrine, and ends at Aso Road Station. The video features an opening with a course explanation, followed by segments showcasing each location, including scenic views and local attractions.' where id = 'o-2FcMHmGW3l-1gRzkvog';
update content_bodies set title = 'バイクの聖地阿蘇をツーリング！道の駅阿蘇～大観峰 #1前編', description = 'この動画では、バイク愛好者にとっての聖地である阿蘇のおすすめツーリングコースを紹介します。道の駅阿蘇を出発し、ASO MILK FACTORY、山田パーキング、湯浦パーキングを経て、大観峰までのルートを走ります。オープニングではコースの説明があり、道の駅阿蘇からのスタートが紹介され、各スポットの魅力や美しい景色が映し出されます。動画の最後には、次回の内容の予告があります。' where id = 'Zwi_LFq3EXQwuvb1x8X6i';
update content_bodies set title = 'Touring the Sacred Land of Motorcycles: Aso! Road Station Aso to Daikanbo #1 Part 1', description = 'This video introduces recommended touring routes in Aso, a sacred place for motorcycle enthusiasts. The journey starts from Road Station Aso and includes stops at ASO MILK FACTORY, Yamada Parking, Yuura Parking, and finally Daikanbo. The video features an opening with a course explanation, followed by the start at Road Station Aso, and highlights each stop along the way, showcasing the beautiful scenery and attractions. The video concludes with a preview of the next part.' where id = 'rh87Wy4nLEI0gcXkI58FF';
update content_bodies set title = '阿蘇リゾート Ver1', description = '絶景や宿泊施設、美味しい食事、さまざまな体験が楽しめる阿蘇市の魅力を紹介します。阿蘇リゾートの見所が満載です。' where id = 'hJHXbd8ipI4Ps4_EaBfaG';
update content_bodies set title = 'Aso Resort Ver1', description = 'Aso City is filled with stunning views, accommodations, food, and experiences. This introduction showcases the highlights of Aso Resort.' where id = 'OuZ5vdGeD_6OQqkjVy69o';
update content_bodies set title = '【阿蘇デートにおすすめ！】9月下旬までの限定絶景！波野そば畑', description = '秋の阿蘇デートにぴったりな「波野そば畑」は、9月下旬までしか見ることができない美しい景色です。700万本の白いそばの花が丘全体を覆い、まるで絵本の中にいるような幻想的な光景が広がります。帰りには「道の駅波野 神楽苑」で「そばソフト」を味わうのもお忘れなく！ただし、そば畑周辺には駐車場がないため、訪れる際は県道214号沿いの駐車場を利用してください。' where id = '31oK4XbsekL2LJ7Nsyotj';
update content_bodies set title = 'Recommended for Aso Dates! Limited Scenic View Until Late September! Namino Soba Field', description = 'The Namino Soba Field is a picturesque spot perfect for autumn dates in Aso, only visible until late September. The field is covered with 7 million white buckwheat flowers, creating a scene reminiscent of a storybook. Don''t forget to stop by ''Michi no Eki Namino Kaguraen'' on your way back to enjoy their ''soba soft'' ice cream! Please note that there is no parking available near the soba field, so use the parking area along Prefectural Road 214 when you visit.' where id = 'A2b24gSAqA9bC4uKapkoW';
update content_bodies set title = '神楽フェスダイジェスト　約10時間を約10分まとめ', description = '2023年10月7日に開催された「第32回 神楽フェスティバル」では、約10時間の舞台を約10分のダイジェストにまとめました。出演団体は、波野小学校子ども神楽クラブ（熊本県阿蘇市）、城原神楽保存会（大分県竹田市）、波野中学校神楽クラブ（熊本県阿蘇市）、下来原西組神楽社中（島根県浜田市）、波野太鼓 黒鶫（熊本県阿蘇市）、中江岩戸神楽保存会（熊本県阿蘇市）、横堀岩戸神楽保存会（熊本県阿蘇市）、宇目神楽保存会（大分県佐伯市）、御嶽流奥畑神楽（大分県豊後大野市）です。' where id = 'vXtOBTCpilYCmqTdajRhM';
update content_bodies set title = 'Kagura Festival Digest: Summarizing 10 Hours into 10 Minutes', description = 'The 32nd Kagura Festival was held on October 7, 2023, featuring approximately 10 hours of performances condensed into a 10-minute digest. The festival showcased various groups in the following order: the Wave Elementary School Children''s Kagura Club from Aso City, Kumamoto; the Jōhara Kagura Preservation Society from Takeda City, Oita; the Wave Junior High School Kagura Club from Aso City, Kumamoto; the Shimoekihara Nishi Group Kagura Society from Hamada City, Shimane; the Wave Taiko Black Thrush from Aso City, Kumamoto; the Nakagoe Iwato Kagura Preservation Society from Aso City, Kumamoto; the Yokobori Iwato Kagura Preservation Society from Aso City, Kumamoto; the Ume Kagura Preservation Society from Saiki City, Oita; and the Ontake-ryu Okubata Kagura from Bungo-Ono City, Oita.' where id = 'YDw2i3APyDJA1_YkRvROR';
update content_bodies set title = '阿蘇市夏の穴場スポット3選', description = 'この記事では、阿蘇市の夏の穴場スポットを3つ紹介します。まずは阿蘇淡水魚センターで、営業時間は午前10時から午後5時までで、10月から2月は休業します。次に、女学校跡にある湧水かんざらしの店があり、こちらは午前10時から午後6時まで営業し、水曜日が定休日ですが、祝日の場合は翌日が休みです。最後に、ポケットパーク湧水があり、リラックスできる環境を提供しています。これらのスポットは、阿蘇で夏を楽しむためのユニークな体験を提供します。' where id = 'ZEBqZAYEzcwWs6-ckUIY3';
update content_bodies set title = 'Three Hidden Summer Spots in Aso City', description = 'This article introduces three hidden summer spots in Aso City. The first is the Aso Freshwater Fish Center, open from 10 AM to 5 PM, closed from October to February. The second is the former girls'' school site, which features a shop called Yusui Kanzarashi, operating from 10 AM to 6 PM and closed on Wednesdays (or the following day if a holiday). Lastly, there is the Pocket Park Yusui, which offers a relaxing environment. Each location provides a unique experience for visitors looking to enjoy the summer in Aso.' where id = 'BTifigHsfs-CGXBrAe6rk';
update content_bodies set title = '道路に畳を敷いてお花見！阿蘇門前町商店街の「お座敷商店街」', description = '2023年4月2日、熊本県阿蘇市の阿蘇神社近くの門前町商店街で、道路に畳を敷いて花見を楽しむイベント「お座敷商店街」が開催され、多くの人で賑わいました。今年は演歌歌手の「茜つばき」さんが来場し、歌で会場を盛り上げていました。このイベントは毎年桜の時期に開催されるので、ぜひ遊びに来てください！' where id = 'aoJ1PKhm2mZ1LVNRS6Tgf';
update content_bodies set title = 'Tatami Mats on the Road for Cherry Blossom Viewing! ''Ozasiki Shopping Street'' in Aso Monzen Town', description = 'On April 2, 2023, the ''Ozasiki Shopping Street'' event took place in the Monzen Town shopping district near Aso Shrine in Aso City, Kumamoto Prefecture, where tatami mats were laid out on the road for people to enjoy cherry blossom viewing. The event attracted a large crowd! This year, the enka singer ''Akane Tsubaki'' performed, energizing the venue with her songs. The event is held annually during the cherry blossom season, so be sure to visit!' where id = 'IwthLP-WQbSWjBKeSaEHG';
update content_bodies set title = '阿蘇の四季と温泉', description = '阿蘇は四季の移ろいが美しい地域であり、各季節の特徴を楽しむことができます。年間を通じてさまざまな祭りやアクティビティが行われ、また、阿蘇の名物である温泉も楽しむことができます。' where id = 'C6fpzHA6ENYbguJiIaii_';
update content_bodies set title = 'Seasons and Hot Springs of Aso', description = 'Aso is known for its beautiful seasonal changes, showcasing the unique characteristics of each season. Visitors can enjoy various festivals and activities throughout the year, as well as the region''s famous hot springs.' where id = 'pADPJGB4vCiXuoAu-rimx';
update content_bodies set title = '阿蘇の夏', description = '阿蘇の夏は、四季の美しさが際立つ時期です。この地域は、涼やかな湧水と広大な草千里で知られており、夏の間にその魅力が一層引き立ちます。' where id = 'gNVuxXHbOKaKEatRLRoWQ';
update content_bodies set title = 'Summer in Aso', description = 'Aso''s summer is characterized by its vibrant seasonal beauty. The region is known for its refreshing spring water and the expansive grasslands of Kusasenri, which come alive during this season.' where id = 'AcWqyd4rqAkfv1vrblSf-';
update content_bodies set title = '阿蘇の冬', description = '阿蘇の冬は、四季を彩る特別な季節であり、自然や風景の美しさを堪能できる時期です。' where id = '7TEflBTmu8b42kvPINPV9';
update content_bodies set title = 'Winter in Aso', description = 'Aso''s winter is a season that adds color to the four seasons, showcasing the beauty of nature and landscapes.' where id = 'mAw7kvuKqd2zQjZ3QYs2G';
update content_bodies set title = '恋人たちのイルミネーション in 阿蘇内牧温泉', description = '阿蘇市内牧の「泉大橋」の両側に、心を打つ光のアートが登場しています。このイルミネーションは2023年3月14日(火)まで点灯されます。訪れる際は、阿蘇市農村環境改善センターの駐車場を利用することが推奨されています。' where id = 'vUCEI356YRxapiKcDfWCy';
update content_bodies set title = 'Illumination for Lovers in Aso Nakama Onsen', description = 'A beautiful light art display has been set up on both sides of the Izumi Ohashi bridge in Aso City, Nakama. The illumination will be lit until March 14, 2023. Visitors are encouraged to use the parking facilities at the Aso City Agricultural Environment Improvement Center.' where id = '1m7OkQm8r0ljhy42aYr-6';
update content_bodies set title = '阿蘇キャンドルナイト2022 in 乙姫', description = '人と人との距離を保たなければならない今だからこそ、同じ体験を通して心をつなげたいという思いがあります。2020年12月に阿蘇で灯った希望の光は、今年で3年目を迎えます。' where id = 'AL6U2m89nMJiRt7q8jgp2';
update content_bodies set title = 'Aso Candle Night 2022 in Otohime', description = 'In a time when we must maintain distance from one another, we aim to connect hearts through shared experiences. The hope that was lit in Aso in December 2020 marks its third year this year.' where id = 'C7jIBs-ibXzQUOA3GMZYV';
update content_bodies set title = 'デートにも使える！夏の阿蘇市おすすめ観光コース！', description = 'このガイドは「水」をテーマに、阿蘇駅を出発点として阿蘇山へ向かう観光コースを紹介します。マス釣りが楽しめるスポットや阿蘇神社、湧き水が豊富な阿蘇門前町商店街、女子に人気のかんざらしが楽しめる旧女学校跡など、多彩な観光地が含まれています。阿蘇パノラマラインや草千里、阿蘇淡水魚センターなどの名所も訪れられ、地元のカフェやショップも楽しめます。このコースは、阿蘇市の自然美と文化遺産を探索したいカップルに最適です。' where id = 'QcmZA2v27AMMaBSKJ1VzY';
update content_bodies set title = 'Recommended Summer Sightseeing Course in Aso City for Dates!', description = 'This guide focuses on the theme of ''water'' and starts from Aso Station, leading to Aso Mountain. It includes spots for trout fishing, Aso Shrine, and the Aso Monzen Town shopping street, known for its abundant spring water. Additionally, it highlights the popular photo spot, the old girls'' school ruins, where visitors can enjoy refreshing ''kanzarashi'' sweets. The itinerary features various attractions such as the Aso Panorama Line, Kusasenri, and the Aso Freshwater Fish Center, along with local cafes and shops. The course is perfect for couples looking to explore the natural beauty and cultural heritage of Aso City.' where id = 'pqWZ5wk7s-Qw9COeWpMPc';
update content_bodies set title = '【一面真っ白】2022年波野のそば畑に行ってきました。', description = '阿蘇市波野のそば畑では、そばの花が満開を迎え、一面真っ白な美しい景色が広がっています。場所は熊本県阿蘇市波野大字波野3756-2です。そば畑の周辺には駐車場がないため、熊本県道214号沿いの駐車場に車を停め、徒歩で約5分の距離を歩くことをお勧めします。' where id = 'i3oGFzU8FBDriepc2nnTU';
update content_bodies set title = 'Visit to the Buckwheat Fields in Namino, 2022', description = 'The buckwheat flowers in the fields of Namino, Aso City, are in full bloom, creating a stunning landscape of pure white. The location is at 3756-2 Namino, Aso City, Kumamoto Prefecture, 869-2806. There is no parking available near the fields, so it is recommended to park at the nearby parking lot along Kumamoto Prefectural Road 214 and walk for about five minutes to reach the fields.' where id = 'KSbs_Pg07LRTNxaUgFHXx';
update content_bodies set title = '阿蘇へ、恋。～All need is Love 恋人の聖地プロジェクト【阿蘇市公式MOVIE】', description = '熊本県阿蘇市は、恋人の仲を深めるスポットとして注目を集めている神秘的なエリアです。恋愛運アップや縁結びのご利益があるとされ、カップルや女子たちの間で人気が高まっています。阿蘇市では「恋人の聖地化プロジェクト」を進めており、自然豊かな阿蘇カルデラの麓で、ハートをテーマにした名物グルメやカップルで楽しめる体験が提供されています。2022年には、SNS映えするスポットや楽しいアクティビティが続々登場し、訪れる人々はカメラを持って「恋愛の聖地」を楽しむことができます。' where id = 'FVb6xhGhy3y6dGCDcGO8Z';
update content_bodies set title = 'Aso, Love. - All need is Love: Lovers'' Sacred Site Project [Aso City Official MOVIE]', description = 'Aso City in Kumamoto Prefecture is gaining attention as a mystical area where couples can deepen their relationships. Known for its love-related benefits like improved romance luck and matchmaking, Aso City is part of the ''Lovers'' Sacred Site Project'' under the slogan ''Aso, Love. - All need is Love.'' The city is creating heartwarming spots amidst the beautiful Aso caldera, offering unique romantic experiences and delicious heart-themed gourmet food. In 2022, various attractions that are perfect for social media sharing, such as picturesque views and fun activities for couples, are being introduced. Visitors are encouraged to explore this ''sacred site of love'' with their cameras in hand.' where id = '9m2w_oivTbyOYHqYCJDgg';
update content_bodies set title = '初詣におすすめ！子宝スポット！乙姫子安河原観音をご紹介！', description = '初詣におすすめの子宝スポットである乙姫子安河原観音について紹介します。この場所は、子宝を願う人々に特に人気があります。' where id = 'XlXBUyea-ZCRTc1eFKDmg';
update content_bodies set title = 'Recommended for Hatsumode! Introducing the Childbirth Spot: Otohime Koyasugawara Kannon!', description = 'This article introduces Otohime Koyasugawara Kannon, a recommended spot for Hatsumode, especially for those seeking blessings for childbirth.' where id = 'SyvLH72GsO1KtRqsKjNCQ';
update content_bodies set title = '動画でみる　阿蘇神社「御田植神幸式」（通称 御田祭）', description = '2021年の阿蘇神社「御田植神幸式」（通称 御田祭）は、残念ながら新型コロナウイルスの影響で中止となりました。しかし、2019年の祭りの模様を動画で楽しむことができます。御田祭は、地域の伝統行事として重要な役割を果たしており、毎年多くの人々が参加します。2021年は開催されませんでしたが、過去の映像を通じてその雰囲気を感じることができます。' where id = 'QR1i-wNaJvaPQrzB0ewds';
update content_bodies set title = 'Aso Shrine''s Rice Planting Festival (Ota Matsuri)', description = 'The 2021 Aso Shrine''s Rice Planting Festival (commonly known as Ota Matsuri) was unfortunately canceled due to the impact of COVID-19. However, you can enjoy a video of the event from 2019!' where id = 'oJk2giJOAPFYvYix4-2OR';
update content_bodies set title = 'JR九州「あそぼーい！」10年の軌跡', description = 'JR九州の観光特急「あそぼーい！」の運行開始10周年を記念し、WebTVアソが過去の映像を再編しました。「あそぼーい！」は通常、週末に熊本駅と別府駅間で1往復運行していますが、令和3年7月22日から8月31日までの夏休み期間中は毎日運行される予定です。この夏は「あそぼーい！」に乗って、ぜひ阿蘇にお越しください！' where id = 'W7vvHhcwHz5cjRZDmZ6XK';
update content_bodies set title = 'The 10-Year Journey of JR Kyushu''s ''Asoboy!''', description = 'To commemorate the 10th anniversary of JR Kyushu''s sightseeing limited express ''Asoboy!'', past footage has been re-edited by WebTV Aso. Typically, ''Asoboy!'' operates one round trip between Kumamoto Station and Beppu Station on weekends. However, during the summer vacation period from July 22 to August 31, 2021, it is scheduled to run daily. This summer, we invite you to ride ''Asoboy!'' and visit Aso!' where id = '8SmL8l6zbaTLx8bYehCjx';
update content_bodies set title = '2020 阿蘇市の紅葉', description = '2020年は紅葉の当たり年とされ、コロナ禍で旅行や外出を控えている方々のために、阿蘇市の紅葉を旅行気分で楽しめる形で紹介します。旅のスタート地点は大観峰で、ゴールはこの時期に人気の根子岳を目指します。途中にはお寺や神社など、阿蘇市の紅葉スポットを紹介するので、ぜひお見逃しなく。' where id = 's24OWXStYNCy2CrJomolw';
update content_bodies set title = 'Autumn Foliage in Aso City 2020', description = 'The year 2020 is said to be a great year for autumn foliage. Due to the COVID-19 pandemic, many people are refraining from traveling and going out, so this time we will introduce the autumn colors of Aso City in a way that allows you to enjoy the feeling of travel. The journey starts at Daikanbo and aims for the popular Nekodake during this season. Along the way, we will introduce various autumn foliage spots in Aso City, including temples and shrines, so don''t miss out.' where id = 'cTTSYGDqdV46wPoDOS5zn';
update content_bodies set title = '阿蘇市の立ち寄り湯～坊中エリア～', description = '阿蘇市で日帰り入湯ができる温泉を紹介します。今年は寒さとコロナの影響で例年より厳しい冬となっていますが、感染対策をしっかり行い、ぜひ阿蘇の温泉を訪れてください。紹介されている温泉には、阿蘇の司ビラパークホテル＆スパリゾートや、阿蘇坊中温泉「夢の湯」が含まれています。' where id = 'EbUNNfwWGYZlp5PTFsfOK';
update content_bodies set title = 'Hot Springs in Aso City - Bōchū Area', description = 'This article introduces day-use hot springs in Aso City. This winter has been particularly harsh due to cold weather and COVID-19, but with proper infection control measures in place, we encourage you to visit Aso''s hot springs. Featured locations include Aso''s Tsukasa Villa Park Hotel & Spa Resort and Bōchū Onsen ''Yume no Yu.''' where id = 'hQaWyw2--cvVaIJQTEfU1';
update content_bodies set title = '阿蘇市のテイクアウトランチスポット～阿蘇エリア・その２～', description = '阿蘇の大自然でランチを楽しみたい方に向けて、この動画では阿蘇市でテイクアウトできる食べ物を楽しめるおすすめの休憩スポットを全4エリアに分けて紹介します。第2回では、阿蘇谷と呼ばれる平地エリアにある遊具のある公園や穴場の絶景スポットを取り上げます。' where id = 'L2k0S2PSEPN7VbVd94DzO';
update content_bodies set title = 'Takeout Lunch Spots in Aso City - Aso Area Part 2', description = 'If you want to enjoy lunch in the great nature of Aso, this video introduces recommended rest spots where you can eat takeout food in Aso City, divided into four areas. In this second installment, we will showcase parks with playground equipment and hidden scenic spots in the flat area known as Aso Valley.' where id = 'bKXV74dQv3lkSKIWZ-52_';
update content_bodies set title = '三陸ジオパークVRムービー（御石海岸）', description = '三陸ジオパークVRムービーは、岩手県大船渡市に位置する御石海岸を紹介しています。この地域は、独特な地質構造と美しい自然景観で知られており、「リアスの奇妙な形成美」と称されています。' where id = 'klLFjiOmHIo1GA5brEGcK';
update content_bodies set title = 'Sanriku Geopark VR Movie (Goishi Coast)', description = 'The Sanriku Geopark VR Movie showcases the Goishi Coast, located in Ofunato City, Iwate Prefecture. This area is renowned for its unique geological formations and stunning natural beauty, often referred to as ''Rias Strange Formation Beauty.''' where id = 'VQCIyBF70wUiZVz58wVKf';
update content_bodies set title = '紅梅が満開', description = '阿蘇市一の宮町宮地にある井田森二さんの自宅の紅梅が満開を迎えています。春の訪れを感じさせる美しい光景が広がっており、地域の人々にとっても楽しみの一つとなっています。紅梅の花は鮮やかな色合いで、訪れる人々の目を楽しませています。' where id = 'KQhbN6eHK35D7tfGjac4B';
update content_bodies set title = 'Red Plum Blossoms in Full Bloom', description = 'The red plum blossoms at the home of Mr. Morinobu Ida in Ichinomiya Town, Aso City, have reached full bloom.' where id = 'ROARzuBTzP1Cdhpmh9zZ2';
update content_bodies set title = '【バラドーム！！】春の薔薇まつり in はな阿蘇美', description = '阿蘇市小里に位置する観光施設、はな阿蘇美では、温室で育てられたバラの花が見事に満開を迎えています。隣接する売店は現在改装中で利用できませんが、バラ園には無料で入場可能です。' where id = 'sRu7QrZUCNDWccopSdoKA';
update content_bodies set title = 'Spring Rose Festival at Hana Aso Beauty', description = 'The Hana Aso Beauty, a tourist facility located in Kozaki, Aso City, is currently showcasing a stunning display of roses in full bloom, cultivated in its greenhouse. Although the adjacent shops are undergoing renovations and are not accessible at the moment, visitors can enjoy free entry to the rose garden.' where id = '6o5NeNQakYhRPSTJnstLG';
update content_bodies set title = 'そらふねの桟橋への行き方～プチ登山編～', description = '以前にアップした「そらふねの桟橋への行き方」の車道は、森林作業のため全面通行止めとなっています。現在、そらふねの桟橋へは登山道からのみアクセス可能です。駐車場の場所が変更され、田子山トレッキング駐車場（熊本県阿蘇市三久保387、郵便番号869-2302）に駐車する必要があります。この動画では、オープニング、通行止めとなった前回のコース、プチ登山の様子、もう一つの登山道について紹介しています。詳細は阿蘇市の公式発表を参照してください。' where id = 'qf8m6TOWPG1s44GNSa3Hi';
update content_bodies set title = 'How to Access Sorafune''s Pier - Mini Hiking Edition', description = 'The previously shared route to Sorafune''s Pier is currently closed due to forest work, and access is now only possible via hiking trails. The parking location has changed to the Tagoyama Trekking Parking Lot, located at 387 Mikubo, Aso City, Kumamoto Prefecture, 869-2302. The video includes an introduction, a mention of the previous route (now closed), a mini hike on the previous course (also closed), and information about another hiking trail. For more details, refer to the Aso City announcement regarding access to Sorafune''s Pier.' where id = 'wLYF6ruYxz-_4hdVxy3J_';
update content_bodies set title = 'あそべるあそ 前編', description = 'この動画では「こどもが楽しめる阿蘇」をテーマに、阿蘇のおすすめスポットを紹介します。前編では、公園、プール、温泉に焦点を当てています。具体的には、あそビバやあそMTBパーク、とんぼ公園の紹介があり、CatchMealの紹介も行われます。また、クアリゾートオメールのプールや夢の湯の温泉、阿蘇駅周辺の立寄りスポットについても触れています。' where id = 'S_X2-GAchrVDJ-ayYdfrP';
update content_bodies set title = 'Aso Playable Aso Part 1', description = 'This video introduces various spots in Aso where children can have fun, focusing on the theme of ''child-friendly Aso.'' The first part highlights parks, pools, and hot springs. The video includes sections on Aso Viva, Aso MTB Park, and Tombo Park, as well as a feature on CatchMeal. It also covers the Ku Resort Omer for pools and Yume no Yu for hot springs, along with nearby attractions around Aso Station.' where id = '1gIZOFgrpbcqWwvq9GRNW';
update content_bodies set title = 'あそべるあそ 後編', description = 'この動画では「こどもが楽しめる阿蘇」をテーマに、キーワード別におすすめスポットを紹介しています。後編のキーワードは、ふれあい、体験、キャンプです。具体的には、阿蘇カドリー・ドミニオンでのふれあいや、阿蘇草千里乗馬クラブでの体験、果実の国カップルズでの体験、古代の里キャンプ場でのキャンプが紹介されています。また、名水の里(手野)周辺の立寄りスポットも取り上げられています。' where id = 'sBP5QAIOglhZzdEthRC1N';
update content_bodies set title = 'Aso Playable Aso Part 2', description = 'This video focuses on ''Aso for Kids'' and introduces recommended spots categorized by keywords. The keywords for the second part are interaction, experience, and camping. The video includes various attractions such as Aso Cuddly Dominion for interaction, Aso Kusasenri Riding Club for experiences, and CatchMeal. It also features Fruits Country Couples for another experience and the Ancient Village Campground for camping. Additionally, it highlights nearby spots around Meisui no Sato (Tenno) for visitors.' where id = 'T9i17vzIRmMb007Lt8O1R';
update content_bodies set title = '早朝の高岳！美しい朝焼けとミヤマキリシマ', description = '6月6日（金）の早朝に高岳で撮影したミヤマキリシマの花についての記録です。今年の烏帽子岳ではミヤマキリシマの花数が少なかったようですが、高岳では見事に咲いていました。今週から悪天候が続くため、今年の阿蘇市でのミヤマキリシマは見納めになると思われます。この美しい季節がまた来年訪れることを期待しています。' where id = 'fW1gp5d-mFhr4UpLGVCrN';
update content_bodies set title = 'Early Morning at Takadake! Beautiful Sunrise and Miyama Kirishima', description = 'On the early morning of June 6th, I captured the Miyama Kirishima flowers at Takadake. This year, it seems that the number of Miyama Kirishima flowers at Eboshidake was low, but they were beautifully in bloom here. With bad weather expected from this week, it is likely that this will be the last chance to see the Miyama Kirishima in Aso City this year. I look forward to this beautiful season again next year.' where id = 'X06GhD_QkjtgnydwHjSbN';
update content_bodies set title = '【阿蘇】根子岳の紅葉 2023/10/24 撮影', description = '今年も根子岳の紅葉が見頃を迎えています！山頂から紅葉越しに見下ろす阿蘇の風景は圧巻で、赤や黄色のパッチワークのように染まった根子岳の山肌も美しいです。ただし、危険も多い山なので、登山にチャレンジされる際は体調をしっかり整えて、万全の準備で臨んでください。現在は根子岳登山道の3ルートのうち、2ルートが通行不可となっており、この動画撮影の際に通行した「箱石釣井尾根ルート」が唯一の登山道となっています。' where id = 'KLAvYa0drPvA-WLuSXFcX';
update content_bodies set title = 'Autumn Foliage at Nekodake - Captured on October 24, 2023', description = 'This year, the autumn foliage at Nekodake is at its peak! The view of the Aso landscape from the summit, framed by colorful leaves, is breathtaking. The mountainside of Nekodake is beautifully adorned with patches of red and yellow. However, the mountain poses many dangers, so those planning to hike should ensure they are in good health and well-prepared. Currently, two of the three hiking routes to Nekodake are closed, leaving the ''Hakoishi Tsuriin Ridge Route'' as the only accessible path for climbing.' where id = 'eKgJ0QIXqPQjw9okxTToT';
update content_bodies set title = '【幻想的】ゲンジボタル - 阿蘇の夏2022 -', description = '令和4年6月2日、9日、10日に撮影した狩尾四ツ江川のホタルの様子を紹介します。日没と共にホタルの光が点灯し、20時30分頃が最も活発でした。6月13日には梅雨入りしましたが、雨が上がればまだちらほらとホタルが見られるかもしれません。今年は狩尾と古代の里（手野）にしか行っていませんが、阿蘇市内で「今年のホタルは良かった！」という場所があれば、ぜひ教えてください。' where id = '8Ew78M2DHBwM1F2FqvUqD';
update content_bodies set title = 'Fantastical Genji Fireflies - Aso Summer 2022 -', description = 'This captures the fireflies at the Kariyo Yotsue River, photographed on June 2, 9, and 10, 2022. As dusk fell, the fireflies began to light up, with the most activity observed around 8:30 PM. Although the rainy season has started as of June 13, there may still be a few fireflies flying around once the rain stops. This year, I have only visited Kariyo and Kodai no Sato (Tenno), but if there are other locations in Aso City where the fireflies were particularly good this year, please let me know.' where id = 't7uHHiJHuemvInbrWjROZ';
update content_bodies set title = '令和３年阿蘇の風物詩～逆さ涅槃像～', description = '水が張られた田んぼに、阿蘇五岳の美しい山並みが映り込む「逆さ涅槃像」が現れました。この風景は、阿蘇の自然の美しさを象徴するものであり、地域の風物詩として親しまれています。' where id = '0gJzMAu2-8lVLLpirRbVD';
update content_bodies set title = 'The Scenic Beauty of Aso in 2021 - Inverted Nirvana Statue', description = 'The ''Inverted Nirvana Statue'' has appeared, reflecting the majestic Aso Five Peaks in the water-filled rice paddies.' where id = '0glbpLOQKzmioUpUqxXEN';
update content_bodies set title = '2021年冬 草千里の樹氷', description = '令和3年2月19日、草千里展望所周辺で、阿蘇の三大氷のひとつである樹氷が現れました。樹氷は、冬の寒さによって形成される美しい氷の現象で、訪れる人々に幻想的な景色を提供します。草千里はその美しい自然景観で知られ、多くの観光客が訪れる場所です。樹氷の出現は、冬の阿蘇の魅力をさらに引き立てるものとなりました。' where id = '8K4vIzxX76MzF8SvDUVxe';
update content_bodies set title = 'Winter 2021: Frosted Trees at Kusasenri', description = 'On February 19, 2021, frost-covered trees, known as ''Juhyo,'' one of the three major ice formations of Aso, appeared around the Kusasenri Observatory.' where id = 'vWLyN6HigMm-Ft5pIIvx0';
update content_bodies set title = '令和3年1月19日阿蘇空中散歩 古閑の滝', description = '令和3年1月19日に、凍った古閑の滝を撮影しました。この日は阿蘇空中散歩の一環として、自然の美しさを楽しむ機会となりました。古閑の滝はその美しい氷の景観で知られ、訪れる人々に感動を与えています。' where id = 'fWnqh96jkbV5MPhKCgsw4';
update content_bodies set title = 'Aso Aerial Walk on January 19, 2021: Koga Falls', description = 'On January 19, 2021, I captured images of the frozen Koga Falls during the Aso aerial walk.' where id = 'sh5d7ANNeGYqak87RLAsj';
update content_bodies set title = '三陸ジオパークVRムービー（山野岩）', description = '岩手県宮古市に位置する山野岩は、「侵食に耐え、高くそびえる大岩」として知られています。この岩は、その壮大な高さと侵食に対する耐久性が特徴であり、地域の自然美と地質的重要性を示しています。' where id = '8eNbVgyaMNDxnHCMMfhlP';
update content_bodies set title = 'Sanriku Geopark VR Movie (Sanno Rock)', description = 'The Sanriku Geopark VR movie features Sanno Rock, a prominent geological formation located in Miyako City, Iwate Prefecture. This rock is notable for its impressive height and resilience against erosion, showcasing the natural beauty and geological significance of the region.' where id = 'xyWNZzNWNP3lAmQHCjXe4';
update content_bodies set title = '三陸ジオパークVRムービー（新明崎）', description = '宮城県気仙沼市に位置する新明崎は、「石灰岩の洞窟に隠された小さな岬」として知られています。この地域は独特の石灰岩洞窟があり、探求する価値のある秘密や自然の美しさを秘めています。' where id = 'Vp_dEEBo8Qan2eqbmYDvA';
update content_bodies set title = 'Sanriku Geopark VR Movie (Shinmeizaki)', description = 'The Sanriku Geopark VR Movie showcases Shinmeizaki, a small cape located in Kesennuma City, Miyagi Prefecture. This area is known for its unique limestone caves, which hold secrets and natural beauty worth exploring.' where id = 'lY2gnAH809CS2KYfaWqzx';
update content_bodies set title = '【大自然4K】「阿蘇 冬景色」高画質 癒し映像', description = '『SCENE of the ASO』シリーズの一環として、自然豊かな阿蘇の風景を4Kカメラで撮影した映像です。第5巻では、厳しい寒さの中でも美しい姿を見せる阿蘇の「冬景色」を紹介します。九州に位置しながらも高い標高を持つ阿蘇では、冬になると様々な氷の芸術が生まれます。阿蘇三大氷と呼ばれる「樹氷」「古閑の滝の氷瀑」「仙酔峡の氷柱」を楽しむことができます。オープニング、中岳、樹氷、古閑の滝、仙酔峡の各セクションがあり、最後には次回の野焼きイベントの予告があります。' where id = 'BscKFPaAdg8OSvE9F8QKv';
update content_bodies set title = 'Aso Winter Scenery in 4K - Healing Nature Footage', description = 'This video is part of the ''SCENE of the ASO'' series, showcasing the rich natural landscapes of Aso captured in 4K. Volume 5 features the beautiful winter scenery of Aso, which reveals its stunning beauty even in the harsh cold. Despite being in Kyushu, Aso''s high elevation creates various ice formations during winter. Viewers can enjoy the three major ice attractions of Aso: ''Juhyo'' (frost-covered trees), ''Koga Falls Icefall'', and ''Sensuikyo Ice Pillars''. The video includes an opening, segments on Nakadake, Juhyo, Koga Falls, and Sensuikyo, and concludes with a preview of the next episode featuring a grass burning event.' where id = '_D-kuEY11_Ji01JgxPXkv';
update content_bodies set title = '三陸ジオパークVRムービー（リアスの南）', description = '三陸ジオパークVRムービーは、南三陸とリアス地域の美しい風景を紹介しています。特に、五石海岸、穴通し磯、ブローホール岩、五石浜、山田湾、オランダ島、気仙沼湾などの名所が取り上げられています。このバーチャル体験を通じて、これらの地域の自然の美しさと地質的な重要性を探求することができます。' where id = 'gAR4xG6HuhrGbzAagAk_y';
update content_bodies set title = 'Sanriku Geopark VR Movie (South of Rias)', description = 'The Sanriku Geopark VR Movie showcases the stunning landscapes of Minamisanriku and the Rias region. It features notable locations such as Goishi Coast, Anatooshi Iso, Blowhole Rock, Goishi Stone Beach, Yamada Bay, Dutch Island, and Kesennuma Bay. This virtual experience allows viewers to explore the natural beauty and geological significance of these areas.' where id = '-97PBlYwJ2cfWuuhwmD2K';
update content_bodies set title = '三陸ジオパークVR映画（災害の伝説）', description = '三陸ジオパークのVR映画は、過去の災害の記憶を未来の世代や世界に伝えることを目的としています。映画では、重要な場所として、たかだ松原の一本松、旧気仙中学校、陸前高田ユースホステル、タピップ45道の駅、太郎の潮止まり、観光ホテルが紹介されています。' where id = '6hptWmCQ4hpQ96yzI4NsE';
update content_bodies set title = 'Sanriku Geopark VR Movie (Legends of disaster)', description = 'The Sanriku Geopark VR Movie aims to convey the memories of past disasters to future generations and the world. It features significant locations such as Takada Matsubara''s One Pine tree, the Former Kesen Middle School, the Rikuzentakada Youth Hostel, the Tapip 45 roadside station, Taro''s Tide Ridge, and the Tourist Hotel.' where id = 'gAgKUFLQOQ9wOEhMI94Ov';
update content_bodies set title = '三陸ジオパークVRムービー（種差海岸）', description = '青森県八戸市に位置する種差海岸を紹介する三陸ジオパークのVRムービーです。この美しい海岸地域の自然の美しさや地質的な形成を強調し、「美しい地球の形成」というテーマを掲げています。' where id = 'FTAq5RXvKKsEbvNseAFS4';
update content_bodies set title = 'Sanriku Geopark VR Movie (Tanesashi coast)', description = 'The Sanriku Geopark VR Movie showcases the Tanesashi coast located in Hachinohe City, Aomori Prefecture. It highlights the natural beauty and geological formations of this stunning coastal area, emphasizing the theme of ''Formation of a beautiful earth.''' where id = 'NQuj_CvwY9h7QG6axZFAh';
update content_bodies set title = '三陸ジオパークVR動画（橋上山）', description = '青森県橋上町に位置する橋上山のVR動画です。この山は「尿と浸食の橋上山」として知られ、独特の地質的特徴を持っています。浸食によって形成された風景が魅力的で、三陸ジオパークの一部として重要な役割を果たしています。' where id = 'SbVjhNK7RM2zPQXKVB53d';
update content_bodies set title = 'Sanriku Geopark VR video (Mt. Hashikami)', description = 'This video showcases Mt. Hashikami, located in Hashikami Town, Aomori Prefecture. The mountain is known for its unique geological features, including urine and erosion formations, which contribute to its distinct landscape.' where id = 'grZdMSAPMyQNFAydHeWN-';
update content_bodies set title = '三陸ジオパークVRムービー（海岸段丘）', description = '三陸ジオパークVRムービーは、青森県橋上町と岩手県平野町の海岸段丘を紹介しています。「生命を育む地球」というテーマのもと、これらの地域の独特な地質的特徴と自然の美しさに焦点を当てています。' where id = 'FJAHzxFTBa8wZUBR85riG';
update content_bodies set title = 'Sanriku Geopark VR Movie (Marine terrace)', description = 'The Sanriku Geopark VR Movie showcases the marine terraces of Hashikami Town in Aomori Prefecture and Hirono Town in Iwate Prefecture. It highlights the theme of ''Earth that fosters life,'' focusing on the unique geological features and natural beauty of these areas.' where id = '-eAeBfyR4UPFKFSB38Hmh';
update content_bodies set title = '三陸ジオパークVRムービー（小袖海岸）', description = '三陸ジオパークVRムービーは、岩手県久慈市に位置する小袖海岸を紹介しています。この海岸は、リーフによってもたらされる豊かな海の生物、特に多様な魚種が生息することで知られています。' where id = '3wk1sporhLKqBbdxKh8Px';
update content_bodies set title = 'Sanriku Geopark VR Movie (Kosode Coast)', description = 'The Sanriku Geopark VR Movie showcases the Kosode Coast located in Kuji City, Iwate Prefecture. This coastal area is known for its rich marine life, particularly the diverse fish species that thrive among the reefs.' where id = 'G8Yf7rmgMrqBlA0W5rEyf';
update content_bodies set title = '三陸ジオパークVRムービー（黒崎）', description = '三陸ジオパークVRムービーは、岩手県普代村に位置する黒崎を紹介しています。この地域は、特に「勇壮な滝を伴う大崖」で知られ、その美しい自然景観が魅力です。黒崎の壮大な風景は、訪れる人々に感動を与えます。' where id = '3T6k2H4wyeh4WtQM56qk6';
update content_bodies set title = 'Sanriku Geopark VR Movie (Kurosaki)', description = 'The Sanriku Geopark VR Movie features Kurosaki, located in Hudai Village, Iwate Prefecture. This area is renowned for its stunning natural beauty, particularly the ''Great cliff with brave waterfall,'' which showcases the dramatic landscapes of the region.' where id = 'sZ9LMm1sZElhBmaCaTQew';
update content_bodies set title = '三陸ジオパークVRムービー（北山崎）', description = '岩手県田野畑村に位置する北山崎の「隆起海岸の美しい景観」を紹介する三陸ジオパークのVRムービーです。このバーチャル体験を通じて、地域の独特な地質的特徴や美しい風景を楽しむことができます。' where id = 'lm8E_d3Lrf_RxuAsA_gft';
update content_bodies set title = 'Sanriku Geopark VR Movie (Kitayamazaki)', description = 'The Sanriku Geopark VR Movie showcases the stunning beauty of the uplift coast at Kitayamazaki, located in Tanohata village, Iwate prefecture. This virtual experience allows viewers to appreciate the unique geological features and scenic landscapes of the area.' where id = 'h94MWb3Y7i5TVSzvhuKFo';
update content_bodies set title = '広島お好み焼き　電光石火', description = '電光石火は、広島風お好み焼きの名店であり、その芸術的な盛り付けと独自の味わいで知られています。食材の新鮮さや伝統的な調理法が、広島の食文化を体験する上での魅力を引き立てています。グルメ愛好家にとって、訪れる価値のある場所です。' where id = 'YuGJXB7h4DmQkC7QpY1cY';
update content_bodies set title = 'Hiroshima Okonomiyaki Denko Sekka - Artistic', description = 'Denko Sekka is a renowned spot for Hiroshima-style okonomiyaki, a savory Japanese pancake. The establishment is celebrated for its artistic presentation and unique flavors, making it a must-visit for food enthusiasts. The use of fresh ingredients and traditional cooking techniques contributes to the overall experience, highlighting the culinary culture of Hiroshima.' where id = 'RyEwTHvmsAejs-o6KxNZW';
update content_bodies set title = '日本の岩手県の世界的な食材', description = '岩手県は日本の北東部に位置し、豊かな自然資源に恵まれた土地と海があり、食の宝庫となっています。この動画では、岩手県の世界的な産物である米、リンゴ、牛肉、海産物を紹介しています。' where id = 'q6vm7lyzTd_lyYEld7BLA';
update content_bodies set title = 'World-class Foods from IWATE, JAPAN', description = 'Iwate, located in the north-east of Japan, is rich in natural resources from both land and sea, making it a treasure trove of food. This video showcases Iwate''s world-class produce, including rice, apples, beef, and seafood.' where id = '1Litk5Moer3kQfdkolbB8';
update content_bodies set title = '北海道ファンマガジンPR動画', description = '北海道ファンマガジンのPR動画は、同誌の内容や魅力を紹介するもので、北海道の美しさや観光名所を映し出しています。この動画は、北海道に関する情報を提供する同誌の魅力を視覚的に伝え、視聴者に北海道についてさらに知ってもらうことを目的としています。' where id = 'qTSqX39PybXiyXuA7rLim';
update content_bodies set title = 'Hokkaido Fan Magazine PR Video', description = 'The Hokkaido Fan Magazine PR video promotes the magazine and its content, showcasing the beauty and attractions of Hokkaido. It serves as a visual introduction to the magazine''s offerings, encouraging viewers to explore more about Hokkaido through the magazine''s platform.' where id = 'WtTAN_XVWirnOa5GdpNf2';
update content_bodies set title = 'SL冬の湿原号が20周年！釧路運転車両所出区から標茶駅入換までを密着', description = 'JR北海道が運行する「SL冬の湿原号」（C11 171号機）が20周年を迎えました。この列車は1月から3月の土日祝を中心に、釧路駅と標茶駅の間を往復運転しています。今回の動画では、釧路運転車両所からの出区、釧路駅での出発、茅沼駅、標茶駅での入換作業に密着しています。出発合図や茅沼駅到着、標茶駅での給水・点検作業など、運行の様子が紹介されています。' where id = 'Ewf1cPVbErcXRkmciD-Mx';
update content_bodies set title = '20th Anniversary of SL Winter Wetland Train! Close-up from Kushiro Depot to Shibecha Station', description = 'The SL Winter Wetland Train (C11 171) operated by JR Hokkaido has celebrated its 20th anniversary. The train runs between Kushiro Station and Shibecha Station mainly on weekends and holidays from January to March. This video closely follows the train''s journey from Kushiro Depot, its departure from Kushiro Station, and the switching operations at Kayano and Shibecha Stations. Key moments include the train''s departure signal, arrival at Kayano Station, and various operational tasks at Shibecha Station, including water supply and inspection before connecting to passenger cars.' where id = 'lMQYNS-ssilqIy4EkBcSc';
update content_bodies set title = '【GOTO_ISLANDS SUMMER 2025.08】', description = '2025年8月に、五島列島の福江島を訪れ、長男と次男と共に墓参りツアーを行う予定です。' where id = 'AfhDz4a52FS7zgCW12DFA';
update content_bodies set title = 'GOTO_ISLANDS SUMMER 2025.08', description = 'In August 2025, a tour to the Goto Islands is planned, specifically to Fukue Island, for a visit to the gravesite with my eldest and second sons.' where id = 'TdDCmLpzhRKSFB95Puazr';
update content_bodies set title = 'キャンプ動画コンテスト用', description = 'このコンテストは九州でのキャンプに関連した動画コンテストで、#動画コンテスト、#九州キャンプ、#キャンプファイヤーというハッシュタグが使われています。手抜きの縦動画のみがエントリーされ、横動画は全くエントリーされませんでした。しかし、実は横動画の方が好きだったという面白い事実があります。' where id = 'Ol_OtcqSd3PPoHkBtElRU';
update content_bodies set title = 'Camping Video Contest', description = 'This is a video contest related to camping in Kyushu, featuring hashtags like #VideoContest, #KyushuCamping, and #Campfire. Only vertical videos, which were made with less effort, were submitted, while horizontal videos were not entered at all. Interestingly, the horizontal videos were the favorites.' where id = '08JHJE9zUE9a0dCukMwUt';
update content_bodies set title = '【ETAGIMA】in 広島', description = '9月に墓参りの際に撮影した同級生との旅動画です。広島や江田島を訪れ、サイクリングを楽しむ様子が収められています。' where id = 'yWSZZ9JNK8d0fCr_29qSc';
update content_bodies set title = 'ETAGIMA in Hiroshima', description = 'A travel video featuring classmates during a visit to graves in September.' where id = 'aR3jArEQ4QRR509c_yS-g';
update content_bodies set title = '直江津港のエクスカーション No.2', description = 'このエクスカーションでは、素晴らしい景色を楽しみながら翡翠探しを体験できます。参加者は、電車またはレンタカーを利用して沿岸の風景を探索することができます。' where id = 'OheorfO2c5JgXAliAxT63';
update content_bodies set title = 'Port of Naoetsu excursion No.2', description = 'This excursion offers a unique experience of jade hunting along the coastal line, complemented by a scenic view. Participants can choose to travel by train or rent a car to explore the area.' where id = 'borETQ575hMylX496VUC_';
update content_bodies set title = '【ローラーリュージュ（ローラーリュージュ）で遊んできた】芦北海浜総合公園', description = '初めまして、片山亀寿と申します。熊本在住で、九州の様々な場所を訪れています。Vlog的な要素や家族、自己満足、個人や企業の応援動画など、ジャンルは多岐にわたりますが、刺激やワクワクを発信したいと思っています。得意なこととして、外資系金融機関での勤務、理学療法士、動画クリエーター、スノーボード、サーフィン、スケート、剣道四段、弓道初段など多彩な資格や趣味があります。気軽によろしくお願いいたします。' where id = 'p272TbNppjO0zz58VF4eS';
update content_bodies set title = 'Playing Roller Luge at Ashikita Seaside Park', description = 'This post introduces the experience of playing Roller Luge at Ashikita Seaside Park. The author, Kameyuki Katayama, resides in Kumamoto and frequently explores various locations in Kyushu. The content is diverse, including Vlog elements, family moments, and support for individuals and businesses, aiming to share excitement and inspiration. Katayama has a background in finance, physical therapy, and video creation, along with various hobbies such as snowboarding, surfing, and martial arts. He encourages readers to connect with him.' where id = 'T5iW9wnV5YQQaI_KzBoo-';
update content_bodies set title = '【五島列島】🏝玉の浦エリア観光廻り🤙　海、アコウ、お食事etc...', description = '初めまして、片山亀寿と申します。長崎県五島列島の美しい景色や秘蔵情報をお届けしています。ぜひ、長崎の魅力を感じていただければと思います。この動画では、玉の浦エリアの観光スポットを巡り、大瀬崎灯台を紹介します。以前ドローンで撮影した映像もあるので、ぜひご覧ください。五島列島に関する様々な情報を毎日YouTubeで更新していますので、チャンネル登録もよろしくお願いします。' where id = 'yIfoSwNNxuUjmqWHxNWYH';
update content_bodies set title = 'Goto Islands: Exploring the Tamanoura Area - Sea, Akou, Dining, etc.', description = 'Hello, my name is Kameju Katayama. I share beautiful scenery and secret information about the Goto Islands in Nagasaki Prefecture that you may not know. I hope you get to see the wonderful charm of Nagasaki. In this video, I explore various tourist spots in the Tamanoura area of the Goto Islands, including the Osezaki Lighthouse, which I previously filmed with a drone. Please check out my earlier YouTube videos for stunning views. I regularly update my YouTube channel with various content about the Goto Islands, so please consider subscribing!' where id = 'eVjcvfn9K8r0tLp-XMU94';
update content_bodies set title = '五島列島のサーフィン冒険', description = '初めまして、五島列島の片山亀寿です。この動画では、長崎県五島列島の美しい景色や隠れた魅力をお伝えします。久しぶりにサーフィンに行くことに決め、一人で海に入るのは少し勇気がいりました。強風の中、波にもまれながら体力を消耗しました。この体験を通じて、自然の力を再認識し、人間の無力さを感じました。エメラルドグリーンの海でのサーフィンはまるでリゾート地にいるようで、心が洗われる思いでした。ゆるっとした動画ですが、楽しんでいただければ嬉しいです。良かったらグッドボタンとチャンネル登録もよろしくお願いします。' where id = 'rItksU7WIurzMvLrQ7GbO';
update content_bodies set title = 'Exploring the Goto Islands: Surfing Adventure', description = 'Hello everyone, I''m Kame from the Goto Islands in Nagasaki Prefecture. In this video, I share the beautiful scenery and hidden gems of this area. After a long time, I decided to go surfing, and it was a bit daunting to go into the ocean alone. The strong winds made it challenging, and I found myself exhausted from the waves. This experience reminded me of the power of nature and how small we are in comparison. Surfing in the emerald green sea felt like being in a resort, refreshing my spirit. I hope you enjoy this laid-back video, and if you do, please give it a thumbs up and subscribe to my channel for more updates from the Goto Islands.' where id = 'SFzEckq3uVLFG9pBvwYa8';
update content_bodies set title = '五島列島【映画の舞台】【パワースポット】妻夫木聡さん出演　あの映画の舞台に子供達と正月に行ってみた❗️絶景絶叫❗️', description = '正月の初撮影は、子供達と共に映画の舞台を訪れ、正月太りを解消するために急遽決定しました。美しい景色と興奮に満ちた旅でしたが、嵯峨野島の映像が誤って消去されてしまい、編集にかけた数時間が無駄になってしまいました。この出来事は、外付けハードディスクの必要性を痛感させるものでした。いつもご視聴ありがとうございます。チャンネル登録もよろしくお願いします。' where id = 'FT4tzzkZUUXKURkGCEOR9';
update content_bodies set title = 'Goto Islands: Movie Location and Power Spot Featuring Satoshi Tsumabuki - A New Year''s Trip with Kids to the Movie''s Setting!', description = 'The first shoot of the New Year was a spontaneous decision to visit a movie location with the kids to shake off the holiday weight. The trip was filled with beautiful scenery and excitement. However, there was a mishap with the footage from Sagano Island, which was accidentally deleted, causing disappointment after spending hours editing. This experience highlighted the importance of having an external hard drive for storage. Thank you for watching, and please consider subscribing to the channel!' where id = 'pJ-Oy3nLVPBBSaDnCWOlI';
update content_bodies set title = 'NIIGATA in 10 優雅で便利な製品 ー「刃物」編ー', description = '「NIIGATA in 10」は、新潟のこだわりやストーリーを持つ製品や熟練の職人技による逸品を10の体験テーマに分類し、新潟の優れたものづくりを国内外に発信するプロジェクトです。第1弾は「刃物」編で、美しくて使いやすい新潟県産品を紹介しています。' where id = 'aWondqy1Z8LW4wqfx5twy';
update content_bodies set title = 'NIIGATA in 10 Elegant and Useful - Knife Edition', description = 'NIIGATA in 10 is a project that categorizes unique products and stories from Niigata, showcasing exceptional craftsmanship and quality. It aims to promote Niigata''s outstanding manufacturing both domestically and internationally through ten experiential themes. The first edition focuses on knives, highlighting beautiful and practical products made in Niigata.' where id = 'pEOYn2HPYplAOqs7ka9YY';
update content_bodies set title = '新潟の美しくて使いやすい製品 -「受け継がれる伝統技術」編 -', description = '「Niigata in 10」は、新潟のこだわりやストーリー性を持つ製品、熟練の職人技によって生み出される逸品を10の体験テーマに分類し、新潟の優れたものづくりを国内外に発信するプロジェクトです。第2弾は「受け継がれる伝統技術」編で、美しくて使いやすい新潟県産品が紹介されます。' where id = 'D1xkpqbCkHkxi1Cr6MEso';
update content_bodies set title = 'Niigata in 10 Elegant and Useful - ''Traditional Techniques Passed Down'' Edition -', description = '''Niigata in 10'' is a project that showcases unique products and stories from Niigata, categorized into ten experiential themes. It highlights the exceptional craftsmanship and products created by skilled artisans, promoting Niigata''s superior manufacturing both domestically and internationally. The second edition focuses on ''Traditional Techniques Passed Down,'' featuring beautiful and practical products from Niigata Prefecture.' where id = 'Cd9sSEJuzq6NCzHVVZ2S9';
update content_bodies set title = '新潟の美しくて使いやすい製品 - 「進化する伝統技術」編', description = '「Niigata in 10」は、新潟のこだわりやストーリーを持つ製品、熟練の職人技によって生み出される逸品を10の体験テーマに分類し、新潟の優れたものづくりを国内外に発信するプロジェクトです。第2弾は「進化する伝統技術」編で、美しくて使いやすい新潟県産品を紹介します。' where id = '_DuDrKL30xP8q-2gaISoq';
update content_bodies set title = 'Niigata in 10 Elegant and Useful - ''Evolving Traditional Techniques'' Edition', description = '''Niigata in 10'' is a project that categorizes unique products and stories from Niigata, showcasing exquisite craftsmanship by skilled artisans. It aims to promote Niigata''s exceptional manufacturing both domestically and internationally. This second edition focuses on ''Evolving Traditional Techniques,'' highlighting beautiful and practical products made in Niigata.' where id = 'e_AZ7bBXl4JOTFbA06J-V';
update content_bodies set title = 'NIIGATA in 10エレガントで便利 - 「数百年を超え現代に息づく伝統技術」編', description = '「NIIGATA in 10」は、新潟のこだわりやストーリー性を持つ製品、熟練の職人技による逸品を10の体験テーマに分類し、新潟の優れたものづくりを国内外に発信するプロジェクトです。第4弾は「数百年を超え現代に息づく伝統技術」をテーマに、美しくて使いやすい新潟県産品を紹介します。' where id = 'D1ma1nMELwyQgNvckeG1q';
update content_bodies set title = 'NIIGATA in 10 Elegant and Useful - ''Traditional Techniques Alive for Hundreds of Years''', description = '''NIIGATA in 10'' is a project that showcases unique products and masterful craftsmanship from Niigata, categorized into ten experiential themes. It aims to promote Niigata''s exceptional manufacturing both domestically and internationally. The fourth installment focuses on ''Traditional Techniques Alive for Hundreds of Years,'' highlighting beautiful and practical products made in Niigata.' where id = '1BKvuzetRQiEvKjaPEw6a';
update content_bodies set title = '新潟スノーリゾートのプロモーションムービー', description = '新潟は、国内外の観光客に人気のスノーリゾートで、広大な純白の雪に覆われた平原の中で、スキーやスノーシュー体験、そり遊びなど、さまざまな雪のアクティビティを楽しむことができます。新潟は、スキーの専門家だけでなく、家族全員にとっても楽しいエリアです。また、訪問者は、自然の中で育まれた米や日本酒、温泉などの「食と飲み物」で心と体を豊かにすることができます。さらに、空中ランタン祭りや小千谷の熱気球祭りなど、さまざまなイベントで壮大な景色を楽しむことができます。新潟でユニークな体験をしてみませんか？' where id = 'uy0tqEW09UdA4D2BVYsh1';
update content_bodies set title = 'Promotion Movie of “Snow Resort Niigata”', description = 'Niigata is a popular snow resort that attracts both domestic and international visitors. It offers a variety of snow activities, including skiing, snowshoeing, and sledding, all set against a backdrop of pristine white snow. This destination caters to everyone, from skiing experts to families looking for fun. In addition to outdoor activities, visitors can indulge in local cuisine, featuring rice from the surrounding nature, Japanese sake, and relaxing hot springs. Niigata also hosts various events, such as the sky lantern festival and the Ojiya hot-air balloon festival, providing breathtaking scenery. Experience the unique charm of Niigata.' where id = 'z-VWmnaGhj9wv_yf0wgMK';
update content_bodies set title = '佐渡港エクスカーション No.3', description = 'このエクスカーションでは、北雪酒造の酒蔵見学が含まれており、参加者は日本酒の製造過程について学ぶことができます。見学の後には、食事や飲み物を楽しむ機会があり、運動の後にリラックスするのに最適な方法となっています。' where id = 'Izigz9gB0FHuUnYEIeilD';
update content_bodies set title = 'Sado Port excursion No.3', description = 'This excursion includes a tour of the Hokusetsu Shuzo sake brewery, where participants can learn about the sake-making process. After the tour, there will be an opportunity to enjoy food and drinks, making it a perfect way to relax after some physical activity.' where id = 'A6TRADQskgfB2ndnA4tnv';
update content_bodies set title = '「新潟スノーリゾート」のプロモーションムービー　雪のアクティビティに焦点を当てて', description = '新潟は、国内外からの訪問者に人気のあるスノーリゾートで、純白の雪に覆われた広大な平原の中でさまざまな雪のアクティビティを楽しむことができます。家族全員で楽しめる旅行先として最適で、スノーシューやスノーモービル、雪上バナナボートなど、多彩な雪のアクティビティを体験できます。新潟でユニークな体験を楽しんでみませんか？スキーを安全に楽しむことをお勧めし、禁止区域でのスキーは避けてください。' where id = 'RMd1sfX-FsKo3TrWWHBIi';
update content_bodies set title = 'Promotion Movie of “Snow Resort Niigata” Focused on Snow Activities', description = 'Niigata is a popular snow resort that attracts visitors from both Japan and abroad, offering a variety of snow activities in its expansive, pristine snowy landscapes. It is an ideal destination for families, where guests can partake in numerous snow-related activities such as snowshoeing, snowmobiling, and banana boating on the snow fields. Niigata promises a unique experience for all who visit. Visitors are encouraged to enjoy skiing safely and to avoid skiing in prohibited areas.' where id = 'bzUgGELp8nVxE24K64JTj';
update content_bodies set title = '「新潟スノーリゾート」プロモーションムービー - 「湯沢」に焦点を当てて', description = '新潟は、国内外の観光客に人気のスノーリゾートで、純白の雪に覆われた広大な平原の中でさまざまな雪のアクティビティを楽しむことができます。特に「湯沢」エリアでは、スキーやスノーシュー、スノーモービル、雪上バナナボートなど、多彩な雪のアクティビティを楽しむことができます。また、温泉や日本酒、美味しい食事も堪能できます。新潟でユニークな体験を楽しんでみませんか？安全にスキーを楽しみ、禁止エリアでのスキーは避けてください。' where id = 'XXqpf6F4IRzKLZSEJlK1W';
update content_bodies set title = 'Promotion Movie of “Snow Resort Niigata” Focused on “Yuzawa”', description = 'Niigata is a renowned snow resort that attracts both domestic and international visitors, offering a variety of snow activities in its expansive, pristine snowy landscapes. The Yuzawa area stands out for its skiing opportunities and diverse snow activities, including snowshoeing, snowmobiling, and banana boating on the snow. Additionally, visitors can indulge in hot springs, sake, and delicious local cuisine. Niigata promises a unique experience for all who visit. Remember to ski safely and avoid prohibited areas.' where id = '2gnIA-jlhz37F54_FlJq6';
update content_bodies set title = '「新潟スノーリゾート」プロモーションムービー　「グルメ」に焦点を当てて', description = '新潟は、国内外からの訪問者に人気のスノーリゾートで、スキーやスノーシュー、そり遊びなど、広大な白銀の大地でさまざまな雪のアクティビティを楽しむことができます。さらに、新潟は美味しい料理でも知られており、日本一の米と酒蔵の数を誇ります。湯沢では、ユニークな超大きなおにぎりを楽しむことができ、100種類以上の日本酒を味わうことができます。新潟では新鮮な海産物、肉、野菜、果物も楽しめるため、アクティビティだけでなく、素晴らしい料理にも満足できるでしょう。' where id = 'sg5HXW4pKv3d_hTqCcKSq';
update content_bodies set title = 'Promotion Movie of “Snow Resort Niigata” Focused on “Gastronomy”', description = 'Niigata is a popular snow resort that attracts visitors from both Japan and abroad, offering a variety of snow activities such as skiing, snowshoeing, and sledding on its expansive white plains. In addition to its winter sports, Niigata is renowned for its exceptional cuisine, particularly its high-quality rice and the largest number of sake breweries in Japan. Visitors can enjoy a unique super-sized rice ball in Yuzawa and sample over 100 different types of sake to find their favorite. The region also boasts delicious seafood, meat, vegetables, and fruits, ensuring that guests are satisfied not only with the activities but also with the culinary delights available.' where id = 'T9lcstuwQnmQF3QHBBZLP';
update content_bodies set title = '「新潟スノーリゾート」観光に焦点を当てたプロモーションムービー', description = '新潟は、国内外の観光客に人気のスノーリゾートで、スキーやスノーシュー、そり遊びなど、純白の雪に覆われた広大な平原でさまざまな雪のアクティビティを楽しむことができます。また、「小千谷のバルーンフェスティバル」や雪原での花火など、訪れる価値のある魅力的な場所やイベントも多数あります。新潟では、長期滞在を楽しむことができ、ユニークな体験をぜひ味わってみてください。' where id = 'aox7-PXKtpcjKopXuGRw8';
update content_bodies set title = 'Promotion Movie of “Snow Resort Niigata” Focused on “Sightseeing”', description = 'Niigata is a popular snow resort that attracts both domestic and international visitors. It offers a variety of snow activities, including skiing, snowshoeing, and sledding on its expansive, pristine snow-covered plains. In addition to these activities, Niigata features numerous attractions and events, such as the Ojiya Balloon Festival and fireworks displays in the snowy landscape. This makes it an ideal destination for a long stay. Experience the unique charm of Niigata and enjoy a memorable winter getaway.' where id = 'tl17BskLSGBenYF-ysh0m';
update content_bodies set title = '新潟港のエクスカーション No.1', description = '越後は美味しい米と水の産地であり、豊かな農業文化が根付いています。このエクスカーションでは、世代を超えて受け継がれてきた酒文化を体験することができます。越後の酒文化を通じて、地域の魅力を深く知ることができる貴重な機会です。' where id = 'Cat_0FE52cvbz8prTg3kj';
update content_bodies set title = 'Port of Niigata excursion No.1', description = 'Echigo is renowned for its rich agricultural heritage, particularly its delicious rice and high-quality water, which are essential for sake production. This excursion offers a unique opportunity to explore the sake culture that has been cherished and passed down through generations in the Echigo region.' where id = 'zCrETZwIrZWmENvnYB9gw';
update content_bodies set title = '佐渡港エクスカーション No.2', description = 'このエクスカーションでは、佐渡の豊かな文化を体験できます。地元の伝統やライフスタイルに浸ることができる多様なアクティビティを楽しんでください。' where id = 'ySF5PasOpnjZxNLzZXTws';
update content_bodies set title = 'Sado Port excursion No.2', description = 'Experience the rich culture of Sado through this excursion. Enjoy a variety of activities that will immerse you in the local traditions and lifestyle.' where id = 'LIRKsLq2Y_3NhMz3g5qWb';
update content_bodies set title = '佐渡港エクスカーション No.1', description = '佐渡金銀山を中心に、北沢浮選場など多彩な観光スポットを楽しむ日帰り旅行です。' where id = 'k_JQhL-u0rPCDNCTNU15_';
update content_bodies set title = 'Sado Port excursion No.1', description = 'Experience a day trip filled with diverse attractions centered around the Sado Gold and Silver Mine, including the Kitazawa Floatation Plant.' where id = 'ESJhUHURu_9tQTpd2tl_2';
update content_bodies set title = '新潟港のエクスカーション No.2', description = 'このエクスカーションでは、文化遺産で知られる伝統的な村・弥彦と、職人の街・燕三条を訪れます。弥彦神社の見学や、弥彦ロープウェイからの景色を楽しむことができます。' where id = '7qLTf9U6p-mCWXEZFD6it';
update content_bodies set title = 'Port of Niigata excursion No.2', description = 'This excursion takes you to the traditional village of Yahiko, known for its cultural heritage, and the city of Tsubame-Sanjo, famous for its craftsmanship. Highlights include visiting Yahiko Shrine and enjoying the views from the Yahiko Ropeway.' where id = 'Ih2MPx3XBGEUNx9Ypdyom';
update content_bodies set title = '直江津港のエクスカーション No.1', description = '美しい景色と素晴らしい食事を楽しむことができる旅行です。自然の美しさを堪能しながら、特別な食体験を味わうことができます。' where id = 'FGDnms9TAPfAh9YyCYrC9';
update content_bodies set title = 'Port of Naoetsu excursion No.1', description = 'This excursion offers a chance to enjoy stunning views and delicious food, making it a perfect trip for those who appreciate beautiful scenery.' where id = 'ISLYBSVmExa8O8J43_TTr';
update content_bodies set title = 'SADO NO KIWAMI Vol.4: 究極のマリンアクティビティ – 海とつながる湖・加茂でのスタンドアップパドル', description = '「SADO NO KIWAMI」、すなわち究極の佐渡は、佐渡に住み、愛し、佐渡を極めた人々を通じて、佐渡のアドベンチャーツーリズムを紹介します。第4巻では、県内最大の湖である加茂湖のSUP（スタンドアップパドル）インストラクター藤井が、SUPの楽しみ方や湖の魅力を語り、佐渡でしか味わえない究極の体験を紹介します。アドベンチャーツーリズムは、自然、アクティビティ、文化の3つの要素のうち、少なくとも2つを組み合わせた体験を通じて、場所の魅力をより深く楽しむ観光の形です。' where id = 'WNETtFb1qRDjAlWzh51cb';
update content_bodies set title = 'SADO NO KIWAMI Vol.4: The Ultimate Marine Activity–Standup Paddling in the Ocean-Connected Lake Kamo', description = 'SADO NO KIWAMI, or Ultimate Sado, highlights adventure tourism on Sado Island through the experiences of its residents. In volume 4, SUP instructor Fujii shares insights on enjoying stand-up paddling at Lake Kamo, the largest lake in Niigata Prefecture. He emphasizes the unique charm of the lake and the ultimate experiences that can only be found on Sado Island. Adventure tourism is defined as a way to deeply appreciate a location by engaging in experiences that combine at least two of the three elements: nature, activity, and culture.' where id = 'Cfv7Yl24vmOxlcEnCHspn';
update content_bodies set title = '佐渡の極vol.03　佐渡まちあるきの極－港町・小木町の町並みと歴史－', description = '「佐渡の極」の第3回では、佐渡に生き、愛し、極めた人々を通じて、佐渡のアドベンチャーツーリズムの魅力を紹介します。今回は、北前船や西廻り航路の寄港地として栄えた港町・小木町でまちあるきガイドを行う笠井さんを通じて、小木の魅力や歴史的な街並みを探ります。佐渡ならではの極上体験をお届けします。アドベンチャーツーリズムとは、「自然」「アクティビティ」「文化」の3要素を2つ以上満たす体験を通じて、その土地の魅力をより深く堪能できる旅行形態です。' where id = 'WmR-RCSCrb8EsigujdF7i';
update content_bodies set title = 'Sado''s Extreme Vol.03 - The Charm of Ogikucho''s Townscape and History', description = 'In the third installment of ''Sado''s Extreme,'' we explore the allure of Sado''s adventure tourism through the experiences of those who live, love, and master Sado. This episode features Kasai, a guide for walking tours in Ogikucho, a port town that flourished as a stopover for Kitamaebune and the western route. Through Kasai''s insights, we will discover the unique charm and historical streets of Ogikucho, offering an unparalleled experience that can only be found in Sado. Adventure tourism is defined as a travel form that allows deeper appreciation of a region''s appeal by fulfilling at least two of the three elements: nature, activities, and culture.' where id = 'SOgOjVpjxl0vr0qn-UFUq';
update content_bodies set title = '佐渡の極vol.02　佐渡サイクリングの極－小佐渡絶景めぐり－', description = '「佐渡の極（きわみ）」の第2回では、佐渡に生き、佐渡を愛する自転車愛好家の鰕名（えびな）さんを通じて、佐渡のアドベンチャーツーリズムの魅力を紹介します。彼はサイクリングの楽しさや、峠の頂上から見える絶景スポットを紹介し、佐渡ならではの極上体験を伝えます。アドベンチャーツーリズムとは、「自然」「アクティビティ」「文化」の3要素を2つ以上満たす体験を通じて、その土地の魅力をより深く堪能できる旅行形態です。' where id = 'xnJAeDmXZTdi-Ta1wbw03';
update content_bodies set title = 'Sado''s Extreme Vol.02 - The Ultimate Sado Cycling Experience: Exploring the Scenic Spots of Ko-Sado', description = 'In this second installment of ''Sado''s Extreme,'' we introduce the allure of adventure tourism in Sado through the experiences of local cycling enthusiast Ebina. He shares the joys of cycling and highlights breathtaking viewpoints accessible from mountain summits, offering unique experiences that can only be found in Sado. Adventure tourism is defined as a travel style that allows deeper appreciation of a region''s charm by fulfilling at least two of the three elements: nature, activities, and culture.' where id = 'BSpNKtAIkT9davzrosdT6';
update content_bodies set title = 'SADO NO KIWAMI Vol. 2: 究極のサイクリング - 小佐渡の素晴らしい景色を探る -', description = '「SADO NO KIWAMI」、すなわち究極の佐渡は、佐渡に住み、佐渡を愛し、佐渡を極めた人々を通じて、佐渡の冒険観光を紹介します。第2巻では、自転車愛好家のエビナさんを通じて、サイクリングの素晴らしさや山の峠からの絶景を紹介し、他では味わえない究極の体験を提供します。冒険観光は、自然、アクティビティ、文化の3つの要素のうち少なくとも2つを含む体験を通じて、場所の魅力をより深く楽しむ観光の形です。' where id = 'An-6f0wjvkohB6QgTPFX7';
update content_bodies set title = 'SADO NO KIWAMI Vol. 2: Ultimate Cycling -Exploring Kosado’s Fantastic Views-', description = 'SADO NO KIWAMI, or Ultimate Sado, highlights adventure tourism on Sado Island through the experiences of its residents who are passionate about the area. In this second volume, cycling enthusiast Mr. Ebina takes center stage, showcasing the joys of cycling and the stunning views from mountain passes on Sado. These unique experiences are exclusive to the island, emphasizing the thrill of adventure tourism, which combines elements of nature, activity, and culture for a deeper appreciation of the destination.' where id = 'TYItZZCp3pX7ch3b4Bp8r';
update content_bodies set title = '佐渡の極vol.01　佐渡滝ツアーの極－名瀑・十郎滝に挑む－', description = '「佐渡の極」は、佐渡に生き、愛し、極めた人々を通じて、佐渡のアドベンチャーツーリズムの魅力を紹介するシリーズです。今回は、滝ガイドの石塚浩之さんを通じて、佐渡の滝の魅力を発信し、特別な体験をお届けします。アドベンチャーツーリズムとは、「自然」「アクティビティ」「文化」の3要素を2つ以上満たす旅行形態で、より深くその土地の魅力を楽しむことができます。また、新潟県観光協会の公式ブログ「たびきち」では、動画取材の様子や撮影の裏話も紹介されています。' where id = 'OaMWfOtbqSuoJ4T9a2Noz';
update content_bodies set title = 'Sado''s Extreme Vol.01 - Challenging the Majestic Juuro Waterfall', description = 'This article introduces the allure of adventure tourism in Sado through the experiences of those who live, love, and master the island. The focus is on Hiroyuki Ishizuka, a waterfall guide who knows Sado''s waterfalls intimately and promotes their charm through waterfall tours. Readers will discover unique experiences that can only be enjoyed in Sado. Adventure tourism is defined as a travel form that allows deeper appreciation of a location by fulfilling at least two of the three elements: nature, activities, and culture. The official blog of the Niigata Prefecture Tourism Association, ''Tabikichi,'' also shares behind-the-scenes stories and video coverage from the tour.' where id = 'UGLsqlJBGHSPq-keZFn0l';
update content_bodies set title = '鹿児島県 伊佐市 日帰り温泉 ７選', description = 'この記事では、鹿児島県伊佐市にある日帰り温泉を7つ紹介しています。それぞれの温泉の特徴や魅力について簡潔に説明しており、訪れる人々が自然の温泉に浸かりながら美しい景色を楽しむことができることを強調しています。また、伊佐市のGoogleマップのリンクや、さらなる交流のためのSNSアカウントも紹介されています。さらに、日本秘湯を攻める会のオリジナルオレンジタオルの販売も促進しており、さまざまなセットで購入可能です。' where id = '79mEbz3lv10ontfDQbdnA';
update content_bodies set title = 'Top 7 Day Onsen in Isa City, Kagoshima', description = 'This article highlights seven recommended day-use hot springs (onsen) in Isa City, Kagoshima. It provides a brief overview of each onsen, including their unique features and attractions. Visitors can enjoy the relaxing experience of soaking in natural hot springs while taking in the beautiful surroundings of the area. The article also includes links to a Google Maps location for Isa City and social media accounts for further engagement. Additionally, it promotes the sale of original orange towels from the Japan Hidden Hot Springs Association, available in various sets.' where id = 'wxgs3K8irv_rrLa0XP6G_';
update content_bodies set title = '佐渡の極vol.04　佐渡マリンアクティビティの極-海とつながる加茂湖のSUP-', description = '「佐渡の極（きわみ）」の第4回では、佐渡に生き、愛し、極めた人々を通じて、佐渡のアドベンチャーツーリズムの魅力を紹介します。今回は、県内最大の湖である加茂湖でSUP（スタンドアップパドル）インストラクターを務める藤井さんに焦点を当て、SUPの楽しみ方や加茂湖の魅力を伝えます。佐渡ならではの極上体験をお楽しみください。アドベンチャーツーリズムとは、「自然」「アクティビティ」「文化」の3要素を2つ以上満たす体験を通じて、その土地の魅力を深く味わう旅行形態です。' where id = 'tO9h8zFBXFSrPobcp-xl1';
update content_bodies set title = 'Sado''s Extreme Vol.04 - The Ultimate Marine Activity in Sado: SUP on Kamo Lake', description = 'In this fourth installment of ''Sado''s Extreme,'' we explore the allure of adventure tourism in Sado through the experiences of those who live, love, and master the island. This episode features Fujii, a SUP (Stand Up Paddle) instructor at Kamo Lake, the largest lake in Niigata Prefecture. He shares insights on how to enjoy SUP and highlights the unique charm of Kamo Lake, offering an unparalleled experience that can only be found in Sado. Adventure tourism is defined as a travel form that allows deeper appreciation of a region by fulfilling at least two of the three elements: nature, activities, and culture.' where id = 'Y307ttUu_yBLSzGaoWyOw';
update content_bodies set title = 'SADO NO KIWAMI Vol. 1: 究極の佐渡の滝 -十郎滝に挑む-', description = '「SADO NO KIWAMI」、すなわち究極の佐渡は、佐渡に住み、佐渡を愛し、佐渡を極めた人々を通じて、佐渡の冒険観光を紹介します。滝のガイドである石塚裕之は、滝の魅力を熟知しており、ツアーを通じてその魅力を伝えます。彼を通じて、他では味わえない究極の佐渡体験を紹介します。冒険観光は、自然、アクティビティ、文化の3つの要素のうち、少なくとも2つを含む体験を通じて、場所の魅力をより深く楽しむ観光の形態です。' where id = 'KPkE9UUZ_qTywzIkNVlza';
update content_bodies set title = 'SADO NO KIWAMI Vol. 1: The Ultimate Sado Waterfall -Tackling Juro Falls-', description = 'SADO NO KIWAMI, or Ultimate Sado, highlights adventure tourism on Sado Island through the experiences of local residents who are passionate about their home. The guide, Ishizuka Hiroyuki, is well-versed in the island''s waterfalls and offers tours that reveal their unique beauty. This initiative aims to provide an unparalleled experience on Sado, emphasizing the combination of nature, activity, and culture that defines adventure tourism.' where id = 'MpCKczNQpQiZsa8ThjDKt';
update content_bodies set title = '大佐渡石名天然杉遊歩道【秋編】', description = '大佐渡山脈の北部に位置する県有林石名団地には、特異な形状の巨杉が生育しています。新潟県では、この雄大な天然杉を安全に観賞できるように遊歩道を整備しました。澄み切った秋空と色づく木々の中で、天然杉の雄大さが一層際立って見えます。' where id = 'kNLcBbf0SwqRHPmS2W_BF';
update content_bodies set title = 'Ogasawara Shina Natural Cedar Walking Path - Autumn Edition', description = 'In the northern part of the Ogasawara Mountain Range, the Shina district of Niigata Prefecture is home to uniquely shaped giant cedars. To allow visitors to safely enjoy these magnificent natural cedars, a walking path has been developed. Against the backdrop of clear autumn skies and colorful foliage, the grandeur of the natural cedars stands out even more.' where id = 'DPa8COFsu2b97PPrS8IRc';
update content_bodies set title = '四国カルスト 天狗高原(2022.5.17)', description = '晴天を期待して四国カルストの天狗高原に行きましたが、結果はやや曇りでした。GW明けの平日だったため観光客は少なく、のんびりと過ごすことができました。道の狭さには毎回うんざりしますが、今回は360°動画よりも高解像度でアップしました。有名なYutuberには「アベンタドールで四国カルスト行ってみた」という動画をぜひ作ってほしいと思います。撮影はInsta360 One X2で行い、編集はInsta360 Studio 2022とFinal Cut Proを使用しました。' where id = 'jsJSD4gdM8-UjY-XEvq_c';
update content_bodies set title = 'Shikoku Karst Tengu Plateau (May 17, 2022)', description = 'I visited the Shikoku Karst Tengu Plateau hoping for clear weather, but it was somewhat cloudy. Since it was a weekday after Golden Week, there were fewer tourists, allowing for a relaxed experience. I always find the narrowness of the roads along the way quite frustrating. This time, I uploaded a higher resolution video compared to my previous 360° videos. I hope a famous YouTuber will create a video titled ''Driving an Aventador to Shikoku Karst.'' The filming was done with an Insta360 One X2, and editing was done using Insta360 Studio 2022 and Final Cut Pro.' where id = 'IjB7Nknc2966xz1Lzoy07';
update content_bodies set title = '【東京中央区観光紹介ムービー】ダイジェスト版（3分版）', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介しています。ダイジェスト版では、中央区の魅力を集約し、歩き、アクティビティ、食、色、人々の各バージョンの特徴を活かしています。歩きバージョンでは、まるで自分が街を歩いているかのような視点を提供し、アクティビティバージョンでは特定の瞬間や場所でしか体験できない祭りや体験を紹介します。食バージョンでは、中央区で味わえる日本の料理を集め、色バージョンでは言葉を必要としない圧倒的な景色を提供し、人々バージョンでは「日本のおもてなし」を基にした市民の素敵な笑顔を集めています。このビデオを観ることで、言葉では表現できない中央区の魅力が明らかになり、視聴者は自分に響く何かを見つけることができるでしょう。' where id = 'sdfxWRWYKc1iaxHGmjLzk';
update content_bodies set title = 'Tokyo Chuo City tourism introduction movie - Digest version (3min. version)', description = 'This promotional video showcases the various attractions of Tokyo Chuo City. The Digest version compiles the highlights of Chuo City, emphasizing the unique aspects of the Walk, Activity, Food, Colors, and People versions. The Walk version offers a perspective as if you are strolling through the streets, while the Activity version captures festivals and experiences unique to specific times and places. The Food version features a variety of Japanese cuisine available in the city, the Colors version presents stunning visuals that speak for themselves, and the People version highlights the warm smiles of the city''s residents, embodying the concept of ''Japanese welcome.'' This video reveals the charm of Chuo Ward in an indescribable way, ensuring viewers find something that resonates with them.' where id = 'q__GoHDHQ09eDYsgiZ-WD';
update content_bodies set title = '東京中央区観光紹介ムービー】ダイジェスト版（1.5分版）', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介しています。ダイジェスト版では、中央区の魅力を「歩」「遊」「食」「彩」「人」のテーマを活かしてまとめています。「歩」版では街を歩いているかのような視点を提供し、「遊」版では特定の瞬間や場所でしか体験できない祭りやアクティビティを紹介。「食」版では、中央区で味わえる日本の美味しい料理を集め、「彩」版では言葉を必要としない圧倒的な風景を提供します。「人」版では、地域の人々の温かい笑顔を集め、「日本のおもてなし」を表現しています。このビデオを通じて、言葉では表現できない中央区の魅力を感じることができるでしょう。' where id = 'aftXK3Hmj18uU-umP4haY';
update content_bodies set title = 'Tokyo Chuo City tourism introduction movie】Digest version (1.5min. version）', description = 'This promotional video showcases the diverse tourist attractions of Tokyo Chuo City. The digest version compiles the city''s appealing aspects, utilizing the Walk, Activity, Food, Colors, and People themes. The Walk version simulates a street-level view, while the Activity version highlights unique festivals and experiences. The Food version features a variety of Japanese cuisine available in the city, and the Colors version presents stunning visuals that speak for themselves. Lastly, the People version captures the warm smiles of the city''s residents, embodying the essence of ''Japanese welcome.'' This video effectively conveys the charm of Chuo Ward in a way that words cannot, ensuring viewers discover something that resonates with them.' where id = 'UOx-SAf4rB2U3dAzVxVxu';
update content_bodies set title = '愛媛県 宇和島市 和霊神社(2019.9.19)', description = '和霊神社は、愛媛県宇和島市に位置し、漁業を中心とした産業の神として中四国で広く崇められている和霊信仰の総本山です。神社は独特の雰囲気を持ち、訪れる人にパワーを与えてくれそうですが、観光客はあまり多くありません。ぜひ、訪れてその魅力を体験してみてください。' where id = '-Hd6dt4NGmgP7Eu275-Il';
update content_bodies set title = 'Uwajima City, Ehime Prefecture - Warei Shrine (2019.9.19)', description = 'Warei Shrine, located in Uwajima City, Ehime Prefecture, is revered as the main shrine of the Warei faith, which is widely worshipped as the deity of industry, particularly fishing, in the Chugoku and Shikoku regions. The shrine has a unique atmosphere that seems to offer spiritual power, yet it attracts relatively few tourists. Visitors are encouraged to come and experience its charm.' where id = '6zavwB1K9ObsuS57OxclY';
update content_bodies set title = '日本で12例の現存天守、宇和島城(2019.9.25)', description = '久々に宇和島城に上りました。城山は結構キツイです。台風の影響だったのか補修工事が行われていました。それにしても可愛いお城ですよ！ぜひ生で見に来て下さいね！' where id = 'lXDXuhOvATC1eR-EFfBfI';
update content_bodies set title = 'Existing Tenshu in Japan: Uwajima Castle (September 25, 2019)', description = 'I recently visited Uwajima Castle. The climb up the castle hill was quite challenging. There were repair works ongoing, possibly due to the impact of a typhoon. Nevertheless, it is a charming castle! I highly recommend visiting it in person!' where id = 'FSRFbg2MpXGrAOqBGxdbP';
update content_bodies set title = '【道後で鬼滅のMMD】極楽浄土', description = '通常は賑わっている道後温泉ですが、コロナの影響でその状況は一変しました。普段なら人が映らない写真を撮ることは難しいですが、今は簡単に撮影できます。状況が改善した際には、ぜひ皆さんも道後を訪れてほしいと思います。道後が元気でないといけません。この作品では、様々なモデルやモーションを使用しており、yurieによる「極楽浄土」のモーショントレースや、GARNiDELiAの音楽が使用されています。なお、この作品は鬼滅の刃公式とは一切関係がなく、MMDを使用した二次創作です。' where id = 'PGyij-QElJJfzywnAuQcD';
update content_bodies set title = 'Dogo Onsen with Demon Slayer MMD: Paradise', description = 'Dogo Onsen, usually bustling with visitors, has been significantly affected by the COVID-19 pandemic. Under normal circumstances, capturing photos without people would be nearly impossible, but now it is quite easy. Once the situation improves, I encourage everyone to visit Dogo, as it needs to regain its vitality. The project features various models and motions, including a motion trace of ''Gokuraku Jodo'' by yurie, and music from GARNiDELiA and covers by other artists. Please note that this work is a secondary creation using MMD and is not affiliated with the official Demon Slayer franchise.' where id = 'EbB8HkMnJvq7xSbpGMq5v';
update content_bodies set title = '宇和島市津島町 津島プレーランド(2020.1.31)', description = '梅祭りに行きましたが、まだ花は5分咲きでしたので、近くの津島プレーランドに寄りました。平日だったため、他に誰もいませんでした。施設利用料が安いため、テニス好きの方にはぜひ訪れてほしい場所です。' where id = 'xOH3hzmiwzDoGrQ4iVOHZ';
update content_bodies set title = 'Tsushima Playland in Tsushima Town, Uwajima City (January 31, 2020)', description = 'I visited the plum festival but found that the flowers were only about 50% in bloom, so I decided to stop by Tsushima Playland nearby. Since it was a weekday, there was no one else around. The facility has low usage fees, making it a great option for tennis enthusiasts to consider visiting.' where id = 'Czf1JL9u0712i5phSNUb7';
update content_bodies set title = '和霊公園 桜便り(2020.4.4)', description = '暴風による被害がほぼ復旧した和霊公園の桜の咲き具合についての報告です。昼間と夕方に撮影した写真が含まれています。' where id = 'gHcbeEJrkm0WcTARey3TV';
update content_bodies set title = 'Cherry Blossom Report from Warei Park (April 4, 2020)', description = 'This report details the blooming status of cherry blossoms in Warei Park, which has mostly recovered from storm damage. Photos were taken during the day and in the evening.' where id = '9cKA2EjVP_zUxsprxWxuY';
update content_bodies set title = '愛媛県松山市 道後 飛鳥乃湯泉インスタレーション', description = '道後温泉別館の飛鳥乃湯泉に、中庭の「ハダカヒロバ」で蜷川実花さんの約230点の花の写真が展示されます。この大規模なインスタレーションは屋外の床も利用され、展示期間は令和3年10月27日から令和6年2月29日までです。10月25日の動画撮影時には立ち入り禁止でしたが、作品をしっかり定着させるための養生期間と思われます。27日からは入場可能となり、蜷川さんのビビットな色使いが道後の新たな撮影スポットを生み出します。皆さんも写真を撮って、インスタやツイッターで道後を盛り上げましょう。「愛媛の元気は道後から！」' where id = 'lg5a7mzOoMYzH8_BxXyDI';
update content_bodies set title = 'Asuka no Yusen Installation in Dogo, Matsuyama City, Ehime Prefecture', description = 'The Asuka no Yusen, a separate building of Dogo Onsen, will feature an installation of approximately 230 flower photographs by Mika Ninagawa in the courtyard''s ''Hadaka Hiroba.'' This large-scale installation will utilize the outdoor flooring as well. The exhibition period is from October 27, 2021, to February 29, 2024. As of October 25, when the video was filmed, access was restricted to ensure the proper installation of the artwork. Visitors will be able to enter starting from the 27th. Ninagawa''s vivid color palette will undoubtedly enhance the space, creating a new photo spot in Dogo. Everyone is encouraged to take photos and share them on social media platforms like Instagram and Twitter to promote Dogo. ''The energy of Ehime starts from Dogo!''' where id = 'y4qpEoMNZ2xeQBLtFl543';
update content_bodies set title = '愛媛県北宇和郡松野町 蔵王神社 一位樫(2019.10.14)', description = '愛媛県北宇和郡松野町にある蔵王神社の一位樫は、愛媛県指定の天然記念物です。この樹木は神社の境内に並んで立つ2本の大樹で、夫婦木とも呼ばれています。残念ながら、神社紹介の動画はアクセスできませんでした。' where id = 'CC1udhZNlZfTjXo1d3KbD';
update content_bodies set title = 'Zao Shrine''s Ichii Tree in Matsuno Town, Ehime Prefecture (2019.10.14)', description = 'The Ichii tree at Zao Shrine in Matsuno Town, Ehime Prefecture, is designated as a natural monument by the prefecture. It consists of two large trees standing side by side within the shrine grounds, commonly referred to as the ''couple trees.'' Unfortunately, the video introducing the shrine could not be accessed.' where id = 'Cs1J__XAUZS376p_NfOjc';
update content_bodies set title = '紫電改展示館(愛南町)[2022.3.4)', description = '愛媛県南宇和郡愛南町の紫電改展示館を訪れました。昭和53年に海底で発見されたというニュースは、当時小学生だった私にとって衝撃的でした。展示されている機体の鋼板の薄さは、戦争の悲しさを伝えています。現在の物騒な状況を考えると、特にその思いが強く感じられます。NO WAR。' where id = 'p8MLqFTHxWKhoOuOhdFAv';
update content_bodies set title = 'Shidenkai Museum (Ainan Town) [2022.3.4]', description = 'I visited the Shidenkai Museum in Ainan Town, Ehime Prefecture. The news of its discovery on the seabed in 1978 was shocking to me as an elementary school student. The thinness of the steel plates of the displayed aircraft conveys the sadness of war. Given the current global situation, this feeling may be even more pronounced. NO WAR.' where id = 'dDLdbtyfaOkzK1ZjmIdJy';
update content_bodies set title = '新型 伊予灘ものがたり(2022.4.30)', description = '国道378号をドライブ中に伊予灘ものがたりに遭遇しました。360°カメラで撮影していたので、その様子をまとめました。本来は車載動画の撮影のはずが、予想外の展開になりました。' where id = 'ns6_MT5L3Ps8S6o917vb1';
update content_bodies set title = 'New Iyonada Monogatari (April 30, 2022)', description = 'While driving on National Route 378, I encountered the Iyonada Monogatari. I captured the experience using a 360° camera and compiled the footage. What was supposed to be a car-mounted video shoot turned into something unexpected.' where id = '09PwiouZHJvHRUEBF0VgY';
update content_bodies set title = 'R378 伊予灘ドライブ-大洲市編-(2022.5.2)', description = 'R378 夕やけこやけラインを八幡浜から大洲に入ったところから新長浜大橋までの伊予灘360°動画です。伊予市の海岸線も良いですが、個人的には大洲市の海岸線が好きです。線路があれば、もっと最高になると思います。' where id = '-2uIhbyqmQf7z6ZSEl4tX';
update content_bodies set title = 'R378 Iyo-nada Drive - Ozu City Edition (2022.5.2)', description = 'This is a 360° video of the R378 Yuyake Koyake Line, capturing the drive from Yahatahama to Ozu, specifically from the entrance to Ozu City to the Shin-Nagahama Bridge. While the coastline of Iyo City is beautiful, I personally prefer the coastline of Ozu City. It would be even better if there were train tracks nearby.' where id = 'lVAGxT0bmtcH_RHccC44B';
update content_bodies set title = '大洲城(2022.4.25)', description = '大洲城の紹介です。駐車場からお城まで徒歩で向かっています。撮影にはInsta360 ONE X2を使用していますが、360°動画の編集に苦労しています。テロップの入れ方に悩んでおり、BGMをつけるべきかどうかも考えています。' where id = 'eR4_rPE_koTUWmsZ0XD5G';
update content_bodies set title = 'Ozu Castle (April 25, 2022)', description = 'This is Ozu Castle. I am walking from the parking lot to the castle. The footage is captured using the Insta360 ONE X2. I am struggling with editing the 360° video and finding the right way to add captions. I wonder if it''s better not to include background music.' where id = '-t9KNihKX1pmf2CEgMb9-';
update content_bodies set title = 'R378 伊予灘ドライブ-伊予市編-(2022.4.30)', description = 'ゴールデンウィークの真っ最中、天気も良かったので伊予灘をドライブしました。途中で鬼列車と並走するというおまけもありました。撮影にはInsta360 One X2を使用し、編集はInsta360 Studio 2022とFinal Cut Proで行いました。' where id = 'eCyD51GuYy-i9ivz3-0UC';
update content_bodies set title = 'R378 Iyo-nada Drive - Iyo City Edition (2022.4.30)', description = 'During the Golden Week, I took a drive along Iyo-nada with great weather. Along the way, I had the bonus experience of running alongside the ''Oni Train''. The video was shot using the Insta360 One X2 and edited with Insta360 Studio 2022 and Final Cut Pro.' where id = 'ncX96b2mL7ZVEOqznHGte';
update content_bodies set title = '内子町八日市護国伝統的建造物群保存地区(2022.5.5)', description = '愛媛県内子町にある「内子町八日市護国伝統的建造物群保存地区」は、明治時代の歴史や情緒あふれる町並みが魅力で、多くの人々に人気があります。この360°動画では、その美しい景観を楽しむことができます。撮影にはInsta360 one X2が使用され、編集にはInsta360 Studio 2022とFinal Cut PROが用いられています。' where id = '5zTK-EdsblxCJp2gFAfdl';
update content_bodies set title = 'Yokaichi Gokoku Traditional Building Preservation District in Uchiko Town (May 5, 2022)', description = 'This is a 360° video showcasing the Yokaichi Gokoku Traditional Building Preservation District in Uchiko Town, Ehime Prefecture, which is popular for its historical and picturesque townscape reminiscent of the Meiji era.' where id = 'OHSjGaCeiNkw7622C_TH9';
update content_bodies set title = '道後温泉 坊ちゃんカラクリ時計', description = '道後温泉駅前に位置する「坊っちゃんカラクリ時計」は、平成6年に道後温泉本館の建設100周年を記念して作られました。この時計は午前8時から午後10時までの間、毎時道後温泉らしい音楽と共にせり上がり、夏目漱石の小説「坊っちゃん」の登場キャラクターが現れます。また、カラクリ時計の隣には、道後温泉の源泉を使用した「足湯」も設置されています。' where id = 'InlncqrfKiYEgUOwuHTLC';
update content_bodies set title = 'Dogo Onsen Botchan Karakuri Clock (November 10, 2022)', description = 'The ''Botchan Karakuri Clock'' located in front of Dogo Onsen Station was created as part of the 100th anniversary project of the Dogo Onsen Honkan, established in 1994. Every hour from 8 AM to 10 PM, the clock rises with music characteristic of Dogo Onsen, featuring characters from the novel ''Botchan.'' Next to the clock, there is a foot bath that uses the hot spring water from Dogo Onsen.' where id = 'KSqlzBIZ83UWHNt9a5Ftx';
update content_bodies set title = '和霊公園・和霊神社360°(2023.01.03)', description = '明けましておめでとうございます。一日、二日と仕事があったため、やっと初詣に出かけることができました。三日なので人はいないかなと思って出掛けたのですが、予想以上に賑わっていました。今年もダラダラとあまり編集することなくありのままで動画を上げて参りますので、よろしくお願いします。' where id = '1gZfRoP5eKQJPOFcvaE62';
update content_bodies set title = 'Warei Park and Warei Shrine 360° (January 3, 2023)', description = 'Happy New Year! After working on the first and second, I finally had the chance to visit for my first shrine visit of the year. I thought there wouldn''t be many people since it was the third, but to my surprise, it was quite lively. This year, I plan to upload videos as they are, without much editing, so I appreciate your continued support.' where id = '-x_WGif66lypV3VUzNE6a';
update content_bodies set title = '現存12天守 宇和島城360°(2023.1.9)', description = '新年を迎え、宇和島城に登ってみました。宇和島市の中心部に位置する丘陵地に建つ宇和島城は、現存12天守の一つであり、宇和島市の数少ない観光資源の一つです。城山は国史跡に指定されており、天守は独立式層塔型の三重三階で、美しい白壁と御殿建築が随所に施されています。優美で印象的な外観ですが、実際に見ると少し小さめで可愛らしいお城です。' where id = 'gDNsRLLlIU_x1_sLEQImM';
update content_bodies set title = 'Uwajima Castle 360° (January 9, 2023)', description = 'In the spirit of the New Year, I decided to visit Uwajima Castle. Located in the center of Uwajima City on a hilly area, Uwajima Castle is one of the twelve existing tenshu (castle towers) in Japan and serves as one of the few tourist attractions in the city. The castle is a national historic site, featuring a three-story, independent-style tower with beautiful white walls and elegant architectural elements throughout. Although it is impressive and charming, upon visiting, one might find it to be slightly smaller than expected.' where id = 'tWf5scAeKzxC8qbp4-4NS';
update content_bodies set title = '愛媛県 宇和島市 伊達博物館 移築に関して', description = '昭和49年に開館した伊達博物館が老朽化に伴い移築されることになりました。移築に関する概要や費用についての情報が提供されています。宇和島市の市政広報番組では、改築事業についての詳細が紹介されています。移築後の集客や収益計画についての懸念があり、建て替えの必要性は認められるものの、観光客を引き寄せるための具体的な戦略が見えないことが問題視されています。今後のスケジュールとしては、基本設計が令和4年8月まで、実施設計が令和5年春まで、トイレやカフェ棟の工事が令和5年春から秋まで行われ、令和9年春には新博物館が開館予定です。' where id = 'p70CcZ1gEgv0aRbxGwC3f';
update content_bodies set title = 'Relocation of Date Museum in Uwajima City, Ehime Prefecture', description = 'The Date Museum, which opened in 1974, is set to be relocated due to aging issues. The announcement includes an overview of the relocation and associated costs. A video from Uwajima City provides further details on the renovation project. There are concerns regarding the museum''s future visitor attraction and revenue generation plans post-relocation. While the necessity for reconstruction due to aging and seismic safety is acknowledged, there is a lack of clarity on how to enhance the museum''s visibility and attract more tourists. The schedule for the project includes basic design completion by August 2022, detailed design until spring 2023, construction of facilities like restrooms and cafes from spring to autumn 2023, and the new museum''s opening in spring 2027.' where id = 'BKnroCmvtM9WL9E1HpRRD';
update content_bodies set title = '西予市 宇和米博物館(2023.4.14)', description = '西予市にある宇和米博物館を訪れました。この博物館は、昭和3年に建築された木造校舎である旧宇和町小学校を移築して使用しています。日本一長い木造建築の廊下（109m）が有名で、毎年秋にはZ-1グランプリという雑巾がけのタイムを競うイベントが開催されています。博物館内では、お米の種類や農機具などの展示が行われています。' where id = 'X7KXYgH39DNxzp78gsZZs';
update content_bodies set title = 'Uwa Rice Museum in Seiyo City (April 14, 2023)', description = 'I visited the Uwa Rice Museum located in Seiyo City. The museum is housed in a wooden school building that was originally constructed in 1928 and relocated for this purpose. It is famous for having the longest wooden corridor in Japan, measuring 109 meters. Every autumn, the Z-1 Grand Prix is held here, where participants compete in a time trial for sliding on cloths. The museum features exhibits on various types of rice and agricultural tools.' where id = 'vSQjfa4UzjDowg6eQkDag';
update content_bodies set title = '愛媛県 宇和島市 和霊公園・和霊神社(2023.5.14)', description = 'この動画は、宇和島市の和霊公園と和霊神社を紹介しています。静止画風の映像で、撮影にはiPhone14が使用されています。音楽はBGMerから提供されています。' where id = 'UzJmxwRqmDqqzDVI3OBEL';
update content_bodies set title = 'Uwajima City, Ehime Prefecture: Warei Park and Warei Shrine (May 14, 2023)', description = 'This video showcases Warei Park and Warei Shrine in Uwajima City. The video has a still image effect. It was filmed using an iPhone 14, and the music is from BGMer.' where id = 'XARNkCiINp5uL-BK4sRTN';
update content_bodies set title = '愛媛県 宇和島市 うわじま牛鬼祭り 海上打上花火', description = '愛媛県宇和島市で開催されるうわじま牛鬼祭りでは、海上で打ち上げられる花火が見どころとなっています。このイベントは祭りのハイライトであり、夜空を彩る鮮やかな色と模様が地元の人々や観光客を魅了します。詳細については、提供されたリンクから本編をご覧ください。' where id = 'WfSzPHeNfFT6DddJbaCgD';
update content_bodies set title = 'Uwajima Ushi Oni Festival Fireworks', description = 'The Uwajima Ushi Oni Festival in Uwajima City, Ehime Prefecture, features spectacular fireworks launched over the sea. This event is a highlight of the festival, showcasing vibrant colors and patterns that light up the night sky, attracting both locals and tourists. For more details, you can watch the main content at the provided link.' where id = '0wTqf31ihPVzqaX6-TKgC';
update content_bodies set title = '高知県高岡郡梼原町 維新の門(2023.9.12)', description = 'この動画では、高知県高岡郡梼原町にある維新の門について紹介しています。維新の門は地域の歴史や文化に関連する重要なスポットであり、訪れる人々にその魅力を伝えています。' where id = '_AN2DCSmB3BHVe6tdKi3x';
update content_bodies set title = 'Ishin no Mon in Yusuhara Town, Takaoka District, Kochi Prefecture (September 12, 2023)', description = 'This video introduces Ishin no Mon, located in Yusuhara Town, Takaoka District, Kochi Prefecture.' where id = 'gMJfceC4lGQP2K5KlzShn';
update content_bodies set title = '伊予市双海町 JR予讃線 下灘駅(2023.9.25)', description = 'ふと思い立って下灘駅に行ってきました。ホームのベンチを取り囲むように多くの人が立っており、撮影が難しい雰囲気でしたが、汽車が入ってきたのでカメラを回しました。近いうちに早朝の誰もいない下灘駅を撮影したいと思っていますが、朝、無事に起きられればの話です。撮影機器はInsta360 One X2です。' where id = 'tUqm9Haf7-tiSZh-UklgK';
update content_bodies set title = 'Shimonada Station on the JR Yosan Line, Iyo City, Futami Town (September 25, 2023)', description = 'I spontaneously decided to visit Shimonada Station, where many people were gathered around the benches on the platform. The atmosphere made it difficult to take photos, but I managed to capture the train as it arrived. I hope to photograph the empty Shimonada Station early in the morning soon, provided I can wake up on time. Equipment used: Insta360 One X2.' where id = 'Tn1n9SGER-61Z7MiF_qrh';
update content_bodies set title = '愛媛県 宇和島市 吉田町 吉田湾(2023.10.12)', description = '知永峠からの夕日が非常に美しかったため、スマートフォンで少しだけ撮影しました。ただし、動画は吉田湾の様子を8分間映したものです。撮影にはiPhone14を使用しました。' where id = 'AnKH3GA3C-09OOHo4hK6S';
update content_bodies set title = 'Yoshida Bay, Uwajima City, Ehime Prefecture (October 12, 2023)', description = 'The sunset from Chien Pass was beautiful, so I took a few photos with my smartphone. However, the video is just an 8-minute long clip of Yoshida Bay.' where id = 'AE09rW-LJnBRTIrXNv-ML';
update content_bodies set title = '愛媛県北宇和郡松野町 虹の森公園 おさかな館(2024.3.5)', description = '虹の森公園おさかな館は、山の中にある淡水魚水族館の独特な雰囲気を提供しています。動画は元々制作するつもりではなかったため、撮影したものをただ繋げただけの内容になっています。残念ながら、ペンギンの撮影は失敗してしまいました。詳細については、虹の森公園おさかな館の公式ウェブサイトをご覧ください。' where id = 'KLhJWqjM2c7SIp6RxhW87';
update content_bodies set title = 'Rainbow Forest Park Fish Museum in Matsuno Town, Ehime Prefecture (March 5, 2024)', description = 'The Rainbow Forest Park Fish Museum offers a unique atmosphere of a freshwater aquarium nestled in the mountains. The video was not originally intended for production, so it consists of simply stitched-together footage. Unfortunately, the penguins were missed in the filming. For more details, please visit the official website of the Rainbow Forest Park Fish Museum.' where id = 'PCKLC_Wf2O61IkisbcRl5';
update content_bodies set title = '本編：伊予市中山町 さくら 絶景エリア(2024.3.31)', description = 'R56の伊予市中山町付近で桜が見事に咲いていたため、撮影を行いました。カメラ(Insta360 OneX2)を車の窓に固定し、撮影後に自宅でアングルを編集しました。360°カメラは非常に便利です。' where id = 'sv6MK2MS6p_XpL-8q42NM';
update content_bodies set title = 'Iyo City Nakayama Town Cherry Blossom Scenic Area (March 31, 2024)', description = 'The cherry blossoms near Nakayama Town in Iyo City along Route R56 were in full bloom, and I captured some footage. I fixed my camera (Insta360 OneX2) to the car window and edited the angles at home. The 360° camera is quite convenient.' where id = 'L-MU8fx4zJbEX227xqCTd';
update content_bodies set title = '宮崎県 えびの市 日帰り温泉 10選', description = 'この記事では、宮崎県えびの市にある日帰り温泉のトップ10を紹介しています。えびの市は美しい自然環境とリラックスできる温泉で知られており、日帰り旅行に最適な場所です。紹介されている温泉は、さまざまなアメニティやユニークな体験を提供しており、地元の人々や訪問者の両方に対応しています。また、温泉文化に関連するソーシャルメディアや商品へのリンクも含まれており、えびの市の温泉を探求する人々にとって、全体的な体験を向上させる内容となっています。' where id = 'x9ZptpV4tpO6O8lHwoxTZ';
update content_bodies set title = 'Top 10 Day Onsen in Ebino City, Miyazaki', description = 'This article presents a selection of the top ten day onsens in Ebino City, Miyazaki. Ebino City is known for its beautiful natural surroundings and relaxing hot springs, making it a perfect destination for day trips. The onsens featured offer various amenities and unique experiences, catering to both locals and visitors. The article also includes links to social media and merchandise related to the Japanese hot spring culture, enhancing the overall experience for those interested in exploring Ebino''s onsens.' where id = 'Fsa0Y-DctuvVjp85GWurW';
update content_bodies set title = '本編：宇和島城 桜便り(2024.4.1)', description = '4月1日、休暇を取り、天候に恵まれたため宇和島城を訪れました。桜は8分咲きから満開に近い状態で、素晴らしい景色を楽しむことができました。コンパクトに作られた宇和島城も、いつも以上に立派に見えました。城と桜の美しさを堪能するには絶好の日でした。' where id = 'zAznmofI55Mzykp3qpq1X';
update content_bodies set title = 'Uwajima Castle Cherry Blossom Report (April 1, 2024)', description = 'On April 1st, I took a day off and visited Uwajima Castle, enjoying the beautiful weather. The cherry blossoms were nearly in full bloom, creating a stunning backdrop. The compactly designed Uwajima Castle appeared even more magnificent than usual. It was a perfect day to appreciate the beauty of the castle and the surrounding cherry blossoms.' where id = 'sVGQ1nis3p68K8lIr-R6a';
update content_bodies set title = '四国自動車博物館スライドショー(2024.7.12)', description = '四国自動車博物館に展示されている車両を一台ずつ撮影した写真を集めたスライドショーです。音楽はBGMerによるもので、詳細はhttp://bgmer.netで確認できます。' where id = 'we9-d4_c9YUIEC66Inj-t';
update content_bodies set title = 'Shikoku Automobile Museum Slide Show (2024.7.12)', description = 'This is a slideshow featuring photographs of each vehicle from the Shikoku Automobile Museum.' where id = 'DtwJ37l58RYYLNVDM6Hx7';
update content_bodies set title = '宇和島闘牛秋場所(2024.10.27)', description = '2024年7月に開催された宇和島闘牛和例大祭場所に続き、宇和島市営闘牛場で宇和島闘牛秋場所が開催されました。気候が良く、吹き抜けの闘牛場で観戦しやすくなると予想され、多くのお客様が県内外から訪れました。お客様ファーストのチャンネルとして、邪魔にならないよう最上階から撮影を行いました。この動画では不戦となった試合を除く10戦中7戦を紹介しています。臨場感には欠けるかもしれませんが、闘牛場の雰囲気は感じていただけると思います。感想や誤字の指摘など、コメントをお待ちしています。撮影機器はiPhone14（光学3倍ズーム）です。' where id = '7pPCQba0fgdNFg_w3XsUs';
update content_bodies set title = 'Uwajima Bullfighting Autumn Event (2024.10.27)', description = 'Following the Uwajima Bullfighting Summer Festival held in July 2024, the Uwajima Bullfighting Autumn Event took place at the Uwajima City Bullfighting Arena. With pleasant weather expected, many spectators from both inside and outside the prefecture attended the event, making it easier to enjoy the open-air arena. The filming was done from the top floor to avoid disturbing the audience, as this is a customer-first channel. This video features 7 out of 10 matches, excluding the ones that did not take place. While it may lack some excitement, viewers can still feel the atmosphere of the bullfighting arena. Comments and feedback are welcome, including corrections for any typos. Filming equipment used: iPhone 14 (optical 3x zoom).' where id = 'q4t8yCwP_f08pX7nxNe2M';
update content_bodies set title = 'うわじま城 - 宇和島城PRソング - (AI Music)', description = '宇和島城をPRする楽曲が制作されました。動画では、宇和島城までの道のりを3倍速で紹介しており、休まず登れば15分以内に到着できるとされていますが、かなり息切れするかもしれません。宇和島観光PR関連の楽曲は増えてきていますが、現時点では配信やCD化の予定はありません。お問い合わせはありますが、状況はそのままです。クラウドファンディングの可能性は検討中です。BGMは「うわじま城」というみーかんチャンネルのオリジナル楽曲で、著作権はみーかんチャンネルにあります。商用利用の場合は事前に連絡が必要です。' where id = 'wdjJJwFqrpXBMjef3FhqC';
update content_bodies set title = 'Uwajima Castle - Uwajima Castle PR Song - (AI Music)', description = 'A song has been created to promote Uwajima Castle. The video shows the journey to the castle at three times the normal speed. It suggests that one can reach the castle in under 15 minutes without stopping, although it may be quite exhausting. While there has been an increase in promotional songs related to Uwajima tourism, there are currently no plans for distribution or CD production. Although inquiries have been made, the situation remains as is. There is a possibility of crowdfunding for this project, which is currently under consideration. The background music is an original piece titled ''Uwajima Castle'' by Miikan Channel, and copyright is held by Miikan Channel. For commercial use, prior contact is required.' where id = 'AaSrV8O2ZfBLQ16c-Y5Dm';
update content_bodies set title = '和霊神社 - 和霊神社の唄 - (AI Music)', description = '宇和島応援ソングの5曲目は和霊神社に関するもので、今回は神社ということで、これまでのようにふざけることなくお届けしています。BGMはみーかんチャンネルのオリジナル楽曲です。著作権はみーかんチャンネルに帰属します。商用利用される場合は事前にご連絡ください。' where id = 'VTSV2D4SmaFri7tPBSBBN';
update content_bodies set title = 'Warei Shrine - Song of Warei Shrine - (AI Music)', description = 'The fifth song supporting Uwajima is about Warei Shrine. This time, we present it without any playful elements, as it is a shrine. The background music is an original piece by Miikan Channel. Copyright belongs to Miikan Channel. Please contact us in advance for any commercial use.' where id = '6Ztotqyk7ELSZPM3fgiLM';
update content_bodies set title = '伊予市双海町 閏住の菜の花(2025.3.5)', description = '伊予市双海町大久保の閏住で菜の花を見に行きました。午前中は雨が降っていたため撮影を迷いましたが、午後から天気が回復したので撮影を決行しました。菜の花はほぼ満開で、今週末には見ごろが確定しています。BGMには「菜の花の約束」（みーかんチャンネルのオリジナル楽曲）を使用しています。著作権はみーかんチャンネルにあり、商用利用の場合は事前にご連絡ください。' where id = 'NGbw-iQespVLIWz8Xj3G_';
update content_bodies set title = 'Nanohana in Urakumi, Iyo City (March 5, 2025)', description = 'I visited the Nanohana (rapeseed flowers) in Urakumi, Okubo, Iyo City. Although it rained in the morning, I decided to take photos in the afternoon when the weather improved. The flowers are almost in full bloom, and they are expected to be at their best this weekend. Background music: ''Promise of Nanohana'' (original song by Mikan Channel). Copyright belongs to Mikan Channel. Please contact us in advance for commercial use.' where id = 'uOIm5M4ke_sw21HL1pAAv';
update content_bodies set title = '伊予市双海町串 日本水仙花開道(2025.2.19)', description = '毎年恒例の双海町の「日本水仙花開道」に行ってきました。満開かなと思いながら訪れたのですが、平日の朝9時台ということで贅沢に貸切状態でした。ただし、他の予定があったため、撮影と編集はざっくりとしたものになっています。主にドラレコ映像を使用しているため、撮影や編集の技術はあまり向上していません。BGMには「SAYONARA -卒業ソング-」(みーかんチャンネルのオリジナル楽曲)を使用しており、著作権はみーかんチャンネルにあります。商用利用される場合は事前にご連絡ください。' where id = 'WvUPe5ORLIa1TywP5UtSR';
update content_bodies set title = 'Japanese Daffodil Flower Road in Futami Town, Iyo City (February 19, 2025)', description = 'I visited the annual ''Japanese Daffodil Flower Road'' in Futami Town, wondering if the flowers were nearing full bloom. Since it was a weekday morning around 9 AM, I enjoyed the luxury of having the place to myself. However, due to other commitments, I could only do a quick shoot and edit. The main footage is from a dashcam, so my filming and editing skills haven''t improved much. The background music is ''SAYONARA - Graduation Song -'' (original composition by Miikan Channel), and copyright belongs to Miikan Channel. Please contact us in advance for commercial use.' where id = 'zDexnj_tzUCneIhsUuh0U';
update content_bodies set title = '宇和島市 名勝 天赦園(2025.4.18)', description = '天赦園の藤がピークを迎えたとのことで訪れました。藤棚（白玉上り藤）は眩しいほどに白く輝いており、いつもは散り際にしか行けなかったため、今回は最高の体験でした。今週末（4月19日、20日）にお時間がある方はぜひ訪れてみてはいかがでしょうか。お客様が少ない時間を狙って朝イチで撮影したため、園内はまだ掃除中でした。掃除が落ち着いた頃がオススメです。BGMには「天赦園」という楽曲が流れており、これはみーかんチャンネルのオリジナルCD「KISAIYA宇和島」に収録されています。宇和島市の食と観光を歌にした観光PRCDですので、興味があればぜひご購入を検討してください。' where id = 'iwK5-XS44aJUpmvVr5ynn';
update content_bodies set title = 'Uwajima City Scenic Spot: Tenshaen (April 18, 2025)', description = 'I visited Tenshaen as the wisteria was at its peak. The wisteria trellis (Shiratama Nobori Fuji) was dazzlingly bright and in full bloom. I usually visit when the flowers are past their prime, so this was a wonderful experience. If you have time this weekend (April 19-20), I highly recommend visiting. I aimed for early morning to capture photos when there were fewer visitors, so the garden was still being cleaned. It’s best to visit once the cleaning settles down. The background music features the song ''Tenshaen,'' included in the original CD ''KISAIYA Uwajima'' sold by Miikan Channel, which promotes Uwajima''s food and tourism through music. If interested, please consider purchasing it.' where id = '7p7o4e9eBxbpXCbt0MpdE';
update content_bodies set title = '新緑の宇和島城(2025.4.18)', description = '天赦園を後にして宇和島城へ登りました。桜は散り、お白山は緑に溢れていました。桜の時期ほどの観光客はいませんでしたが、外国人が多く見受けられました。このことから、英語の学習をサボっている自分を反省しました。BGMには「宇和島城」という楽曲が流れており、これはみーかんチャンネルで販売しているオリジナルCD「KISAIYA宇和島」に収録されています。このCDは宇和島市の食と観光を歌にした観光PRCDです。興味があれば、ぜひご購入を検討してください。オリジナルCDの収録曲は再生リストで聞くことができます。著作権はみーかんチャンネルにあり、商用利用の場合は事前に連絡が必要です。' where id = 'T-Vq4hmPrfylGXQmwon6u';
update content_bodies set title = 'Fresh Green Uwajima Castle (2025.4.18)', description = 'After visiting Tenshaen, I climbed up to Uwajima Castle. The cherry blossoms had fallen, and Mt. Shirayama was lush with greenery. Although there were fewer tourists compared to the cherry blossom season, there were quite a few foreigners. This made me reflect on my neglected English studies. The background music, ''Uwajima Castle,'' is featured on the original CD ''KISAIYA Uwajima'' sold by the Miikan Channel. This CD promotes the food and tourism of Uwajima City through song. If you''re interested, please consider purchasing it. You can listen to the tracks from the original CD on the provided playlist link. The copyright belongs to Miikan Channel, and prior contact is required for commercial use.' where id = 'UUVFWf2x_snuApziIoDZ8';
update content_bodies set title = '宇和島市 津島町 南楽園(2025.5.29)', description = '小雨の中、宇和島市津島町の日本庭園「南楽園」へ行ってきました。現在、夜間延長開園中で21:00まで園内を見ることができます。「竹灯籠の夕べ」として灯籠が飾られ、花菖蒲がライトアップされています。開花状況は園のXによると3割程度ですが、29日時点では5割ほどと感じました。週末には見ごろになるでしょう。BGMは「天空の城 -宇和島城- 秀宗Mix Ver.」(未配信オリジナル楽曲)です。著作権はみーかんチャンネルにあり、商用利用を含むすべての利用は当面禁止です。' where id = 'jyPxNiCVJaHsAJIFf9Y6L';
update content_bodies set title = 'Uwajima City Tsushima Town Nanrakuen (May 29, 2025)', description = 'I visited the Japanese garden ''Nanrakuen'' in Tsushima Town, Uwajima City, on a rainy day. The garden is currently open for extended night hours until 9:00 PM. It features lanterns for the ''Evening of Bamboo Lanterns'' and illuminated iris flowers. According to the garden''s X account, the blooming status is about 30%, but I felt it was closer to 50% as of the 29th. The flowers are expected to be in full bloom over the weekend. Background music: ''Castle in the Sky - Uwajima Castle - Hidemune Mix Ver.'' (original song not yet released). Copyright belongs to Miikan Channel. All uses, including commercial, are prohibited outside of this channel, Instagram, and X.' where id = 'MgBmlTawvVkVGYuoFjBYt';
update content_bodies set title = '新緑映える和霊神社(2025.4.19)', description = 'この動画は、R56和霊公園の鳥居から大鳥居を経て和霊神社までの徒歩の様子を収めています。桜は散り、お白山は緑に包まれています。桜の季節が終わり、春の息吹が感じられる和霊公園の眩しい緑が広がっています。BGMには、みーかんチャンネルが販売するオリジナルCD「KISAIYA宇和島」に収録された「和霊神社」という楽曲が流れています。宇和島市の食と観光をテーマにした観光PRCDですので、興味のある方はぜひご購入を検討してください。オリジナルCDの収録曲は、提供された再生リストで聴くことができます。著作権はみーかんチャンネルにあり、商用利用の際は事前に連絡が必要です。' where id = 'Ul4-zr7bWxvFooG67XT6Y';
update content_bodies set title = 'Fresh Greenery at Warei Shrine (April 19, 2025)', description = 'This video captures a walk from the torii gate of R56 Warei Park to the grand torii gate and then to Warei Shrine. With the cherry blossoms now fallen, Mount Owhite is lush with greenery. The cherry blossom season has ended, and the vibrant greens of spring envelop Warei Park. The background music features the song ''Warei Shrine,'' included in the original CD ''KISAIYA Uwajima'' sold by the Meekan Channel, which promotes the food and tourism of Uwajima City. For those interested, please consider purchasing it. The original CD''s tracklist can be listened to via the provided playlist link. Copyright belongs to Meekan Channel, and prior contact is required for commercial use.' where id = 'AmvZd4Nt_iA5GGSq5jSHQ';
update content_bodies set title = '天空の城-宇和島城-(AI Music 2025.5.11)', description = '本日はきさいや広場で「宇和島EXPO」が開催されていますが、人混みが苦手なため宇和島城へ向かいました。オリジナル楽曲「天空の城-宇和島城-」の歌詞を完成させるために登城しました。コンパクトながら雰囲気のある宇和島城をどのように表現するかを考えています。とりあえず、過去に遡り武士になった気分で創作を進めました。歌は男性ボーカルに変更しました。BGMは「天空の城-宇和島城-」の未配信オリジナル楽曲です。著作権はみーかんチャンネルにあり、商用利用の際は事前にご連絡ください。' where id = 'Wxt2Zos3rIYbTwxMwTlIQ';
update content_bodies set title = 'Sky Castle - Uwajima Castle - (AI Music 2025.5.11)', description = 'Today, the ''Uwajima EXPO'' is taking place at Kisaiya Square, but I decided to visit Uwajima Castle due to my dislike of crowds. I climbed the castle to complete the lyrics for my original song ''Sky Castle - Uwajima Castle.'' I am contemplating how to express the compact yet atmospheric image of Uwajima Castle. For now, I am creating from the perspective of a samurai in the past. The song is now complete. Although the initial preview featured a female vocalist, I have decided to change it to a male vocal for this version. Background music: ''Sky Castle - Uwajima Castle'' (original song not yet released). Copyright belongs to Miikan Channel. Please contact us in advance for commercial use.' where id = 'cHXLX9-liHqENTaCmo5Jx';
update content_bodies set title = '伊達なうわじまお城まつり(2025.5.4)', description = '宇和島市で5月4日と5日に「伊達なうわじまお城まつり」が開催されます。私は4日だけ休みだったので、「秀宗公入部伊達五十七騎大武者行列」を見に行きました。混雑が苦手なYoutuberとしては初めての城まつり参加です。ゴールデンウィーク真っ只中で観光客で賑わう中、十分な撮影ができたので、城山までの行列はパスして帰宅し、曲作りに専念しました。今回の姫は「塩見きら」さんでした。' where id = 'M6Tl2V_QdLoCSXOU0wC5Y';
update content_bodies set title = 'Date Uwajima Castle Festival (May 4, 2025)', description = 'The Date Uwajima Castle Festival is taking place in Uwajima city on May 4th and 5th. Since I only have the 4th off, I went to see the Procession of 57 Date Knights and Lord Hidemune''s Warriors. As a YouTuber who dislikes crowds, this was my first experience at a castle festival. During Golden Week, the area was bustling with tourists, and I managed to capture plenty of footage. However, I decided to skip the procession up to Shiroyama and returned home to focus on writing a song. The featured princess this time was Shiomi Kira.' where id = 'jbWwGy_TQPHb1tKiSmMHQ';
update content_bodies set title = '宮城を訪れよう', description = '宮城県は東京から新幹線で約90分の距離にあり、美しい景色や美味しい料理、東北地方ならではの刺激的なアクティビティが楽しめる魅力的な観光地です。宮城の自然の美しさや文化の豊かさを体験することができます。' where id = 'MpwXmO-_PDGRvmNh9oY_l';
update content_bodies set title = 'Visit Miyagi, Japan', description = 'Miyagi, Japan, is a captivating destination located about 90 minutes by bullet train from Tokyo. This prefecture offers stunning scenery, delicious local cuisine, and exciting activities unique to the Tohoku region. Visitors can explore the natural beauty and cultural richness that Miyagi has to offer.' where id = 'W2fBsCRoe3ptohHG2MPgn';
update content_bodies set title = '英語による石巻地域の観光案内動画', description = '宮城県東部地方振興事務所は、震災後に防災教育や復興の様子を見学するために被災地を訪れる外国人観光客が増えていることを受けて、英語で石巻地域（石巻市、東松島市、女川町）の魅力や復興の様子を紹介する動画を製作しました。この動画では、ドローンで撮影した迫力ある映像と英語のナレーションを通じて、石巻地域の魅力を発信しています。ぜひご覧ください。' where id = 'HW_8vcfPaQbi5bnSTm-4_';
update content_bodies set title = 'Tourist Guide Video for the Ishinomaki Region in English', description = 'The Miyagi Prefectural Eastern Region Promotion Office has produced a video in English to showcase the attractions of the Ishinomaki area (Ishinomaki City, Higashimatsushima City, Onagawa Town) and the recovery efforts following the Great East Japan Earthquake. This initiative comes in response to the increasing number of foreign tourists visiting the disaster-stricken areas for disaster prevention education and to observe the recovery process. The video features stunning drone footage and English narration, highlighting the charm of the Ishinomaki region. We encourage you to watch it.' where id = 'pgqPY0fCDThanS9tpl0yy';
update content_bodies set title = '日本遺産「葛城修験」PR動画 3分版', description = '和歌山から始まり、大阪、奈良へと続く祈りの道「葛城修験」。この地域は「葛城」と呼ばれ、多くの神々が住む山として古くから崇められてきました。修験道の開祖である役行者が最初に修行の地として選んだのもこの葛城です。現在でも修験者たちはこの地で巡礼の旅を続けています。' where id = 'HxAbCRJV1zPuTFI4_-Q0u';
update content_bodies set title = 'Katsuragi Shugendo PR Video 3-Minute Version', description = 'The Katsuragi Shugendo, which begins in Wakayama and continues through Osaka and Nara, is a sacred pilgrimage route. The area known as ''Katsuragi'' has been revered since ancient times as a mountain inhabited by many deities. En no Gyoja, the founder of Shugendo, chose this place as his first training ground. Even today, practitioners continue their pilgrimage in this region.' where id = 'WFqlm5yoN9tv5XUfPUrIy';
update content_bodies set title = '日本遺産「葛城修験」PR動画 1分版', description = '和歌山から始まり、大阪、奈良へと続く祈りの道「葛城修験」。この地域は「葛城」と呼ばれ、多くの神々が住む山として古くから崇められてきました。修験道の開祖である役行者が最初に修行の地として選んだのもこの葛城です。現在でも修験者たちはこの地で巡礼の旅を続けています。' where id = 'OiiqZWgwoVkJfyGWnwHx4';
update content_bodies set title = 'Katsuragi Shugendo PR Video 1-Minute Version', description = 'Katsuragi Shugendo is a spiritual path that begins in Wakayama and extends through Osaka and Nara. This mountainous region, known as ''Katsuragi,'' has been revered by people since ancient times as a dwelling place for many deities. The founder of Shugendo, En no Gyōja, chose Katsuragi as his initial training ground. Even today, practitioners of Shugendo continue their pilgrimage journeys in this sacred area.' where id = 'Kw6e4XaNOYmRdNpCGDzgL';
update content_bodies set title = '和歌山県日高地方の熊野古道', description = '和歌山県日高地方の熊野古道について、鹿ヶ瀬峠から三鍋王子までのルートを紹介します。黒竹や梅林に囲まれた山道や海岸部を含む風光明媚なコースを楽しむことができます。熊野古道紀伊路の街道マップは、指定されたリンクからご覧いただけます。撮影協力として、熊野古道紀伊路語り部の会とひだか広報家のお仕事に感謝します。日高広域観光振興協議会の公式HPやSNSもぜひご覧ください。' where id = 'M4Zj3uujZOhMZeLUcR47c';
update content_bodies set title = 'Kumano Kodo in the Hidaka Region of Wakayama Prefecture', description = 'This guide introduces the Kumano Kodo from Kakagase Pass to Minabe Oji in the Hidaka region of Wakayama Prefecture. Enjoy a scenic route surrounded by black bamboo and plum groves, including coastal areas. For a map of the Kumano Kodo Kii Route, please visit the provided link. Special thanks to the Kumano Kodo Kii Road Storytellers Association and the Hidaka Public Relations Team for their support. For more information, visit the official website and social media links of the Hidaka Regional Tourism Promotion Council.' where id = 'Z2cgLQ8MPW4xyjOdonTEJ';
update content_bodies set title = '観光PR動画 紀美野町編 - きみの想いと交差する きみのまち', description = 'この動画では、紀美野町の観光スポットが紹介されています。具体的には、きこりのピザ屋SOMAUD、キミノーカ、手漉き和紙工房あせりな、ベーカリーテラスドーシェル、生石高原県立自然公園、紀美野町立みさと天文台などが登場します。海南市・紀美野町の観光情報については、海草振興局のHPや、海南海草地方広域観光協議会の公式インスタグラム、フェイスブックをチェックしてください。' where id = 'FbfSXu_biZfdaMcIHNJqo';
update content_bodies set title = 'Tourism PR Video: Kimino Town Edition - Your Town Where Your Thoughts Intersect', description = 'The video showcases various attractions in Kimino Town, including the SOMAUD pizzeria, Kimino-ka, the handmade washi paper workshop Aserina, the Bakery Terrace Doshel, the Nakaishi Plateau Prefectural Natural Park, and the Misato Observatory. For more information on tourism in Kainan City and Kimino Town, check the following resources: the Kaika Promotion Bureau''s website for local tourism information, the official Instagram account of the Kainan Kaika Regional Tourism Council, and their official Facebook page.' where id = 'hhRKl3mh8W422IJpsrVde';
update content_bodies set title = '観光PR動画 海南市編 出会いも未来もここにある あいのあるまち、K"AI"NAN', description = 'この動画では、海南市の観光スポットが紹介されています。具体的には、JR海南駅、黒沢牧場、紀州漆器伝統産業会館うるわし館、黒江ぬりもの館、黒牛茶屋、中言神社、和歌山県立自然博物館、下津町大崎などが登場します。海南市と紀美野町の観光情報については、海草振興局のHPや、海南海草地方広域観光協議会の公式インスタグラム、フェイスブックをチェックしてください。' where id = 'mGlyDYq2jk5AdT6doMxed';
update content_bodies set title = 'Tourism PR Video: Kainan City - A Town of Love Where Encounters and Futures Await', description = 'The video showcases various attractions in Kainan City, including JR Kainan Station, Kurozawa Farm, the Kishu Lacquerware Traditional Industry Hall, Kuroe Lacquerware Museum, Kuroushi Teahouse, Nakagoto Shrine, Wakayama Prefectural Natural History Museum, and Osaki in Shimizu Town. For more tourism information about Kainan City and Kimino Town, check the following resources: the Kaika Promotion Bureau''s website for local tourism information, the official Instagram account of the Kainan Kaika Regional Tourism Council, and their official Facebook page.' where id = '7ra209ulh9JCmw7bL3eGU';
update content_bodies set title = '和歌山県観光PR動画', description = '和歌山県内の魅力的な観光地や景勝地をドローンで撮影したPR動画です。普段見ることができない上空からの美しい景色を楽しむことができます。撮影地には、白浜町の円月島や三段壁、千畳敷、白良浜、古座川町の一枚岩、串本町の潮岬、串本大橋、海金剛、樫野埼、新宮市の瀞峡などが含まれています。' where id = '0WVYmQXqJYCVU4QY5sW3N';
update content_bodies set title = 'Wakayama Prefecture Tourism PR Video', description = 'This promotional video showcases the attractive tourist spots and scenic locations in Wakayama Prefecture, captured using drone footage. Enjoy breathtaking aerial views that are typically not accessible.' where id = 'IlwUcWSRSNasv0ZIyG1Ss';
update content_bodies set title = '和歌山ワーケーションPR動画　団体編（85秒）', description = 'ワーケーションとは、リモートワークを活用し、リゾート地などの環境の良い場所で、休暇や研修を兼ねて短中期的に滞在し仕事を行う新しい働き方です。首都圏で活躍する企業に和歌山でのワーケーションを体験していただき、交通の利便性が高く、リゾート環境が整う和歌山の魅力の一部を紹介しています。' where id = '1XZJXmhwCixJ9vsgPDh7J';
update content_bodies set title = 'Wakayama Workation PR Video - Group Edition (85 seconds)', description = 'Workation is a new way of working that utilizes remote work, allowing individuals to stay in pleasant environments such as resorts for short to medium-term periods while combining work with vacation or training. Companies active in metropolitan areas experienced ''workation'' in Wakayama. This video introduces some of the attractions of Wakayama, which boasts high transportation convenience and well-established resort environments.' where id = 'dncauu7KKVFTFABdeVj7n';
update content_bodies set title = '和歌山観光プロモーションビデオ（高野編）', description = '和歌山県の観光を促進するためのビデオで、高野地域に焦点を当てています。このビデオは和歌山県インターネット放送局を通じて視聴可能です。' where id = 'tYs5qJsWuhSZu4nK83yCU';
update content_bodies set title = 'Wakayama Tourism Promotion Video (Koya Edition)', description = 'This is a promotional video for tourism in Wakayama Prefecture, focusing on the Koya region. It is available through the Wakayama Prefectural Internet Broadcasting Station.' where id = '7z-6e9T6tSJv-O6eMAKvx';
update content_bodies set title = '和歌山観光プロモーションビデオ（熊野編2）', description = '和歌山県の観光を促進するためのビデオで、特に熊野地域に焦点を当てています。このビデオは和歌山県インターネット放送局を通じて視聴可能です。' where id = 'tZ8n1fDgny8cbPHbqu01J';
update content_bodies set title = 'Wakayama Tourism Promotion Video (Kumano Edition 2)', description = 'This is a promotional video for tourism in Wakayama Prefecture, focusing on the Kumano region. It is available through the Wakayama Prefectural Internet Broadcasting Station.' where id = 'Rb-eW1HLy3cA8lUi7UWMD';
update content_bodies set title = '日本遺産「絶景の宝庫　和歌の浦」', description = '和歌の浦は和歌山県に位置し、日本遺産として認定されています。この地域は、その美しい自然景観と文化的な重要性で知られています。和歌山県インターネット放送局では、和歌の浦の魅力や情報を提供しています。' where id = 'P4ewy1JnRO5h8N_8z0EbR';
update content_bodies set title = 'Japan Heritage: Scenic Treasure of Wakanoura', description = 'Wakanoura, located in Wakayama Prefecture, is recognized as a Japan Heritage site. It is celebrated for its stunning natural beauty and cultural significance. The region is featured on the Wakayama Prefectural Internet Broadcasting Station, which provides insights and information about this picturesque area.' where id = 'oios_7d1yRTmZLq9Q0MoH';
update content_bodies set title = '和歌山観光プロモーションビデオ（和みわかやま香港版）', description = '和歌山県の観光を促進するためのプロモーションビデオで、地域の魅力や文化を紹介しています。このビデオは和歌山県インターネット放送局の一環であり、地元の観光を促進し、特に香港の視聴者との交流を図ることを目的としています。' where id = 'ZKA0p_KtGDFCFSS_-hibm';
update content_bodies set title = 'Wakayama Tourism Promotion Video (Nagomi Wakayama Hong Kong Version)', description = 'This is a promotional video for tourism in Wakayama Prefecture, showcasing the region''s attractions and culture. It is part of the Wakayama Prefectural Internet Broadcasting Station, which aims to promote local tourism and engage with audiences, particularly in Hong Kong.' where id = 'QdcpLAbRVJC3mF5NEs5uC';
update content_bodies set title = '和歌山県民歌', description = '和歌山県民歌は、西川好次郎が作詞し、山田耕筰が作曲した歌で、和歌山の美しさと文化を称賛しています。浜木綿の香りや、陽に映える緑の起伏を描写し、和歌山を常春の国として表現しています。人々の和や文化の豊かさを強調し、地域のさらなる発展を願う内容となっています。ふるさとは常に微笑んでいるというメッセージが込められています。' where id = 'DqdMez0jOiYdgheaI2y4d';
update content_bodies set title = 'Wakayama Prefectural Anthem', description = 'The Wakayama Prefectural Anthem, written by Yoshijiro Nishikawa and composed by Kosaku Yamada, celebrates the beauty and culture of Wakayama. It describes the fragrant coastal flowers and the lush green hills that reflect the warmth of the sun. The anthem emphasizes Wakayama as a land of eternal spring, highlighting the harmony among its people and the richness of its culture. It encourages the region to continue to thrive and prosper, portraying the hometown as a place that always smiles.' where id = '798pMOZtsiN51UBdJvKEZ';
update content_bodies set title = '和歌山観光プロモーションビデオ（和みわかやま台湾版）', description = '和歌山県の観光を促進するためのプロモーションビデオであり、和歌山県インターネット放送局を通じて視聴可能です。' where id = 'g5oHE3Tx76Mztotv0vzxD';
update content_bodies set title = 'Wakayama Tourism Promotion Video (Taiwan Version)', description = 'This is a promotional video for tourism in Wakayama Prefecture, available through the Wakayama Prefectural Internet Broadcasting Station.' where id = 'aG_GDCD4s1csDz7sGiIfE';
update content_bodies set title = '和歌山県の「完全養殖スマ」', description = '和歌山県水産試験場は、平成24年度から幻の高級魚「スマ」の養殖技術の開発に取り組んできました。平成27年度には、東京海洋大学が人工的に育てたスマから採卵を行い、和歌山県水産試験場の技術指導の下、株式会社丸東が完全養殖スマの種苗生産を行いました。現在、株式会社丸東は自社のイケスでスマを養殖しています。本動画では、和歌山県串本町大島のイケスで群泳する完全養殖スマの水中映像が紹介されています。' where id = 'fwy_drEo7_L4admjFtuTZ';
update content_bodies set title = 'Complete Cultivation of Suma in Wakayama Prefecture', description = 'Since the fiscal year 2012, the Wakayama Prefectural Fisheries Experiment Station has been working on developing cultivation techniques for the elusive high-end fish, Suma. In fiscal year 2015, Tokyo University of Marine Science and Technology successfully collected eggs from parent Suma raised artificially, under the technical guidance of the Wakayama Prefectural Fisheries Experiment Station. The cultivation company, Maruto Co., Ltd., then produced seedlings of completely cultivated Suma. Currently, Maruto Co., Ltd. is raising Suma in its own fish pens. This video showcases underwater footage of the completely cultivated Suma swimming in the fish pens located in Oshima, Kushimoto Town, Wakayama Prefecture.' where id = 'mIPw_nr4SReYNkqkR1vkp';
update content_bodies set title = '和歌山観光プロモーションビデオ（和みわかやま韓国版）', description = '和歌山県の観光を促進するためのビデオで、和歌山県インターネット放送局を通じて視聴できます。' where id = '8O4yrd1mIdfGCByYEMlKr';
update content_bodies set title = 'Wakayama Tourism Promotion Video (Korean Version)', description = 'This is a promotional video for tourism in Wakayama Prefecture, available through the Wakayama Prefectural Internet Broadcasting Station.' where id = 'L49E1jNe6HhJnZ76mKQdL';
update content_bodies set title = '和歌山観光プロモーションビデオ（絶景・グルメ編）', description = '和歌山県の絶景やグルメを紹介するプロモーションビデオです。このビデオは、和歌山県の観光を促進するために、和歌山県インターネット放送局が提供しています。美しい風景や地元の美味しい料理を通じて、和歌山の魅力を伝えています。' where id = 'kB3kLDxoZnFSARkH_JVMJ';
update content_bodies set title = 'Wakayama Tourism Promotion Video (Scenic Views and Gourmet)', description = 'This video showcases the beautiful landscapes and delicious cuisine of Wakayama Prefecture. It is part of the online broadcasting service provided by the Wakayama Prefectural Government, aimed at promoting tourism in the region.' where id = 'th-QeNWvMDJ9V2WYvBdQD';
update content_bodies set title = '紀の川よくばりサイクリング', description = 'この動画は紀の川よくばりサイクリングについて紹介しています。紀の川の美しい風景を楽しみながら、サイクリングを通じて地域の魅力を体験できる内容です。' where id = 'caPY7_K_EsT38QHUdlGI0';
update content_bodies set title = 'Kinokawa Yoku-Bari Cycling', description = 'This video introduces the Kinokawa Yoku-Bari Cycling experience.' where id = 'qnrGIs_KFmrj0mTso7OA-';
