update content_bodies set title = '日本トルコ 時を越える絆 ～エルトゥールル号が繋ぐ友好の物語～', description = '和歌山県インターネット放送局が放送するこの番組は、日本とトルコの歴史的および文化的なつながりを探求し、エルトゥールル号の物語に焦点を当てています。両国の間に築かれた友情と絆の歴史を紹介しています。' where id = 'f4_x_IuL7kM5dRpU0TRNa';
update content_bodies set title = 'Japan-Turkey: Bonds Across Time - The Story of Friendship Connected by the Ertugrul Ship', description = 'This program, broadcasted by the Wakayama Prefectural Internet Broadcasting Station, explores the historical and cultural ties between Japan and Turkey, focusing on the story of the Ertugrul ship. It highlights the friendship and connections that have developed over time between the two nations.' where id = 'H4ylmoRx7vwt82n1ydwCH';
update content_bodies set title = '和歌山県北山村の魅力　じゃばらと筏下り', description = '和歌山県のインターネット放送局では、北山村の特産品であるじゃばらや、筏下りの魅力について紹介しています。' where id = 'YWnPdcv56dUD62d_H0EFD';
update content_bodies set title = 'Attractions of Kitayama Village in Wakayama Prefecture: Jabara and River Rafting', description = 'Wakayama Prefecture''s internet broadcasting station provides insights into the unique attractions of Kitayama Village, including the local specialty, jabara, and the exciting experience of river rafting.' where id = '8Trw5bIstcto9T8iDbR_c';
update content_bodies set title = '友ヶ島（西側ルート）：和歌山県', description = '和歌山県のインターネット放送局に関する情報を提供しています。友ヶ島は美しい自然と歴史的な背景を持つ場所であり、訪れる人々に多くの魅力を提供しています。詳細は和歌山県の公式サイトで確認できます。' where id = 'hnedSc-2IjIIVHdHMFUNB';
update content_bodies set title = 'Tomo Island (West Route): Wakayama Prefecture', description = 'Wakayama Prefecture Internet Broadcasting Station' where id = 'Xq7IynQETsDjSvV88lKmw';
update content_bodies set title = 'トゥーンタウンのミッキーの家でミッキーと会おう | 東京ディズニーランド', description = '東京ディズニーランドのトゥーンタウンにあるミッキーの家で、ミッキー・マウスとのミート＆グリートを楽しむことができます。この動画では、2022年7月の訪問時のミッキーの家のフルツアーを紹介しています。入場券は公式ウェブサイトから購入可能で、現在いくつかのチケットタイプが販売中です。この魔法のようなミッキーとの出会いをお見逃しなく！動画には音楽が含まれており、すべてのコンテンツはエンターテインメント目的で使用されており、著作権侵害の意図はありません。' where id = '7_IGhgNWwCDobE9yMJ4y0';
update content_bodies set title = 'Meet and Greet with Mickey in Toontown’s House of Mickey Mouse | Tokyo Disneyland', description = 'Join Mickey Mouse for a meet and greet at his house in Toontown, Tokyo Disneyland. This video showcases a full tour of Mickey''s House from a visit in July 2022. Tickets for admission can be purchased through the official Tokyo Disneyland website, where some ticket types are currently on sale. Don''t miss the chance to experience this magical encounter with Mickey Mouse! The video features music, and all content is used for entertainment purposes only, with no copyright infringement intended.' where id = '18wy37-cnanYV44WR1HNk';
update content_bodies set title = 'ディズニーランド2022 | 東京ディズニーランドに行く際のヒント | 子供たちの夏の楽しみ', description = '2022年の夏、子供たちは冒険を楽しみにしており、東京ディズニーランドやディズニーシーは魔法のような体験を提供します。この動画では、2022年7月2日のディズニーランド訪問のハイライトと、夏の訪問時に役立つヒントを共有しています。視聴者は、公式の東京ディズニーリゾートのウェブサイトを通じて入場券を予約することが奨励されており、現在いくつかのチケットタイプが販売中です。また、動画には音楽が含まれており、著作権に関する免責事項が記載されており、すべてのコンテンツはそれぞれの所有者に帰属し、エンターテインメント目的でのみ使用されることが明記されています。' where id = 'gRxOk0Bc3hI7SBhrRF_R8';
update content_bodies set title = 'Disneyland 2022 | Tips When Going to Tokyo Disneyland | Kids Summer Fun', description = 'In the summer of 2022, families are eager for adventures, and Tokyo Disneyland and Disney Sea offer magical experiences for children. This video shares highlights from a Disneyland visit on July 2, 2022, along with useful tips for summer visits. Viewers are encouraged to book admission tickets through the official Tokyo Disney Resort website, where some ticket types are currently on sale. The video also features music and includes a disclaimer about copyright, stating that all content belongs to its respective owners and is intended for entertainment purposes only.' where id = 'voQr7zzDIsLB10WazqGtb';
update content_bodies set title = '日本の訪れるべき場所 | 湯滝 | 旅行ガイド', description = '湯滝は、栃木県日光市の奥日光エリアに位置する滝で、高さ50メートル、幅25メートルの美しい滝です。湯滝は、華厳滝や竜頭滝と並ぶ奥日光の三大滝の一つです。この滝は、日光白根山のふもとにある湯ノ湖の南岸から流れ落ちています。名前に反して、湯滝の水は冷たく、温泉ではありません。滝の水は湯川となり、標高の高い仙女ヶ原湿原を流れ、竜頭滝を経て中禅寺湖に至ります。湯滝の側には遊歩道が整備されており、滝の口や盆地、側面など、三つのポイントから滝を観賞できます。特に展望デッキからの滝の盆地を間近で見ることは特別な体験です。' where id = '0uTuWJBIWKhmGzHcCyKNM';
update content_bodies set title = 'Places to Visit in Nikko Japan | Yudaki Falls | Travel Guide', description = 'Yudaki Falls, located in the Oku-Nikko area of Nikko City, Tochigi Prefecture, is a stunning waterfall that stands 50 meters high and 25 meters wide. It is one of the three major waterfalls in Oku-Nikko, alongside Kegon Falls and Ryuzu Falls. The waterfall flows from the south shore of Lake Yuno-ko, situated at the base of Mt. Nikko-Shirane, one of Japan''s 100 Major Mountains. Despite its name, Yudaki (meaning ''hot water waterfall''), the water is cold. The waterfall feeds into the River Yukawa, which traverses the high-elevation Senjo-gahara Marshland before reaching Ryuzu Falls and Lake Chuzenji-ko. Visitors can enjoy a promenade along Yudaki Falls, offering views of its mouth, basin, and side, with the observation deck providing a particularly close look at the waterfall basin.' where id = '7PeIZ44ATyrjgWDOblRqg';
update content_bodies set title = '相模湖リゾートのチェアリフトライド | セーラームーンイルミネーション |', description = '相模湖プレジャーフォレストでは、温泉、キャンプ、ドローンなどのさまざまなレジャー活動が楽しめます。冬のイルミネーションイベントは2021年11月13日から2022年4月3日まで、午後4時から午後9時まで開催されます。入場料は大人1,500円、子供1,100円で、リフト乗車料が含まれています。夜間フリーパスは大人2,800円、子供2,200円で販売されています。会場は新宿から車で約50分、または電車で相模湖駅からアクセス可能です。リゾートのウェブサイトでは、さまざまな言語での情報が提供されています。' where id = '7b6c3Jhbac3vSZWDN1act';
update content_bodies set title = 'Chair Lift Ride at Sagamiko Resort | Sailormoon Illumination |', description = 'Sagamiko Pleasure Forest offers a variety of leisure activities, including hot springs, camping, and an amusement park. The winter illuminations event runs from November 13, 2021, to April 3, 2022, from 4 PM to 9 PM. Admission prices are 1,500 yen for adults and 1,100 yen for children, which includes the lift ride. A night free pass is available for 2,800 yen for adults and 2,200 yen for children. The venue is accessible by car from Shinjuku in about 50 minutes or by train via Sagamiko Station. The resort''s website provides additional information in multiple languages.' where id = 'NnpSTjbUHNZAbpGqTPUxE';
update content_bodies set title = '回転寿司レストラン', description = '先週の土曜日、家族はコロナウイルスの影響で外食を控えていたため、久しぶりに東京の回転寿司レストランを訪れました。寿司を食べたいという欲求が高まっていたため、楽しみにしていました。レストランはとても清潔で、閉店間際だったため、他のお客さんはほとんどいませんでした。迅速に注文を済ませたため、食事もあっという間に終わりました。美味しくて満腹になる寿司を楽しみ、素晴らしい体験となりました。' where id = 'y_0x8GllJDlNM55A_K68U';
update content_bodies set title = 'Sushi Conveyor Belt Restaurant', description = 'Last Saturday, the family decided to visit a conveyor belt sushi restaurant in Tokyo after a long time of not dining out due to the COVID-19 pandemic. They had been craving sushi and were excited to finally enjoy it. The restaurant was clean and not crowded, as they were the last customers before closing time. They placed a quick order, leading to a fast dinner experience. The family enjoyed the delicious and filling sushi, making the outing a delightful experience.' where id = 'wUE0XuFeiEhlXcAsyOC8Q';
update content_bodies set title = '清砂橋からの眺め/江東区から江戸川区への散歩・ジョギング', description = 'この動画では、清砂橋を散歩・ジョギングしながら、その周辺の美しい景色を紹介します。清砂橋は、東京の江東区と江戸川区を結ぶ橋で、荒川の上に位置しています。リラックスして、東京の別の一面を楽しんでいただければと思います。動画はスポンサーがなく、音楽やグラフィックの権利はそれぞれの所有者に帰属します。ぜひご覧ください！' where id = 'QVXX0MFn8wtvrPqGfbbSn';
update content_bodies set title = 'View from Kiyosunao Bridge/ Walk/Jog from Koto City to Edogawa City', description = 'In this video, we take you on a jogging and walking tour along the Kiyosunao Bridge, which connects Koto City and Edogawa City over the Arakawa River in Tokyo. We showcase the beautiful views of the surrounding area, inviting viewers to relax and enjoy the scenery. The video is not sponsored, and all rights to the music and graphics belong to their respective owners. Join us for this exploration of another part of Tokyo!' where id = 'Ld308jY1UB5TXZ3nXHgnT';
update content_bodies set title = '栃木県 奥鬼怒温泉郷 4選', description = '奥鬼怒温泉郷は、栃木県に位置する美しい温泉地で、静かな環境と自然の美しさが魅力です。この地域には、独自の体験と治療効果を持つ4つの異なる温泉があります。訪れる人々は、ミネラル豊富な温泉に浸かりながら、穏やかな雰囲気を楽しむことができます。温泉の水は癒しの効果があるとされ、周囲の景色やアウトドア活動の機会も人気です。詳細については、提供されたGoogleマップのリンクを参照してください。' where id = 'WD0YA5iYVt86LqJNLKuwg';
update content_bodies set title = 'The Four Hot Springs of Oku-Kinu Onsen Village, Tochigi', description = 'Oku-Kinu Onsen Village is a picturesque hot spring area located in Tochigi Prefecture, Japan. It is known for its serene environment and beautiful natural surroundings. The village features four distinct hot springs, each offering unique experiences and therapeutic benefits. Visitors can enjoy the tranquil atmosphere while soaking in the mineral-rich waters, which are believed to have healing properties. The area is also popular for its scenic views and opportunities for outdoor activities. For more information, you can explore the provided Google Maps link.' where id = 'KHL_7IRg7Pv1inv0upcYK';
update content_bodies set title = '西湖湖畔キャンプ場 | 富士山近くのキャンプサイト', description = '西湖湖畔キャンプ場は、山梨県富士河口湖町にある富士五湖の一つ、西湖の湖畔に位置しています。このキャンプ場は美しい森林と湖に囲まれた自然豊かな環境を提供しており、標高902メートルに位置しています。草地が広がり、松や広葉樹の森に囲まれています。キャンプ場にはショップやキッチンが完備されており、訪れる人々に便利です。西湖の最大水深は71.1メートルで、富士五湖の中で二番目に深い湖です。予約や問い合わせは、公式ウェブサイトを確認してください。' where id = 'plTD3L4MKweU66FSd7w4c';
update content_bodies set title = 'Saiko Kohan Campground | Campsite near Mt. Fuji', description = 'Saiko Kohan Campground is located on the shores of Saiko, one of the Fuji Five Lakes in Fujikawaguchiko, Yamanashi Prefecture, Japan. This campsite is surrounded by beautiful forests and lakes, providing a rich natural environment. It is situated at an altitude of 902 meters and features grassland along with pine and hardwood forests. The campground is well-equipped with shops and kitchens for visitors. The maximum water depth of Saiko Lake is 71.1 meters, making it the second deepest among the Fuji Five Lakes. For inquiries and reservations, visitors can check their website.' where id = 'q4i49y2VqceYhoxVZlB52';
update content_bodies set title = '渋谷のキットカットショコラトリーで「マイキットカット」を作る方法 | 家族とバレンタインデーを過ごす方法', description = '東京・渋谷の宮下公園にあるキットカットショコラトリーでは、「マイキットカットプログラム」を通じて、自分だけのオリジナルキットカットを作ることができます。このプログラムでは、ビター、ミルク、ルビーのチョコレートから選び、ドライフルーツやナッツ、カラフルなトッピングを使ってカスタマイズできます。ギフトボックスは6種類の日本独自のデザインで提供されています。予約はオンラインまたは店舗で可能で、体験は約1時間かかります。料金は2,160円（約20ドル）で、飲み物が含まれています。営業時間は午前11時から午後9時までです。' where id = 'kN3cvVDvETYlNyI4FWgbB';
update content_bodies set title = 'How to Make “My KitKat” at KitKat Chocolatory Shibuya | How to Spend Valentines Day with Family', description = 'At the Kit Kat Chocolatory in Miyashita Park, Shibuya, Tokyo, you can create your own personalized KitKat through the ''My Kit Kat Program.'' This program allows you to choose from Bitter, Milk, and Ruby chocolate and customize your KitKat with various toppings, including dried fruits, nuts, and colorful decorations. Gift boxes are available in six unique Japanese designs. Reservations can be made online or in-person at the shop, and the experience lasts about an hour, including cooling time. The price is ¥2,160 (approximately $20), which includes a drink. The shop operates from 11 a.m. to 9 p.m. on a daily basis.' where id = 'X8phiyAtpCRr5DGz1ZhrM';
update content_bodies set title = '西丹沢ウェルキャンプへのロードトリップとデイキャンプ（未編集）', description = 'この未編集の動画は、西丹沢ウェルキャンプでのデイキャンプの様子を紹介しています。都市の暑さを逃れ、涼しい流れの水や美しい自然、新鮮な空気を楽しむ素晴らしい一日でした。Punzalan家族やArgamaso家族と共に過ごし、楽しい思い出を作りました。この動画はその日の楽しさを捉えており、Punzalan家族への感謝の気持ちが表れています。視聴者が楽しんでくれることを願い、次の冒険を楽しみにしています。' where id = 'cMOxyHrLr_9qqAAiPRVDv';
update content_bodies set title = 'Road Trip and Daycamping to Well Camp Nishi Tanzawa (uncut)', description = 'This uncut video showcases a day of camping at Well Camp Nishi Tanzawa. The experience was delightful, as the group escaped the city''s heat to enjoy a refreshing environment filled with cool stream water, beautiful nature, and fresh air. The day was spent with the Punzalan family and cousins from the Argamaso family, creating wonderful memories together. The video captures the joy of the day, and the creators express gratitude to the Punzalan family for the experience. They hope viewers enjoy the video and look forward to their next adventure.' where id = 'J1p4TXdq1aIW5SrOHBtid';
update content_bodies set title = 'シャチのショー', description = '鴨川シーワールドでのシャチのショーは、訪れる人々にとって刺激的な体験です。この動画では、ショーのスリリングな瞬間が捉えられており、これらの素晴らしい生き物の知性と優雅さが紹介されています。制作者は、視聴者が動画を楽しんでくれたことを願っています。さらにコンテンツを楽しむために、Instagram、Facebook、YouTubeのソーシャルメディアアカウントをフォローするように促しています。' where id = 'JSdQMryznS7WPjeSfSjOX';
update content_bodies set title = 'Orca the Killer Whale', description = 'The Orca show at Kamogawa Seaworld is an exciting experience for visitors. The video captures the thrilling moments of the show, showcasing the intelligence and grace of these magnificent creatures. The creators express their hope that viewers enjoyed the video as much as they did. For more content, they encourage following their social media accounts on Instagram, Facebook, and YouTube.' where id = 'vVVrKILn4P-yMZDsvA9eo';
update content_bodies set title = '小石川後楽園の秋の紅葉', description = 'この動画では、東京の名園、小石川後楽園を紹介します。小石川後楽園は、1629年に水戸徳川家の初代当主・頼房によって設立され、2代目の光圀の時代に完成しました。中央に池と丘があり、散策に最適です。光圀は、明代の儒学者・朱舜水の思想を取り入れ、清湖の再現や「満月橋」などの中国文化に由来する要素を組み込みました。「後楽園」という名前は、光圀が感銘を受けた中国の文献に由来し、権力を維持した後に楽しむべきという意味があります。小石川後楽園は重要文化財に指定されており、面積は70,847.17平方メートル、4,030本の高木と17,700本の低木があります。開園時間は9:00から17:00までで、入園料は300円です。' where id = 'G8xaPPCexSX7qRjTbOlP6';
update content_bodies set title = 'Koishikawa Korakuen Gardens Autumn Foliage', description = 'In this video, we explore the Koishikawa Korakuen Gardens, one of Tokyo''s finest Japanese gardens. Established in 1629 by Yorifusa, the founder of the Mito Tokugawa family, the garden was completed under the second clan ruler, Mitsukuni. It features a central pond and hills, ideal for leisurely walks. Mitsukuni incorporated elements from Chinese culture, including a replica of Seiko Lake and a ''Full Moon Bridge.'' The name ''Korakuen'' reflects a Chinese text emphasizing the importance of enjoying power after securing it. Recognized as an important historical asset, the garden spans over 70,000 square meters and is home to thousands of trees. It is open daily from 9:00 AM to 5:00 PM, with an entrance fee of ¥300.' where id = 'M0qK0Ur_i7D7Q1cBwAkzx';
update content_bodies set title = '明治神宮外苑 銀杏並木 東京 | 秋の紅葉 | 青山外苑', description = '東京の青山通りに沿って広がる美しい黄色の銀杏の木々を楽しむことができます。この場所は、秋の季節に訪れる人々に人気があり、自然の鮮やかな色合いを楽しむことができます。動画には、風景を引き立てる音楽や映像が含まれています。コラボレーションや製品レビューについては、メールでの連絡が可能です。このコンテンツは娯楽目的で作成されており、使用されているすべてのメディアはそれぞれの所有者に帰属します。' where id = 'BjXqEPLxdoVbdI2HqLLgU';
update content_bodies set title = 'Meiji Jingu Gaien Ginkgo Avenue Tokyo | Fall Foliage | Aoyama Gaien', description = 'Experience the stunning yellow ginkgo trees lining Aoyama Avenue in Tokyo during the autumn season. This location is renowned for its beautiful fall foliage, attracting visitors who appreciate the vibrant colors of nature. The video features music and visuals that enhance the experience of this picturesque setting. For collaborations or product reviews, viewers can reach out via email. The content is intended for entertainment purposes, and all media used belongs to their respective owners.' where id = 'th1MmzP4Clo90lLXbZuCd';
update content_bodies set title = '西湖癒しの里根場（伝統的な日本の村）ウォークツアー', description = '西湖癒しの里根場は、富士山の近くに位置する伝統的な日本の村です。このウォークツアーでは、訪問者が地域の美しい風景と文化遺産を探索する機会を提供します。村は絵のように美しい風景と伝統的な建築で知られており、本物の日本文化を体験したい旅行者にとって理想的な旅行先です。ツアーでは、村の魅力や周辺の西湖、富士山の素晴らしい景色を強調しています。このユニークな場所の静けさと美しさに浸る絶好の機会です。' where id = 'aGHeBV3PULV5QVl02HiQW';
update content_bodies set title = 'Saiko Iyashi-no-Sato Nenba (Traditional Japanese Village) Walk Tour', description = 'The Saiko Iyashi-no-Sato Nenba is a traditional Japanese village located near Mount Fuji. This walking tour offers visitors a chance to explore the scenic beauty and cultural heritage of the area. The village is known for its picturesque landscapes and traditional architecture, making it a perfect travel destination for those interested in experiencing authentic Japanese culture. The tour highlights the charm of the village and its surroundings, including Lake Saiko and the stunning views of Mount Fuji. It is an ideal opportunity for travelers to immerse themselves in the tranquility and beauty of this unique location.' where id = 'lDHcn5NV_AH-99x6o6bbd';
update content_bodies set title = '忠霊塔への散策 | 富士山ツアー', description = '忠霊塔までの散策に参加し、富士山と富士吉田市の美しい景色を楽しみましょう。このツアーは、日本の象徴的な山とその文化的名所を体験したい方に最適です。' where id = 'DA6ep6YwLdqVEDmZuwZKs';
update content_bodies set title = 'A Walk to Chureito Pagoda | Mt Fuji Tour', description = 'Join us for a scenic walk to Chureito Pagoda, which offers stunning views of Mt Fuji and the surrounding Fujishiyoda City. This tour is perfect for those looking to experience the beauty of Japan''s iconic mountain and its cultural landmarks.' where id = 'zC9-Trqi9HTsMhwZY76B3';
update content_bodies set title = '【360VR】ＶＲ青森ねぶた祭【青森市】', description = '目の前に迫りくる“ねぶた”を体験できる360度のヴァーチャル映像で、2022年夏に3年ぶりに開催された青森ねぶた祭の迫力を感じることができます。' where id = 'ke3DmEOjmVelbk9pvyq30';
update content_bodies set title = 'VR Aomori Nebuta Festival', description = 'Experience the Aomori Nebuta Festival in a virtual setting with stunning visuals. The festival, which had not been held for three years, took place in the summer of 2022, bringing the vibrant and dynamic atmosphere of the event right to your screen.' where id = 'PutbkAEFA9v9CYHJn17Fc';
update content_bodies set title = '【360VR】ＶＲ小牧野遺跡・三内丸山遺跡【青森市】', description = '世界文化遺産に登録された小牧野遺跡と三内丸山遺跡を、360度のヴァーチャル体験で楽しむことができます。鳥のように上空からの美しい景色を堪能し、展示施設を巡る体験をお楽しみください。' where id = '4UT3mvtArw2aDqhe-f46X';
update content_bodies set title = '360VR: Komakino and Sannai-Maruyama Sites in Aomori City', description = 'Experience the virtual tour of the world heritage sites, Komakino and Sannai-Maruyama. Enjoy breathtaking aerial views as if you were a bird, along with a virtual exploration of the exhibition facilities.' where id = 'Uti_rA8Ut25XoX0HY6131';
update content_bodies set title = '青森市冬季観光PR動画（90秒編）', description = '青森市の冬は11月から3月までの5か月間続きます。この期間、青森市では雪と共に生活し、雪を楽しむための観光資源が豊富に揃っています。青森の冬の魅力をぜひ動画でご覧ください。' where id = 'cafWG3wVmYmDVi8E6D9Rs';
update content_bodies set title = 'Aomori City Winter Tourism PR Video (90 seconds)', description = 'Aomori City experiences winter from November to March, living with snow for five months of the year. The city offers abundant winter tourism resources that allow visitors to enjoy and engage with the snow. Discover the charm of Aomori''s winter through this video.' where id = '-nYa3mnUX549NZdWee18q';
update content_bodies set title = '青森市通年観光PR動画（90秒編）', description = '青森市は、八甲田連峰や陸奥湾などの美しい自然に恵まれ、その豊かな自然の中で育まれた多彩な食文化があります。また、世界に誇る青森ねぶた祭や三内丸山遺跡、温泉など、多様な観光資源が揃っています。四季を通じて楽しめる青森の魅力を、ぜひ動画でご覧ください。' where id = 'z6P_G0AXdN6GXv5vepOba';
update content_bodies set title = 'Aomori City Year-Round Tourism PR Video (90 Seconds)', description = 'Aomori City boasts beautiful natural landscapes such as the Hakkoda Mountains and Mutsu Bay, along with a rich and diverse culinary scene nurtured by its abundant nature. The city is also home to the world-renowned Aomori Nebuta Festival, the Sannai-Maruyama archaeological site, and various hot springs, showcasing a wide range of attractive tourist resources. Experience the charm of Aomori throughout the four seasons by watching the video.' where id = '9lunMofrIc9jzeHAy_mbn';
