update content_bodies set title = '八甲田', description = '英語の字幕付きで提供される「八甲田」は、視聴者に作品の内容を理解しやすくするための工夫がされています。映画や映像作品において、英語の字幕は特に外国語の作品を楽しむ際に重要な役割を果たします。この作品もその一環として、視聴者がストーリーやキャラクターの感情をより深く理解できるように配慮されています。' where id = '-62UkdCJMiTazyGFqqdNf';
update content_bodies set title = 'Hakkoda', description = 'Hakkoda with English subtitles.' where id = 'ztRkkOmLBNXFOv1eMEXK6';
update content_bodies set title = '八甲田の樹氷編', description = 'この動画は八甲田の樹氷について紹介しています。八甲田山の美しい樹氷は、冬の厳しい気候条件によって形成され、訪れる人々に幻想的な景観を提供します。樹氷は、雪と風の影響を受けて独特の形状を持ち、自然の芸術作品とも言える存在です。八甲田の樹氷は、観光名所としても知られ、多くの人々がその美しさを求めて訪れます。' where id = 'BKUtptk1t9G7wNxBQGM2K';
