update content_bodies set title = '旅行 東広島～歴史と自然の色彩～', description = 'この観光PR動画は、東広島市の魅力を紹介しています。観光、食、歴史、文化、自然など、多様な魅力が詰まった東広島市で素晴らしい休日を過ごしてみませんか？ぜひお越しください。' where id = 'VaKYmclkLCQLczqvG0yjc';
update content_bodies set title = 'Travel Higashihiroshima～Colors of History and Nature～', description = 'This tourism public relations video showcases the attractions of Higashihiroshima City, highlighting its tourism, food, history, culture, and natural beauty. It invites viewers to experience a wonderful holiday in Higashihiroshima City and encourages them to visit.' where id = 'GENbOWXoQC1lVFiBnnktg';
update content_bodies set title = '旅行 東広島 ～歴史と自然の色彩～', description = 'これは東広島市の観光PR動画です。この動画では、観光、食、歴史、文化、自然など、東広島市の魅力を紹介しています。素晴らしい休日を東広島市で過ごしてみませんか？ぜひお越しください。3分の動画には日本語と英語の字幕が用意されています。' where id = '7Teu00i5oj3HGychE0dM1';
update content_bodies set title = 'Travel Higashihiroshima – Colors of History and Nature', description = 'This is a promotional tourism video for Higashihiroshima City, showcasing its attractions such as tourism, food, history, culture, and nature. The video invites viewers to experience a wonderful holiday in Higashihiroshima City. For more information, viewers can access a 3-minute video with Japanese and English subtitles available through the provided links.' where id = 'EYpB-QLb1zCgWfmUE9OLG';
update content_bodies set title = '東広島市の酒蔵', description = '灘・伏見と並ぶ酒都・西条には、西条酒蔵通りがあり、酒蔵が集まっています。さらに「ひろしま杜氏のふるさと」として知られる安芸津や、田園風景が広がる黒瀬なども市内にあり、合計で10の酒蔵が存在します。' where id = 'd8Cl43398klMQbb3YZtNX';
update content_bodies set title = 'Sake Breweries in Higashihiroshima City', description = 'Saijo, known as a sake town alongside Nada and Fushimi, features the Saijo Sake Brewery Street. In addition to Saijo, the city is home to Akitsu, known as the ''Hometown of Hiroshima Sake Brewers,'' and Kurose, which boasts picturesque rural landscapes. Overall, there are ten sake breweries within the city.' where id = '2qxAsLAuwpeuzn4IT17rQ';
update content_bodies set title = '東広島市観光PR動画（日本酒のまち東広島6秒×5本編）', description = 'この動画は、東広島市の観光をPRするもので、日本酒のまちとしての特徴を強調しています。6秒の短いセグメントが5本あり、各セグメントで市の独自性や日本酒文化の魅力を紹介しています。' where id = '02EWLBMnBN6KJS7NluWUb';
update content_bodies set title = 'Higashihiroshima City Tourism PR Video (Sake Town Higashihiroshima 6 Seconds x 5 Episodes)', description = 'This is a promotional video for Higashihiroshima City, highlighting its identity as a sake town. The video consists of five short segments, each lasting six seconds, showcasing the unique aspects of the city and its sake culture.' where id = '9onL3CcBsQg5BWyVMgl2L';
update content_bodies set title = '東広島の自然', description = '東広島では、季節ごとに風情ある風景を楽しむことができます。市の南部は瀬戸内海に面しており、高台からは美しい島々の景色が広がります。一方、北部は山々に囲まれており、田園風景や山頂からの眺めが心を癒してくれます。' where id = 'JGf0QsYfniq726VzCxsR2';
update content_bodies set title = 'Nature of Higashi-Hiroshima', description = 'Higashi-Hiroshima offers picturesque landscapes that change with the seasons. The southern part of the city faces the Seto Inland Sea, providing breathtaking views of the islands from elevated areas. In contrast, the northern part is surrounded by mountains, where the serene rural scenery and panoramic views from mountain tops can be enjoyed.' where id = 'xZW1ZQAe2VVbP5r4GkIZW';
update content_bodies set title = '必見！エイサー踊りパレード（ミチジュネー）｜沖縄県の祭り', description = 'エイサーは沖縄の伝統的な踊りで、大きなバレルドラムやタボールを打ちながら、歌や三線と共に生演奏されます。一般的に、エイサーグループは音楽家、大きなドラム、タボール、ダンサー、そしてサナジャで構成されています。エイサーは現在多くのイベントで披露されていますが、元々は盆祭りの三日目に祖先の霊を見送るための踊りとして行われていました。沖縄県で最大のエイサーイベントである沖縄全島エイサーまつりは、エイサーの街、沖縄市で開催されます。' where id = 'AFBoiGi1pEM-58YZW2Cwd';
update content_bodies set title = 'Must see！Eisa dance parade (Michijunee)  ｜Festivals in Okinawa Prefecture', description = 'Eisa is a traditional dance from Okinawa, characterized by live performances featuring songs, sanshins, and the rhythmic beating of large barrel drums and tabors. Eisa groups typically include musicians, dancers, and performers known as sanajya. While Eisa is now showcased at various events, its origins lie in a farewell dance for ancestral spirits returning to the world during the bon festival''s third night. The Okinawa Zento Eisa Matsuri, the largest Eisa festival in Okinawa Prefecture, takes place in Okinawa City, known as the city of Eisa.' where id = '16gfzF_ZyoOzDh2bKSJU4';
update content_bodies set title = '東広島市観光PR動画（日本酒のまち東広島6秒×5本編（英語字幕））', description = 'この動画は、東広島市の観光PR動画であり、日本酒の生産で知られる町としての魅力を紹介しています。動画は6秒の短いセグメントが5本あり、各セグメントで市の様々な側面や日本酒文化を紹介しており、英語字幕が付いているため、国際的な視聴者にも楽しめる内容となっています。' where id = 'uLZawd0EBhZ0hF16fEWBP';
update content_bodies set title = 'Higashihiroshima City Tourism PR Video (Sake Town Higashihiroshima 6 seconds x 5 episodes with English subtitles)', description = 'This is a promotional video for Higashihiroshima City, highlighting its identity as a town known for sake production. The video consists of five short segments, each lasting six seconds, showcasing various aspects of the city and its sake culture, with English subtitles provided for international viewers.' where id = 'yLqF2gLCgekL6NOs-RAxC';
update content_bodies set title = '東広島の自然～豊栄・福富・河内～', description = '広島県の中央に位置する豊栄・福富・河内では、それぞれの町独特の自然風景を楽しむことができます。特に、5月中旬から6月上旬にかけてはクロボヤ峡のホンシャクナゲが見頃を迎え、10月下旬から11月下旬には深山峡の紅葉が美しい景観を提供します。' where id = '-0OfllNxx0igc6h4vIeHa';
update content_bodies set title = 'Nature of Higashihiroshima - Toyosaka, Fukutomi, Kawachi', description = 'Located in the central part of Hiroshima Prefecture, Toyosaka, Fukutomi, and Kawachi offer unique natural landscapes. From mid-May to early June, the Honshakunage in Kuroboya Gorge is in full bloom, while the autumn foliage in Miyama Gorge is at its peak from late October to late November.' where id = 'nQAeLcS1jIRpsJLJgTNLG';
update content_bodies set title = '沖縄市の探訪', description = 'このDVDは沖縄市の観光を促進するためのもので、沖縄市のさまざまな観光名所や文化体験、アクティビティを紹介しています。訪問者に沖縄市の魅力を探求し、楽しんでもらうことを目的としています。' where id = 'S-R-2HX0h634MPnHcqoJP';
update content_bodies set title = 'Exploring Okinawa City', description = 'This is a promotional DVD focused on tourism in Okinawa City. It showcases various attractions, cultural experiences, and activities available in the city, aiming to encourage visitors to explore and enjoy what Okinawa City has to offer.' where id = 'FmzmkVHb-GhdXx06lF5-3';
update content_bodies set title = 'おいしさ日本一宮崎牛', description = '宮崎牛の甘く芳醇な香りと肉汁が口の中いっぱいに広がり、とろける霜降りの旨みを堪能できるASMR動画です。ぜひその美味しさを体験してください。' where id = 'h68GvoK6PDG_iyt1Rsczd';
update content_bodies set title = 'Delicious Miyazaki Beef ASMR Video', description = 'Experience the sweet and rich aroma of Miyazaki beef as its juices fill your mouth, melting with the exquisite marbling. This ASMR video invites you to savor the unique flavors of this premium beef.' where id = 'BUXTKY1sQRK1tw9Ss8PvD';
update content_bodies set title = 'サイクリングパラダイス MIYAZAKI（ロングver.）', description = '宮崎は温暖な気候に恵まれ、年間を通じてサイクリングが楽しめる地域です。今回は、宮崎の中でも特に美しいサイクリングルートである青島から日南海岸、そして都井岬までの風景とサイクリング環境を紹介します。「サイクリングパラダイス＝みやざき」として、日本のひなたを走る体験をお楽しみください。' where id = 'H59gD5qoV45pFBZC0iIQh';
update content_bodies set title = 'Cycling paradise MIYAZAKI (Long version)', description = 'Miyazaki, with its warm climate, offers year-round cycling opportunities. This article highlights one of the best cycling routes in Miyazaki, showcasing the beautiful scenery from Aoshima to the Nichinan Coast and Cape Toi. Experience the cycling paradise that is Miyazaki and ride through Japan''s sunny side!' where id = '_5M5gmHXW2z399RFhteAZ';
update content_bodies set title = '鹿児島県 湧水町 日帰り温泉 7選', description = '鹿児島県の湧水町は、美しい温泉で知られています。この記事では、日帰りで利用できるおすすめの温泉を7つ紹介しており、リラックスしたい方に最適なスポットです。訪れる人々は、自然の美しさと温泉の癒しの効果を楽しむことができます。また、温泉体験に関連するSNSや商品へのリンクも掲載されています。' where id = 'zCw1wm9Ebp2ZUfjdtkFCz';
update content_bodies set title = 'Top 7 Day Onsen in Yusui, Kagoshima', description = 'Yusui Town in Kagoshima Prefecture is known for its beautiful hot springs. This article highlights seven recommended day-use onsens in the area, perfect for a relaxing getaway. Visitors can enjoy the natural beauty and therapeutic benefits of these hot springs. The article also includes links to social media and merchandise related to the Japanese hot spring experience.' where id = 'mx2m5cFckUP0beOcPVMP1';
update content_bodies set title = '和歌山県 川湯温泉 共同浴場', description = '川湯温泉には、訪れる人々に伝統的な日本の温泉体験を提供する3つの公衆浴場があります。場所はGoogleマップで確認でき、旅行者にとって便利です。また、インスタグラムアカウント「hitou_wo_semeru」では、この地域の美しさや魅力が紹介されています。さらに、「日本秘湯を攻める会」のオリジナルオレンジタオルが、さまざまなセットで購入可能なリンクも提供されており、訪問者にとって素晴らしいお土産となります。' where id = '9280X6wD_a2eznWA5Ou3t';
update content_bodies set title = 'Public Baths in Kawayu Onsen, Wakayama Prefecture', description = 'Kawayu Onsen features three public baths, offering visitors a unique experience in a traditional Japanese hot spring setting. The location is highlighted on Google Maps, making it easy for travelers to find. Additionally, the Instagram account ''hitou_wo_semeru'' showcases the beauty and charm of the area. For those interested in souvenirs, original orange towels from the ''Nihon Hito o Semeru Kai'' are available for purchase in various sets through provided links. These towels serve as a perfect memento for visitors to take home.' where id = 'VGXdx5Yc7Nnc806xNwqf7';
update content_bodies set title = '熊本県 人吉温泉 日帰り温泉 ８選', description = '人吉市は熊本県に位置し、温泉で知られています。この記事では、地域の中で特におすすめの日帰り温泉8選を紹介しており、訪れる人々が自然の温泉の癒し効果を楽しむ機会を提供しています。また、Googleマップのリンクが掲載されており、簡単にアクセスできるようになっています。さらに、地元の温泉文化に関連するSNSや商品販売のリンクも含まれています。' where id = 'BmZHjRVFUKFNk1BCtimu-';
update content_bodies set title = 'Top 8 Day Onsen in Hitoyoshi, Kumamoto', description = 'Hitoyoshi is a city in Kumamoto known for its hot springs. This article highlights the top eight day-use onsens in the area, providing visitors with a chance to relax and enjoy the therapeutic benefits of the natural hot springs. The article also includes links to a Google Maps location for easy navigation, as well as social media and merchandise links related to the local hot spring culture.' where id = 'mqJJ0rm80VA_4kKXu8bUb';
update content_bodies set title = '共同湯 公衆浴場', description = 'この動画には他の入浴者が映っている場面がありますが、撮影の許可を得ています。様々な意見を持つ方もいらっしゃるかと思いますが、何卒ご理解とご了承をお願い申し上げます。霧島市の旧牧園町にある全13湯の共同浴場を紹介しています。' where id = '_Kt5lZvH7z06G2lPge6Tu';
update content_bodies set title = 'All 13 Public Bathhouses in Kirishima City, Kagoshima Prefecture', description = 'The video features scenes with other bathers, and permission for filming has been obtained. While there may be differing opinions on this matter, we kindly ask for your understanding and acceptance.' where id = 'qADuR-B1kqg7v4dOCI58m';
update content_bodies set title = '長野県 上山田温泉 共同湯 全7湯', description = '上山田温泉は長野県に位置する有名な温泉地で、全7つの公衆浴場があります。各浴場は独自の体験を提供し、ミネラル豊富な温泉の効能を楽しむことができます。この地域は美しい景観と伝統的な日本の雰囲気で知られ、地元の人々や観光客に人気のある目的地です。また、日本秘湯を攻める会のオリジナルオレンジタオルなど、購入可能な商品もいくつかあり、リンクからアクセスできます。' where id = 'adDfbYqWm5ba9CGrsd5cH';
update content_bodies set title = 'All 7 Public Hot Springs in Togura Kamiyamada Onsen, Nagano Prefecture', description = 'Togura Kamiyamada Onsen is a renowned hot spring area in Nagano Prefecture, featuring a total of seven public hot springs. Each of these baths offers a unique experience, allowing visitors to enjoy the therapeutic benefits of the mineral-rich waters. The area is known for its beautiful scenery and traditional Japanese atmosphere, making it a popular destination for both locals and tourists. Additionally, there are various products available for purchase, including original orange towels from the Nihon Hito Onsen Association, which can be found through provided links.' where id = 'uONfIiZwqlyBKuiZxCEF3';
update content_bodies set title = 'びわ湖の素米原　Camp＆E-BIKES', description = '令和3年10月に滋賀県米原市で開催されたサイクリングツアーの様子を紹介します。このツアーでは、Eバイクを利用して日本遺産である「琵琶湖とその水辺景観」を巡るサイクリングルートを体験しました。参加者は美しい湖の景観を楽しみながら、自然と文化を感じることができる貴重な機会となりました。' where id = 'Syg8iRwutjQUpR0YF1l4M';
update content_bodies set title = 'Biwako''s Sumaihara Camp & E-BIKES', description = 'This is an overview of a cycling tour held in October 2021 in Maibara City, Shiga Prefecture. Participants explore the cycling route of the Japanese heritage site ''Lake Biwa and its waterfront landscape'' using E-bikes.' where id = '9UNwlU-MCGsjwVlLclQp5';
update content_bodies set title = '福島県 金山町 共同湯 全8湯', description = '福島県金山町には、全8つの公衆浴場（共同湯）があり、訪れる人々に日本の伝統的な温泉文化を体験する機会を提供しています。美しい自然に囲まれたこの町は、リラクゼーションと探検の両方を楽しむのに最適な場所です。また、地元の特産品やお土産も豊富に揃っています。金山町は、SNSを通じて温泉の魅力を発信し、オリジナルのオレンジタオルなどのグッズもオンラインで販売しています。自然の美しさと文化的な遺産が融合した金山町は、日本の入浴文化に興味がある人々にとって注目すべきスポットです。' where id = '_mT_X_lM9CyDIRHo4LJtF';
update content_bodies set title = 'Kanayama Town, Fukushima Prefecture: All 7 Hot Springs', description = 'Kanayama Town in Fukushima Prefecture is home to a total of seven public hot springs, known as ''kyoudou-yu''. These communal baths offer a unique experience for visitors looking to enjoy traditional Japanese onsen culture. The town is located in a picturesque area, making it an attractive destination for both relaxation and exploration. In addition to the hot springs, visitors can find various local products and souvenirs. The town also promotes its hot springs through social media and offers original merchandise, such as orange towels, for sale online. This combination of natural beauty and cultural heritage makes Kanayama Town a noteworthy spot for those interested in Japan''s bathing traditions.' where id = 'skwvuMf7_jBK13H6zbENd';
update content_bodies set title = '【温泉ひとり旅】長野県 湯めぐり 信州攻め③', description = 'このエントリーは、2025年7月に長野県の温泉を訪れたことを記録しています。著者は体験を共有するためにインスタグラムアカウントを始めました。また、「日本秘湯を攻める会」のオリジナルオレンジタオルを販売しており、いくつかのリンクが提供されています。タオルは2本セット、3本セット、5本セットで購入可能で、それぞれの購入リンクが用意されています。' where id = 'NFrY1wiA9Mm5OofLfhUEf';
update content_bodies set title = 'Solo Onsen Trip: Nagano Prefecture, Yume-guri, Shinshu Attack③', description = 'This entry marks the visit to a hot spring in Nagano Prefecture, dated July 2025. The author has started an Instagram account to share their experiences. Additionally, they are selling original orange towels from the ''Japan Hidden Hot Springs Attack Club'' through various links provided. The towels are available in different sets: a two-piece set, a three-piece set, and a five-piece set, each with its own purchase link.' where id = 'V89pWuwudoH81XaVC8bnp';
update content_bodies set title = '【温泉ひとり旅】長野県 湯めぐり 信州攻め②', description = 'このエントリーは、2025年7月に長野県の温泉を訪れたことを記録しています。著者は体験を共有するためにインスタグラムアカウントを始めました。また、「日本秘湯を攻める会」のオリジナルオレンジタオルを販売しており、各リンクから購入可能です。タオルは2本、3本、5本セットで販売されており、それぞれのリンクが該当する商品ページに誘導しています。' where id = '-I0rf0_LJ954Qzs0kKYx8';
update content_bodies set title = 'Solo Onsen Trip: Nagano Prefecture, Exploring Shinshu②', description = 'This entry marks the visit to hot springs in Nagano Prefecture, specifically in July 2025. The author has started an Instagram account to share their experiences. Additionally, they are selling original orange towels from the ''Japan Hidden Hot Springs Exploration Club'' through various links provided. The towels are available in sets of two, three, and five, with each link directing to the respective product page.' where id = '0S1MCQ7l7zbdFGlPS1lU9';
update content_bodies set title = 'ダイジェスト青島', description = 'この動画はダイジェスト青島を紹介しています。' where id = 'nPH0iM7pIG8YIEJmvsOF-';
update content_bodies set title = 'digest AOSHIMA', description = 'This video provides an introduction to digest AOSHIMA.' where id = 'JMaYrfD12D8OPZbDwQVJn';
