update content_bodies set title = '宮崎食堂女子旅short+', description = 'この動画は宮崎食堂女子旅short+について紹介しています。宮崎食堂を中心にした女子旅の体験や魅力を伝え、参加者同士の楽しさや絆を強調しています。' where id = 'cM8VhmINK26lT6iCLXCmN';
update content_bodies set title = 'Miyazaki Shokudo Girls'' Trip Short+', description = 'This video introduces Miyazaki Shokudo Girls'' Trip Short+. It showcases the experiences and highlights of a girls'' trip centered around the Miyazaki Shokudo, emphasizing the fun and camaraderie among the participants.' where id = 'aOVFPe1I9GcxwDfeqVTK2';
update content_bodies set title = '元気になりに、いらっしゃい。【宮崎市】宮崎食堂ムービー｜女子旅編', description = '宮崎市の魅力を発信する「宮崎食堂」プロジェクトのムービーが公開されました。このムービーでは、青い空の下で海や山の自然に触れ、地元の食や人との交流を通じて元気になれる宮崎市の魅力が描かれています。女子旅編では、都会に住む友達が宮崎食堂ののれんに出会い、宮崎出身の友人に導かれて様々な体験をします。青島神社やマンゴーパフェ、野菜のランチ、シーカヤック、トレッキング、日向灘でのヨガなど、心と体が元気になるアクティビティが満載です。また、地元のバンドSAKANAMONが書き下ろした楽曲「つつうららか」がムービーを彩り、宮崎の魅力を伝えています。「宮崎食堂」プロジェクトは、食や自然、人の温かさを通じて宮崎市の魅力を発信し、訪れる人々を歓迎しています。' where id = 'RmhzlOI46aa6Yfk-AwIjN';
update content_bodies set title = 'Come to Get Energized: Miyazaki Dining Movie - Girls'' Trip Edition', description = 'A new movie has been created to promote the charm of Miyazaki City through the ''Miyazaki Dining'' project. It showcases how visitors can rejuvenate themselves by experiencing the rich nature of the sea and mountains under the blue sky, enjoying local cuisine, and interacting with the friendly locals. In the ''Girls'' Trip Edition,'' a group of friends from the city unexpectedly encounters the ''Miyazaki Dining'' sign. Led by a friend from Miyazaki, they explore various attractions, including the Aoshima Shrine, mango parfaits, vegetable lunches, sea kayaking, trekking, and yoga at sunrise over Hyuga-nada. The movie features an original song ''Tsutsu Uraraka'' by the local rock band SAKANAMON, capturing the essence of local pop and the vibrant scenes of Miyazaki. The ''Miyazaki Dining'' project aims to highlight the city''s warmth, food, and nature, inviting everyone to come and enjoy the local delights.' where id = '9-aZOhtPuiYsQ_3j3ppyN';
update content_bodies set title = '東京の紹介', description = 'Lonely Planetのビデオガイドを使って東京を探検しましょう。このガイドでは、東京の移動方法、訪れるのに最適な時期、そして現地で楽しむべき主なアトラクションについての情報が提供されています。さらに旅行のヒントについては、https://www.lonelyplanet.com/japan/tokyo をご覧ください。' where id = 'EVUndg9W-QCb3bieiGRyW';
update content_bodies set title = 'Introducing Tokyo', description = 'Explore Tokyo with Lonely Planet’s video guide, which provides insights on how to navigate the city, the best times to visit, and the top attractions to experience. For additional travel tips, visit https://www.lonelyplanet.com/japan/tokyo.' where id = 'gtzHCNwMGVLryik2DRaOe';
update content_bodies set title = '京都の紹介', description = 'Lonely Planetのビデオガイドを使って、京都の探索を始めましょう。移動方法、訪れるべき時期、そして現地でのおすすめアクティビティについての情報が得られます。さらに旅行のヒントが必要な方は、Lonely Planetのウェブサイトをご覧ください。' where id = '6_WIQ3LydTeyYCMFdzDAE';
update content_bodies set title = 'Introducing Kyoto', description = 'Discover Kyoto with Lonely Planet''s video guide, which provides insights on how to navigate the city, the best times to visit, and must-see attractions. For additional travel tips, visit the Lonely Planet website.' where id = 'mf4j6l0nVvAwOM3rJ-gOm';
update content_bodies set title = '日本：古き良きものと新しいもの - ロンリープラネット旅行動画', description = '日本は2016年のロンリープラネットの「ベスト・イン・トラベル」で2位にランクインしていますが、異世界的な体験を求める旅行者にとっては常に1位の目的地です。この動画では、ロンリープラネットのパスファインダーであるジェームズ・リースが、伝統的な京都のエリアと活気あふれる東京の都市を視覚的に旅する様子を紹介します。日本の豊かな文化遺産と現代の都市風景の対比を示し、訪れる人々に多様な体験を提供する国の魅力を強調しています。' where id = 'rRjKRLB1iTHMSBsdYOiXg';
update content_bodies set title = 'Japan: the old and the new - Lonely Planet travel video', description = 'Japan is ranked second in Lonely Planet''s Best in Travel for 2016, but it remains a top destination for travelers seeking unique experiences. In this video, James Rees, a Lonely Planet Pathfinder, takes viewers on a visual journey through two popular travel destinations: the traditional areas of Kyoto and the vibrant city of Tokyo. The video showcases the contrast between Japan''s rich cultural heritage and its modern urban landscape, highlighting the diverse experiences that the country offers to visitors.' where id = '_VFEkxN_19nz1Zm1xLjI-';
update content_bodies set title = '日本の文化を明らかにする - ロンリープラネットの旅行動画', description = 'ロンリープラネットは、3人の著名な旅行ブロガーを日本のさまざまな文化的側面を探るために派遣しました。彼らは、能楽や侍の庭といった伝統的な要素から、現代アートの洗練されたギャラリーまで掘り下げています。登場するブロガーは、アリシア・ドリュウニッキ、カシュ・バタチャリヤ、アビゲイル・キングです。日本についての詳細や、フィンエアーの往復航空券が当たるチャンスについては、提供されたウェブサイトを訪れてください。' where id = 'Lj5bRD1mEceVlUyAVkmlQ';
update content_bodies set title = 'Japan Revealed: Culture - Lonely Planet travel videos', description = 'Lonely Planet has sent three prominent travel bloggers to explore various cultural aspects of Japan. They delve into traditional elements such as noh theatre and samurai gardens, as well as contemporary art galleries. The featured bloggers include Alicia Drewnicki, Kash Bhattacharya, and Abigail King. For more information about Japan and a chance to win a round-trip ticket to Japan with Finnair, visit the provided website.' where id = 'UrX7FHhNxSQPVVKuNbj6V';
update content_bodies set title = '東京のあまり知られていない地域を発見する', description = '東京は、秋葉原のネオン輝く通りから、谷中の静かな路地まで、多様な地域が織りなす豊かなタペストリーです。ロンリープラネットのクリスチャン・ボネットがこれらの地域を評価しています。谷中についての詳細は、Omakase ToursやGallery Okuboを参照してください。このコンテンツは、東京観光コンベンションビューローのためにロンリープラネットが制作したものであり、編集の独立性と公正性を反映しています。' where id = 'xD-UJbGz2de1fJCFRF1tS';
update content_bodies set title = 'Discover Tokyo''s lesser known neighbourhoods', description = 'Tokyo is a vibrant city with a variety of neighborhoods, from the bustling, neon-lit streets of Akihabara to the tranquil, narrow alleyways of Yanaka. Cristian Bonetto from Lonely Planet explores these diverse areas, highlighting their unique characteristics. For more information about Yanaka, resources such as Omakase Tours and Gallery Okubo are recommended. This content is produced by Lonely Planet for the Tokyo Convention Visitors Bureau, maintaining the organization''s commitment to editorial independence and impartiality.' where id = 'j-fCLg_J6-E2Rxf1-s1tW';
update content_bodies set title = '日本の旅館に泊まる前に見るべきこと', description = '伝統的な日本の旅館は、癒しの温泉、快適な浴衣、地元文化に根ざした静かな雰囲気を提供し、2026年のロンリープラネットの「ベスト・イン・トラベル」リストに掲載されています。ホストのパトリシア・オコナーは、富士山の麓にある美しい旅館を訪れ、近くのアラクラ神社や癒しの里村も探索します。旅行のインスピレーションを得るために、ロンリープラネットの「ベスト・イン・トラベル」目的地と体験の完全なリストを訪れてください。' where id = 'r3MujIzPZ4ah4KshBdsAF';
update content_bodies set title = 'Watch This BEFORE You Stay In Japan’s Ryokans', description = 'Traditional Japanese ryokans provide a unique escape, featuring relaxing onsen baths, comfortable yukata robes, and a tranquil atmosphere rich in local culture. They are highlighted in Lonely Planet’s 2026 Best In Travel list as top travel experiences for the upcoming year. Host Patricia O’Connor explores a beautiful ryokan located at the base of Mount Fuji, along with nearby attractions such as the Arakura Shrine and Iyashi no Sato village. For more travel inspiration, visit Lonely Planet''s full list of Best In Travel destinations and experiences.' where id = 'uug8rM-2qbqYpvEPMYao0';
update content_bodies set title = '出典から: 日本の地元料理を探る', description = 'Lonely Planetのライターで東京在住のレベッカ・ミルナーは、日本の3つの異なる場所を訪れ、各地特有の地元料理を発見する食の冒険に出かけます。山形の伝統的な里芋のシチューから、都市札幌の有名なジンギスカンレストランまで、彼女は日本の多様な料理を探求します。この探検は、読者にこれらの料理を自宅で楽しむためのレシピやインスピレーションを提供することを目的としており、Lonely Planetの最新の「出典から」タイトルに掲載されています。' where id = 'hGP3XuTtJJNoM9QrWE8C8';
update content_bodies set title = 'From the Source: exploring the local cuisine of Japan', description = 'Rebecca Milner, a writer for Lonely Planet and resident of Tokyo, embarks on a culinary journey across three distinct locations in Japan. She aims to uncover the unique local dishes that define each area, including the traditional taro stews of Yamagata and the renowned Genghis Khan restaurants found in urban Sapporo. This exploration not only highlights the diversity of Japanese cuisine but also offers readers recipes and inspiration for enjoying these dishes at home, as featured in the latest ''From the Source'' title by Lonely Planet.' where id = 'tcySUFhFT_VwoMJf3ws-b';
update content_bodies set title = '2016年アジアの旅行先トップ: 日本・北海道 - Lonely Planet', description = '次の12ヶ月にアジアでどこに行くか決められない方へ、Lonely Planetのライターたちがアジアの魅力的な都市を探訪し、熱帯雨林をトレッキングし、豊かな海で泳いで、見逃せないスポットを見つけました。その結果、旅行者に新たな魅力を提供する定番の目的地や、アクティビティ満載の地域、あまり知られていない場所のリストが完成しました。今年のトップに選ばれたのは、日本の北海道です。他の目的地については、Lonely Planetのウェブサイトを訪れてください。' where id = 'k75iV89nuTAW-QMEjOO5i';
update content_bodies set title = 'The top place to travel in Asia in 2016: Hōkkaido, Japan - Lonely Planet', description = 'Lonely Planet writers have scoured Asia to find the most exciting travel destinations for the coming year. They have explored vibrant cities, trekked through jungles, and swum in beautiful seas to compile a list of must-visit places. This year, Hōkkaido in Japan has been named the top destination. The list includes a mix of classic spots with a new twist, action-packed regions, and lesser-known locations that travelers may not be familiar with. For more details on other destinations, visit the Lonely Planet website.' where id = 'tmpTaFGBUdoAovBJmCqoj';
update content_bodies set title = '日本の魅力：食と飲み物 - ロンリープラネットの旅行動画', description = 'ロンリープラネットは、3人の著名な旅行ブロガーを日本各地に派遣し、地域の食と飲み物の特産品を探求します。新潟の伝統的な酒造り、京都の家庭料理であるおばんざい、東京の焼き鳥の香ばしいグリルなど、日本の美味しい料理を紹介します。ブロガーにはアリシア・ドリュニッキ、カシュ・バタチャリヤ、アビゲイル・キングが含まれています。日本についての詳細や、フィンエアーの往復航空券が当たるチャンスについては、提供されたリンクを訪れてください。' where id = 'ptB28AWvqzdzvqBBhKzsj';
update content_bodies set title = 'Japan Revealed: Food & Drink - Lonely Planet travel videos', description = 'Lonely Planet features three prominent travel bloggers exploring Japan''s regional food and drink specialties. They delve into Niigata''s traditional sake brewing, Kyoto''s homestyle obanzai ryori, and the crisp grilling of yakitori in Tokyo, among other culinary delights. The bloggers include Alicia Drewnicki, Kash Bhattacharya, and Abigail King. For more information about Japan and a chance to win a round-trip ticket with Finnair, visit the provided link.' where id = 'LHOSfJNSRgvaAM5mlHQfk';
update content_bodies set title = '日本の魅力：観光名所とアクティビティ - ロンリープラネットの旅行動画', description = 'ロンリープラネットは、3人の著名な旅行ブロガーを日本に派遣し、国内の観光名所やアクティビティを探求しました。彼らの旅は、人気の観光地からあまり知られていないスポットまで多岐にわたります。奈良の巨大な東大寺の影で鹿に餌を与えたり、金沢の芸妓の家を訪れたり、東京のレトロなビデオゲーム店を探索したりする様子が紹介されています。参加したブロガーは、アリシア・ドリュニッキ、カシュ・バタチャリヤ、アビゲイル・キングです。' where id = 'yAx8DTyjZ30FDywE2qFxw';
update content_bodies set title = 'Japan Revealed: Sights & Activities - Lonely Planet travel videos', description = 'Lonely Planet has sent three prominent travel bloggers to Japan to explore various sights and activities across the country. Their journey includes both popular tourist destinations and lesser-known attractions. Highlights of their adventure include feeding deer near the impressive Todai-ji Buddha in Nara, visiting a geisha house in Kanazawa, and delving into Tokyo''s vintage video game shops. The bloggers featured in this exploration are Alicia Drewnicki, Kash Bhattacharya, and Abigail King.' where id = 'WGdinsOavSfuI6buXX1cU';
update content_bodies set title = '日本の魅力 - ロンリープラネットの旅行動画', description = 'ロンリープラネットは、3人の旅行ブロガーを日本に派遣し、食文化や見逃せない観光スポットを探求しました。彼らが発見したことの一部を紹介する動画です。参加しているブロガーは、アリシア・ドリュニッキ、カシュ・バタチャリヤ、アビゲイル・キングです。日本についての詳細や、フィンエアーの往復航空券が当たるチャンスについては、指定されたウェブサイトを訪れてください。' where id = 'pN6Kmig8j2rkK-p1725hk';
update content_bodies set title = 'Japan Revealed - Lonely Planet travel videos', description = 'Three travel bloggers were sent to Japan to explore its food, culture, and must-see attractions. The video showcases their discoveries and experiences in the country. Featured bloggers include Alicia Drewnicki, Kash Bhattacharya, and Abigail King. For more information about Japan and a chance to win a round-trip ticket to Japan with Finnair, visit the provided website.' where id = '2QK3tHSQEwip1foIwS0eU';
update content_bodies set title = '美術館への誘い', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介します。それぞれの美術館の豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。テーマは、Ⅰ：自然とともにある美術館、Ⅱ：建築家が自作を語る美術館、Ⅲ：アーティストのための美術館／アーティストによる美術館、Ⅳ：デザインを新しい視点から発信する美術館です。最初のテーマでは、自然と深く結びついた6つのアートスポットを紹介し、それぞれの立地や周辺環境、館内の庭園に焦点を当てています。' where id = 'RZfbhph8MT-P5ZNYbAPMC';
update content_bodies set title = 'Invitation to Explore Japan''s Museums-Moerenuma Park', description = 'Japan is home to numerous unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Viewers can enjoy the world of Japanese art through the rich collections and outstanding architecture of these institutions. The themes include: 1) Museums in harmony with nature, 2) Museums where architects discuss their own works, 3) Museums for artists and by artists, and 4) Museums presenting design from new perspectives. The first theme focuses on six art spots deeply connected to nature, highlighting their locations, surrounding environments, and gardens within the museums.' where id = 'z1GKU36vfLEO-sEIcyKzJ';
update content_bodies set title = '【美術館への誘い】1-2. 札幌芸術の森', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介します。それぞれの美術館の豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。テーマは、1) 自然とともにある美術館、2) 建築家が自作を語る美術館、3) アーティストのための美術館／アーティストによる美術館、4) デザインを新しい視点から発信する美術館です。第1テーマでは、自然と深く結びついた6つのアートスポットを紹介し、それぞれの立地や環境、館内の庭園に焦点を当てています。' where id = 'zSzm73_W8ZfCGZA7BaLmK';
update content_bodies set title = 'Invitation to Explore Japan''s Museums-Sapporo Art Park', description = 'Japan is home to numerous unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Viewers can enjoy the rich collections and outstanding architecture that showcase the world of Japanese art. The themes include: 1) Museums in harmony with nature, 2) Museums where architects discuss their own works, 3) Museums for artists and by artists, and 4) Museums presenting design from new perspectives. The first theme focuses on six art spots deeply connected to nature, highlighting their locations, surroundings, and gardens.' where id = 'EXLyR6vjp8iENKG8IgN7P';
update content_bodies set title = '【美術館への誘い】1-3. 清春芸術村', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介します。それぞれの美術館は、豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。テーマは、1) 自然とともにある美術館、2) 建築家が自作を語る美術館、3) アーティストのための美術館／アーティストによる美術館、4) デザインを新しい視点から発信する美術館です。最初のテーマでは、自然と深く結びついた6つのアートスポットを紹介し、それぞれの立地や環境、館内の庭園に焦点を当てています。' where id = 'mV8P-BUQWOHi-8N_iU5U8';
update content_bodies set title = 'Invitation to Explore Japan''s Museums-Kiyoharu Art Colony', description = 'Japan is home to numerous unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Viewers can enjoy the rich collections and outstanding architecture that showcase the world of Japanese art. The themes include: 1) Museums in harmony with nature, 2) Museums where architects discuss their own works, 3) Museums for artists and by artists, and 4) Museums presenting design from new perspectives. The first theme focuses on six art spots deeply connected to nature, highlighting their locations, surroundings, and gardens.' where id = 'FWVTxjgHw8NwcQc5ln6P6';
update content_bodies set title = '美術館への誘い - 島根県立美術館', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館を4つのテーマに分けて紹介し、合計24館を取り上げます。それぞれの美術館の豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。テーマは、1) 自然とともにある美術館、自然環境と深く結びついた6つのアートスポットを紹介; 2) 建築家が自作を語る美術館; 3) アーティストのための美術館／アーティストによる美術館; 4) 新しい視点からデザインを発信する美術館です。このシリーズは、日本の多様なアートシーンを包括的に探求することを目的としています。' where id = 'rhD-YsdSRujLx1rpHHKzn';
update content_bodies set title = 'Invitation to Explore Japan''s Museums - Shimane Art Museum', description = 'Japan is home to numerous unique and captivating art museums. This video series introduces 24 museums across the country, categorized into four themes. Viewers can enjoy the rich collections and outstanding architecture that showcase the world of Japanese art. The themes include: 1) Museums in harmony with nature, focusing on six art spots deeply connected to their natural surroundings; 2) Museums where architects discuss their own works; 3) Museums created for artists or by artists; and 4) Museums that present design from new perspectives. The series aims to provide a comprehensive exploration of Japan''s diverse art scene.' where id = 'bzmKoAMRJLxGdL6sJXSlg';
update content_bodies set title = '【美術館への誘い】1-5. 足立美術館', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介します。それぞれの美術館は、豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。テーマは、自然とともにある美術館、建築家が自作を語る美術館、アーティストのための美術館／アーティストによる美術館、デザインを新しい視点から発信する美術館です。特に「自然とともにある美術館」では、自然と深く結びついた6つのアートスポットを紹介しています。' where id = '-NArue7ylH6IsHTGON-6s';
update content_bodies set title = 'Invitation to Explore Japan''s Museums-Adachi Museum of Art', description = 'Japan is home to numerous unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Viewers can enjoy the rich collections and outstanding architecture that showcase the world of Japanese art. The themes include: 1) Museums in harmony with nature, highlighting six art spots deeply connected to their natural surroundings; 2) Museums where architects discuss their own works; 3) Museums created for artists or by artists; and 4) Museums presenting design from new perspectives. The series aims to provide a comprehensive exploration of Japan''s artistic landscape.' where id = '4gReaqwr6BisHjisTPyT4';
update content_bodies set title = '【美術館への誘い】1-6. 霧島アートの森', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介します。それぞれの美術館は、豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。テーマは、1) 自然とともにある美術館、2) 建築家が自作を語る美術館、3) アーティストのための美術館／アーティストによる美術館、4) デザインを新しい視点から発信する美術館です。最初のテーマでは、自然と深く結びついた6つのアートスポットを紹介し、それぞれの立地や環境、館内の庭園に焦点を当てています。' where id = 'ciRMdYFjW_bqg9DC7fq7P';
update content_bodies set title = 'Invitation to Explore Japan''s Museums-Kirishima Open-Air Museum', description = 'Japan is home to numerous unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Viewers can enjoy the rich collections and outstanding architecture that showcase the world of Japanese art. The themes include: 1) Museums in harmony with nature, 2) Museums where architects discuss their own works, 3) Museums for artists and by artists, and 4) Museums presenting design from new perspectives. The first theme focuses on six art spots deeply connected to nature, highlighting their locations, surroundings, and gardens.' where id = 'FusHBsYygz_HWmWf6pT5Z';
update content_bodies set title = '【美術館への誘い】2-1. 青森県立美術館：青木淳', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介します。それぞれの美術館の豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。テーマは、Ⅰ：自然とともにある美術館、Ⅱ：建築家が自作を語る美術館、Ⅲ：アーティストのための美術館／アーティストによる美術館（8月15日配信予定）、Ⅳ：デザインを新しい視点から発信する美術館（8月22日配信予定）です。Ⅱのテーマでは、建築家が自らの設計コンセプトや特徴、美術館への想いを語る6つの美術館を紹介します。' where id = 'mhGouUBY9a8ab0FknJQX5';
update content_bodies set title = 'Invitation to Explore Japan''s Museums - Aomori Museum of Art', description = 'Japan is home to numerous unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Viewers can enjoy the rich collections and outstanding architecture that showcase the world of Japanese art. The themes include: Ⅰ: Museums in Harmony with Nature, Ⅱ: Museums Where Architects Discuss Their Works, Ⅲ: Museums for Artists / By Artists (scheduled for August 15), and Ⅳ: Museums Presenting Design from New Perspectives (scheduled for August 22). The second theme highlights six notable museum architectures, where the architects themselves share their design concepts, features, and thoughts about the museums.' where id = 'sZ_jBWZKkgXIlXI8VKx3f';
update content_bodies set title = '【美術館への誘い】2-2. 太田市美術館・図書館：平田晃久', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介します。それぞれの美術館の豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。テーマは、Ⅰ：自然とともにある美術館、Ⅱ：建築家が自作を語る美術館、Ⅲ：アーティストのための美術館／アーティストによる美術館（8月15日配信予定）、Ⅳ：デザインを新しい視点から発信する美術館（8月22日配信予定）です。Ⅱでは、建築家が設計のコンセプトや特徴、美術館への想いを語る6つの美術館を紹介します。' where id = 'v4RBeKKbccjB9YrVJJ_ot';
update content_bodies set title = 'Invitation to Explore Japan''s Museums-Art Museum & Library, Ota', description = 'Japan is home to many unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Viewers can enjoy the rich collections and outstanding architecture that showcase the world of Japanese art. The series includes: I. Museums in Harmony with Nature, II. Museums Where Architects Discuss Their Works, III. Museums for Artists/By Artists (scheduled for release on August 15), and IV. Museums Presenting Design from New Perspectives (scheduled for release on August 22). The second theme focuses on six notable museums where architects share their design concepts, features, and thoughts about the museums.' where id = '9O1PzEPkaLrehC4hUaYnh';
update content_bodies set title = '【美術館への誘い】2-3. 根津美術館：隈研吾', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介します。それぞれの美術館は、豊かなコレクションと優れた建築を通じて、日本のアートの世界を楽しむことができます。テーマは、Ⅰ：自然とともにある美術館、Ⅱ：建築家が自作を語る美術館、Ⅲ：アーティストのための美術館／アーティストによる美術館（8月15日配信予定）、Ⅳ：デザインを新しい視点から発信する美術館（8月22日配信予定）です。Ⅱのテーマでは、建築家が自らの設計コンセプトや美術館への想いを語る6つの美術館を紹介します。' where id = 'y015lnNbRLxmVzRQVUETX';
update content_bodies set title = 'Invitation to Explore Japan''s Museums - Nezu Museum', description = 'Japan is home to many unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Each museum showcases its rich collection and outstanding architecture, allowing viewers to enjoy the world of Japanese art. The series includes: I. Museums in Harmony with Nature, II. Museums Where Architects Discuss Their Works, III. Museums for Artists / By Artists (scheduled for August 15), and IV. Museums Presenting Design from New Perspectives (scheduled for August 22). The second theme highlights six notable museums, where the architects themselves share their design concepts, features, and thoughts about the museums.' where id = 'eiEzvCIgZbRc9f7T9is0S';
update content_bodies set title = '金沢21世紀美術館', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介します。それぞれの美術館は、豊かなコレクションと優れた建築を通じて、日本のアートの世界を楽しむことができます。シリーズには、自然と共存する美術館、建築家が自作を語る美術館、アーティストのための美術館、デザインを新しい視点から発信する美術館が含まれています。第2テーマでは、建築家が設計のコンセプトや特徴、思いを語る6つの美術館が紹介されます。' where id = 'HZRaKCAERDjMR_MZTXUHT';
update content_bodies set title = '21st Century Museum of Contemporary Art, Kanazawa', description = 'Japan is home to many unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Each museum showcases its rich collection and outstanding architecture, allowing viewers to enjoy the world of Japanese art. The series includes themes such as museums in harmony with nature, museums where architects discuss their own works, artist-centric museums, and museums presenting design from new perspectives. The second theme focuses on six notable museums where architects share their design concepts, features, and thoughts about the museums.' where id = '2ihGDGvpUM5I4Pt3OkId5';
update content_bodies set title = '【美術館への誘い】2-5. 秋野不矩美術館：藤森照信', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介します。それぞれの美術館は、豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむ機会を提供します。テーマは、Ⅰ：自然とともにある美術館、Ⅱ：建築家が自作を語る美術館、Ⅲ：アーティストのための美術館／アーティストによる美術館（8月15日配信予定）、Ⅳ：デザインを新しい視点から発信する美術館（8月22日配信予定）です。Ⅱのテーマでは、建築家が自らの設計コンセプトや特徴、美術館に対する想いを語る6つの美術館を紹介します。' where id = 'Wg5IVYwXUOoekG4-dxBOO';
update content_bodies set title = 'Invitation to Explore Japan''s Museums - Akino Fuku Museum', description = 'Japan is home to numerous unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Each museum showcases its rich collection and outstanding architecture, allowing viewers to enjoy the world of Japanese art. The themes include: Ⅰ: Museums in Harmony with Nature, Ⅱ: Museums Where Architects Discuss Their Works, Ⅲ: Museums for Artists / By Artists (scheduled for August 15), and Ⅳ: Museums Presenting Design from New Perspectives (scheduled for August 22). The second theme highlights six notable museums where architects share their design concepts, features, and thoughts about the museums.' where id = 'GqHYqlbTo1hrRITIYgo4P';
update content_bodies set title = '【美術館への誘い】2-6. 豊田市美術館：谷口吉生', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介します。それぞれの美術館の豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。テーマは、Ⅰ：自然とともにある美術館、Ⅱ：建築家が自作を語る美術館、Ⅲ：アーティストのための美術館／アーティストによる美術館（8月15日配信予定）、Ⅳ：デザインを新しい視点から発信する美術館（8月22日配信予定）です。Ⅱのテーマでは、建築家が自らの設計について語る6つの美術館を紹介します。' where id = 'uzKdxtejiWGnz96ArlC_p';
update content_bodies set title = 'Invitation to Explore Japan''s Museums-Toyota Municipal Museum of Art', description = 'Japan is home to numerous unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Viewers can enjoy the rich collections and outstanding architecture that showcase the world of Japanese art. The series includes: I. Museums in Harmony with Nature, II. Museums Where Architects Discuss Their Works, III. Museums for Artists/By Artists (scheduled for release on August 15), and IV. Museums Presenting Design from New Perspectives (scheduled for release on August 22). The second theme highlights six notable museums, where the architects themselves share insights about their design concepts, features, and their thoughts on the museums.' where id = 'WgggLimCJoMDohXvanfw0';
update content_bodies set title = '美術館への誘い - 土門拳記念館', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介します。各美術館の豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。テーマには、自然と共にある美術館、建築家が自作を語る美術館、アーティストのための美術館やアーティストによる美術館が含まれています。このエピソードでは、山形県酒田市にある土門拳記念館が紹介されており、著名な写真家土門拳に捧げられた美術館です。彼の芸術的遺産を知ることができる貴重な場所です。' where id = 'FwlAzrD6iDfRpQIV6ZclW';
update content_bodies set title = 'Invitation to Explore Japan''s Museums - Ken Domon Museum of Photography', description = 'Japan is home to many unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Viewers can enjoy the rich collections and outstanding architecture that showcase the world of Japanese art. The series includes themes such as museums in harmony with nature, museums where architects discuss their own works, and museums dedicated to artists or established by artists themselves. In this episode, the Ken Domon Museum of Photography is featured, located in Sakata City, Yamagata Prefecture. The museum is dedicated to the renowned photographer Ken Domon and offers insights into his artistic legacy.' where id = 'CzfEr1NunTzYgFGGRYz9l';
update content_bodies set title = '【美術館への誘い】3-2. 草間彌生美術館', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館を4つのテーマに分けて紹介し、合計24館を取り上げています。それぞれの美術館は、豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。テーマの一つである「アーティストのための美術館／アーティストによる美術館」では、一人のアーティストに捧げられた美術館や、アーティスト自身が設立した美術館を6館紹介しています。' where id = '-AuN2huSthqN7uXGhq8tM';
update content_bodies set title = 'Invitation to Explore Japan''s Museums - Yayoi Kusama Museum', description = 'Japan is home to many unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Each museum showcases rich collections and outstanding architecture, allowing viewers to enjoy the world of Japanese art. The theme ''Museums for Artists / Museums by Artists'' features six museums dedicated to a single artist or established by the artists themselves. The series includes a playlist with multilingual subtitles for a broader audience.' where id = 'koWt6wxH8wGU22vun-Lcv';
update content_bodies set title = '【美術館への誘い】すみだ北斎美術館', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介しています。それぞれの美術館は、豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。特に「アーティストのための美術館／アーティストによる美術館」では、個々のアーティストに捧げられた美術館やアーティスト自身が設立した美術館を6館紹介しています。すみだ北斎美術館は、東京に位置し、著名なアーティスト葛飾北斎の作品を称える美術館です。このシリーズを通じて、さまざまな美術館を訪れることで、アートへの理解を深めることができます。' where id = '6gK0pWUtm9Xa0vCYXl3hg';
update content_bodies set title = 'Invitation to Explore Japan''s Museums - The Sumida Hokusai Museum', description = 'Japan is home to numerous unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Viewers can enjoy the rich collections and outstanding architecture that showcase the world of Japanese art. The series includes museums dedicated to individual artists or established by artists themselves, with a total of six featured in the third theme. The Sumida Hokusai Museum, located in Tokyo, is one of these highlights, celebrating the works of the renowned artist Katsushika Hokusai. The series aims to provide a deeper understanding of art through these diverse institutions.' where id = 'GYc0JmMWH2OHTZbu8hXdz';
update content_bodies set title = '小田原文化財団 江之浦測候所', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介しています。それぞれの美術館は、豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。テーマ「アーティストのための美術館／アーティストによる美術館」では、個々のアーティストに捧げられた美術館やアーティスト自身が設立した美術館を6館紹介しています。土門拳記念館、草間彌生美術館、すみだ北斎美術館、小田原文化財団江之浦測候所などが含まれています。' where id = 'WzPi_IRs4Ca7lw9Fhmy0L';
update content_bodies set title = 'Odawara Art Foundation Enoura Observatory', description = 'Japan is home to many unique and captivating art museums. This video series introduces 24 museums across the country, categorized into four themes. Each museum showcases rich collections and outstanding architecture, allowing viewers to enjoy the world of Japanese art. The theme ''Museums for Artists / Museums by Artists'' features six museums dedicated to individual artists or established by artists themselves. The series includes notable locations such as the Domon Ken Memorial Hall, Yayoi Kusama Museum, Sumida Hokusai Museum, and the Odawara Art Foundation Enoura Observatory, among others.' where id = 'oj-lXZGXByrs48mgD68kp';
update content_bodies set title = '美術館への誘い - 鈴木大拙館', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介します。それぞれの美術館は、豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。テーマは、Ⅰ：自然とともにある美術館、Ⅱ：建築家が自作を語る美術館、Ⅲ：アーティストのための美術館／アーティストによる美術館、Ⅳ：デザインを新しい視点から発信する美術館です。特に、Ⅲでは、個々のアーティストに捧げられた美術館やアーティスト自身が設立した美術館を6館紹介しており、鈴木大拙館もその一つです。' where id = 'MBa35uQrJqe18sLmVrvOA';
update content_bodies set title = 'Invitation to Explore Japan''s Museums - D. T. Suzuki Museum', description = 'Japan is home to numerous unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Each museum showcases rich collections and outstanding architecture, allowing viewers to enjoy the world of Japanese art. The themes include: Ⅰ: Museums in Harmony with Nature, Ⅱ: Museums Where Architects Discuss Their Works, Ⅲ: Museums for Artists / Museums by Artists, and Ⅳ: Museums Presenting Design from New Perspectives. The third theme features six museums dedicated to individual artists or established by artists themselves, including the D. T. Suzuki Museum in Kanazawa.' where id = '5aSc9UnaupXuGlkCy5QP7';
update content_bodies set title = '美術館への誘い', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介します。それぞれの美術館は、豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。テーマは、Ⅰ：自然とともにある美術館、Ⅱ：建築家が自作を語る美術館、Ⅲ：アーティストのための美術館／アーティストによる美術館、Ⅳ：デザインを新しい視点から発信する美術館です。特にⅢでは、アーティストに捧げられた美術館やアーティスト自身が設立した美術館を6館紹介しています。' where id = 'PJH1G4Xo8gkV_CBEDtOsU';
update content_bodies set title = 'Invitation to Explore Japan''s Museums - Site of Reversible Destiny-Yoro Park', description = 'Japan is home to numerous unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Each museum showcases rich collections and outstanding architecture, allowing viewers to enjoy the world of Japanese art. The themes include: I. Museums in harmony with nature, II. Museums where architects discuss their own works, III. Museums dedicated to artists or established by artists, and IV. Museums presenting design from new perspectives. The third theme features six museums dedicated to individual artists or founded by them, highlighting their contributions to the art world.' where id = 'm6QkUakojV0iK-eHQKdOg';
update content_bodies set title = '美術館への誘い - 21_21 DESIGN SIGHT', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介します。それぞれの美術館を通じて、日本のアートの世界を楽しむことができます。テーマは、Ⅰ：自然とともにある美術館、Ⅱ：建築家が自作を語る美術館、Ⅲ：アーティストのための美術館／アーティストによる美術館、Ⅳ：デザインを新しい視点から発信する美術館です。特に第4テーマでは、最先端のプロダクツやグラフィック、伝統工芸、民藝、家具、道具などに関するユニークな活動を行っている6つの美術館を紹介しています。多言語字幕付きのプレイリストも用意されています。' where id = 'xWInSrfGZjfwwTow9ewOm';
update content_bodies set title = 'Invitation to Explore Japan''s Museums - 21_21 DESIGN SIGHT', description = 'Japan is home to numerous unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Viewers can enjoy the rich collections and outstanding architecture that showcase the world of Japanese art. The themes include: I. Museums in Harmony with Nature, II. Museums Where Architects Discuss Their Works, III. Museums for Artists / Museums by Artists, and IV. Museums Presenting Design from New Perspectives. The fourth theme highlights six museums engaged in unique activities related to cutting-edge products, graphics, traditional crafts, folk art, furniture, and tools. A multilingual playlist is available for viewing.' where id = 'JBNE4Su5WFJCIWV2Qent-';
update content_bodies set title = '【美術館への誘い】4-2. 日本民藝館', description = '日本には、個性的で魅力的な美術館が数多く存在します。本ビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介しています。それぞれの美術館は、豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。第4テーマでは、デザインを新しい視点から発信する美術館に焦点を当て、最先端のプロダクツやグラフィック、伝統工芸、民藝、家具、道具などに関するユニークな活動を行っている6つの美術館を紹介しています。シリーズは多言語字幕付きで視聴可能です。' where id = 'wQEtJMgiv-KlFgqZ4m6ZD';
update content_bodies set title = 'Invitation to Explore Japan''s Museums - The Japan Folk Crafts Museum', description = 'Japan is home to numerous unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Each museum showcases rich collections and outstanding architecture, allowing viewers to enjoy the world of Japanese art. The fourth theme focuses on museums that present design from new perspectives, featuring six museums engaged in unique activities related to cutting-edge products, graphics, traditional crafts, folk art, furniture, and tools. The series is available with multilingual subtitles.' where id = 'snz4MddkA3e2rlUwrNyp4';
update content_bodies set title = '【美術館への誘い】4-5. 大阪中之島美術館', description = '日本には、個性的で魅力的な美術館が数多く存在します。このビデオシリーズでは、全国の美術館24館を4つのテーマに分けて紹介しています。各美術館の豊かなコレクションや優れた建築を通じて、日本のアートの世界を楽しむことができます。テーマは、Ⅰ：自然とともにある美術館、Ⅱ：建築家が自作を語る美術館、Ⅲ：アーティストのための美術館／アーティストによる美術館、Ⅳ：デザインを新しい視点から発信する美術館です。特に、デザインを新しい視点から発信する美術館では、最先端のプロダクツやグラフィック、伝統工芸、民藝、家具、道具などに焦点を当てた6つの美術館を紹介しています。' where id = 'OdL1KwWLQjFI07g4SxisQ';
update content_bodies set title = 'Invitation to Explore Japan''s Museums - Nakanoshima Museum of Art, Osaka', description = 'Japan is home to numerous unique and captivating museums. This video series introduces 24 museums across the country, categorized into four themes. Viewers can enjoy the rich collections and outstanding architecture that showcase the world of Japanese art. The themes include: Ⅰ: Museums in harmony with nature, Ⅱ: Museums where architects discuss their works, Ⅲ: Museums for artists and by artists, and Ⅳ: Museums presenting design from new perspectives. The fourth theme highlights six museums engaged in unique activities across various genres, including cutting-edge products, graphics, traditional crafts, folk art, furniture, and tools. A playlist featuring the theme ''Museums presenting design from new perspectives'' is available with multilingual subtitles.' where id = 'Z2p7V6cXPasNv57iUHoF5';
