update content_bodies set title = '【新型パンフレット動画】温泉', description = 'この動画は新型パンフレットにおける温泉の紹介を行っています。温泉の魅力や特徴を視覚的に伝える内容となっており、視聴者に温泉の楽しさやリラックス効果を感じてもらうことを目的としています。新型パンフレットの一環として制作されたこの動画は、温泉の魅力をより多くの人々に伝えるための重要なツールです。' where id = '0zRl_CZTr5EEkzdgGolEv';
update content_bodies set title = 'New Pamphlet Video: Hot Springs', description = 'This video introduces hot springs as part of the new pamphlet.' where id = 'QUkAIkA_3kZMAznLUZM3v';
